// Truth Completeness regression — detects "code has a writer the Architecture Truth doesn't know".
// Static, symbol-level reconciliation for the highest-risk resources (client_matches, platform_*,
// live_timers). Never modifies anything.
//
// Detection model (documented boundaries — we do NOT claim 100% coverage):
//   Rule 1 (file level): every file under server/ containing a literal DML statement on a target
//            table must appear in that resource's index evidence. Catches NEW writers in NEW files.
//   Rule 2 (code→index, symbol level): in the flat exported-function DAL files, any exported
//            function whose body contains target-table DML must be named by some index writer
//            target. Catches NEW write functions in EXISTING allowlisted files (the TE-2 class).
//   Rule 3 (index→code, symbol level): every write symbol recorded in index writer targets must
//            still exist in code. Catches STALE index evidence (deleted code still claimed).
//   NOT covered: dynamically composed SQL (string interpolation of table names), non-exported
//   wrappers, writes executed through generic query helpers with runtime-built SQL.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const INDEX = JSON.parse(fs.readFileSync(path.join(ROOT, ".ai", "architecture", "index.json"), "utf8"));
const INDEX_TEXT = JSON.stringify(INDEX);

const TARGETS = {
  client_matches: { dml: /(?:UPDATE|INSERT\s+INTO|DELETE\s+FROM)\s+client_matches\b/gi },
  platform_matches: { dml: /(?:UPDATE|INSERT\s+INTO|DELETE\s+FROM)\s+platform_matches\b/gi },
  platform_bets: { dml: /(?:UPDATE|INSERT\s+INTO|DELETE\s+FROM)\s+platform_bets\b/gi },
  live_timers: { dml: /(?:UPDATE|INSERT\s+INTO|DELETE\s+FROM)\s+live_timers\b/gi },
};

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (e.name === "node_modules" || e.name.startsWith(".")) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) walk(p, out);
    else if (/\.(js|mjs|ts)$/.test(e.name)) out.push(p);
  }
  return out;
}
// Comments belong to the NEXT function; strip them before attribution so JSDoc mentioning
// DML (e.g. "DELETE ... client_matches") is not blamed on the preceding function.
function stripComments(src) {
  return src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/(^|\n)[ \t]*\/\/[^\n]*/g, "");
}
// Split a (comment-stripped) file into function chunks at every line-start function boundary
// (exported or not), so non-exported helpers break chunks correctly. Only exported functions
// are attributed (internal helpers are covered via their exported wrappers — documented boundary).
function exportedFunctionChunks(cleanText) {
  const re = /^(export\s+)?(?:async\s+)?function\s+(\w+)/gm;
  const marks = [];
  for (const m of cleanText.matchAll(re)) {
    marks.push({ exported: Boolean(m[1]), name: m[2], start: m.index, end: 0 });
  }
  marks.forEach((mk, i) => { mk.end = i + 1 < marks.length ? marks[i + 1].start : cleanText.length; });
  return marks.filter((mk) => mk.exported);
}
const codeFiles = walk(path.join(ROOT, "server"));
const corpus = new Map(codeFiles.map((p) => [p, fs.readFileSync(p, "utf8")]));

function indexEvidencePaths(resourceKey) {
  const res = INDEX.resources[resourceKey];
  const set = new Set();
  if (!res) return set;
  for (const op of res.operations || []) {
    for (const w of op.writers || []) {
      for (const e of w.evidence || []) {
        const m = String(e).match(/^(.*?):[\d]+([,-][\d]+)*$/);
        set.add(m ? m[1] : String(e));
      }
    }
  }
  return set;
}
function indexWriterSymbols(resourceKey) {
  const res = INDEX.resources[resourceKey];
  const syms = new Set();
  if (!res) return syms;
  for (const op of res.operations || []) {
    for (const w of op.writers || []) {
      for (const m of String(w.target).matchAll(/\b((?:write|insert|update|patch|delete|clear|swap|force|prune|mark|archive|replace|save|set|upsert)[A-Z]\w+)\b/g)) {
        syms.add(m[1]);
      }
    }
  }
  return syms;
}

let failures = 0;
const report = [];
for (const [table, cfg] of Object.entries(TARGETS)) {
  const dmlRe = new RegExp(cfg.dml.source, "i");
  const evidenceFiles = indexEvidencePaths(table);
  const indexSymbols = indexWriterSymbols(table);
  const codeSymbols = new Map(); // symbol -> file (write-export symbols found in code)
  const dmlFiles = new Set();

  for (const [abs, text] of corpus.entries()) {
    const rel = path.relative(ROOT, abs).replace(/\\/g, "/");
    if (dmlRe.test(text)) dmlFiles.add(rel);
    // Rule 2: flat exported functions whose body chunk mentions table DML
    if (rel.startsWith("server/db/")) {
      const clean = stripComments(text);
      for (const mk of exportedFunctionChunks(clean)) {
        const body = clean.slice(mk.start, mk.end);
        if (dmlRe.test(body)) codeSymbols.set(mk.name, rel);
      }
    }
  }

  const problems = [];
  // Rule 1
  for (const f of [...dmlFiles].sort()) {
    if (!evidenceFiles.has(f)) {
      problems.push(`GAP(file): ${f} has literal DML on ${table} but is absent from index evidence`);
    }
  }
  // Rule 2
  for (const [sym, file] of [...codeSymbols.entries()].sort()) {
    if (!INDEX_TEXT.includes(sym)) {
      problems.push(`GAP(symbol): ${sym} (${file}) writes ${table} but no index writer target names it`);
    }
  }
  // Rule 3
  const codeTextAll = [...corpus.values()].join("\n");
  for (const sym of [...indexSymbols].sort()) {
    if (!new RegExp(`\\b${sym}\\b`).test(codeTextAll)) {
      problems.push(`STALE(symbol): index records writer "${sym}" but it no longer exists in server/ code`);
    }
  }

  const status = problems.length === 0 ? "PASS" : "FAIL";
  if (problems.length > 0) failures++;
  report.push(`${status} ${table} (dmlFiles=${dmlFiles.size}, codeWriteSymbols=${codeSymbols.size}, indexWriterSymbols=${indexSymbols.size})`);
  for (const p of problems) report.push(`     ${p}`);
}

report.push("");
report.push("Detection boundary (honest limits): static literal-DML + flat exported-function scan only;");
report.push("dynamic SQL composition, non-exported wrappers, and runtime-built statements are NOT covered.");
report.push("This check catches the TE-2 class (new/changed writer unknown to the index), not every possible write path.");
console.log(report.join("\n"));
process.exit(failures === 0 ? 0 : 1);

#!/usr/bin/env node
/**
 * 从 monorepo 内 @changmen/venue-adapter/* 引用生成 package.json exports 白名单。
 * 扫描：client/web/src、packages/venue-adapter（含 vi.mock / dynamic import）。
 *
 * 用法：
 *   node packages/venue-adapter/scripts/sync-package-exports.mjs          # 写回 package.json
 *   node packages/venue-adapter/scripts/sync-package-exports.mjs --check  # 仅校验，有漂移 exit 1
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "../../..");
const ADAPTER_ROOT = path.resolve(__dirname, "../../../packages/venue-adapter");
const PKG_JSON = path.join(ADAPTER_ROOT, "package.json");
const PKG = "@changmen/venue-adapter";
const CHECK = process.argv.includes("--check");

const SCAN_ROOTS = [
  path.join(REPO_ROOT, "client", "web", "src"),
  ADAPTER_ROOT,
];

const IMPORT_RES = [
  new RegExp(`(?:from|import)\\s*(?:\\(?\\s*)?["']${PKG}/([^"']+)["']`, "g"),
  new RegExp(`import\\s*\\(\\s*["']${PKG}/([^"']+)["']\\s*\\)`, "g"),
  new RegExp(`vi\\.mock\\s*\\(\\s*["']${PKG}/([^"']+)["']`, "g"),
];

/** Browser and Node entries are retired; never regenerate runtime aliases here. */
const FIXED_EXPORTS = {};

function walk(dir, out = []) {
  for (const name of fs.readdirSync(dir)) {
    if (name === "node_modules" || name === "dist")
      continue;
    const p = path.join(dir, name);
    const st = fs.statSync(p);
    if (st.isDirectory())
      walk(p, out);
    else if (/\.(ts|tsx|vue|mjs|js)$/.test(name))
      out.push(p);
  }
  return out;
}

function resolveExportTarget(sub) {
  const rel = sub.replace(/\\/g, "/");
  const candidates = [
    `${rel}.ts`,
    `${rel}.tsx`,
    `${rel}/index.ts`,
    `${rel}.mjs`,
    `${rel}/index.mjs`,
  ];
  for (const c of candidates) {
    const abs = path.join(ADAPTER_ROOT, c);
    if (fs.existsSync(abs))
      return `./${c}`;
  }
  return null;
}

function collectSubpaths() {
  const subs = new Set();
  for (const root of SCAN_ROOTS) {
    if (!fs.existsSync(root))
      continue;
    for (const file of walk(root)) {
      const text = fs.readFileSync(file, "utf8");
      for (const re of IMPORT_RES) {
        re.lastIndex = 0;
        let m;
        while ((m = re.exec(text)) !== null)
          subs.add(m[1]);
      }
    }
  }
  return subs;
}

function buildExports() {
  const exports = { ...FIXED_EXPORTS };
  const missing = [];
  for (const sub of [...collectSubpaths()].sort()) {
    if (!Object.hasOwn(FIXED_EXPORTS, `./${sub}`)) {
      console.error(`Browser entry retired: @changmen/venue-adapter/${sub}; use @changmen/venue-browser/adapter.`);
      process.exit(1);
    }
    const target = resolveExportTarget(sub);
    if (!target) {
      missing.push(sub);
      continue;
    }
    exports[`./${sub}`] = target;
  }
  if (missing.length) {
    console.error("sync-package-exports: 无法解析以下子路径到磁盘文件：");
    for (const m of missing)
      console.error(`  ./${m}`);
    process.exit(1);
  }
  return exports;
}

function sortedExportsObject(exports) {
  const out = {};
  for (const key of Object.keys(exports).sort())
    out[key] = exports[key];
  return out;
}

function readCurrentExports() {
  const pkg = JSON.parse(fs.readFileSync(PKG_JSON, "utf8"));
  return pkg.exports ?? {};
}

function exportsEqual(a, b) {
  const ka = Object.keys(a).sort();
  const kb = Object.keys(b).sort();
  if (ka.length !== kb.length)
    return false;
  return ka.every((k, i) => k === kb[i] && a[k] === b[k]);
}

const nextExports = sortedExportsObject(buildExports());

if (CHECK) {
  const cur = readCurrentExports();
  if (!exportsEqual(cur, nextExports)) {
    console.error("sync-package-exports --check: package.json exports 与扫描结果不一致");
    console.error("运行: npm run sync:exports --workspace=@changmen/venue-adapter");
    process.exit(1);
  }
  console.log(`sync-package-exports --check: OK (${Object.keys(nextExports).length} entries)`);
  process.exit(0);
}

const pkg = JSON.parse(fs.readFileSync(PKG_JSON, "utf8"));
pkg.exports = nextExports;
fs.writeFileSync(PKG_JSON, `${JSON.stringify(pkg, null, 2)}\n`);
console.log(`sync-package-exports: wrote ${Object.keys(nextExports).length} exports to package.json`);

/** [changmen 扩展] 只识别源码身份；不加载应用、凭证或数据库，也不决定交易许可。 */
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";

const digest = value => createHash("sha256").update(value).digest("hex");
const normalize = value => value.replaceAll("\r\n", "\n");
const shaPattern = /^[a-f0-9]{40}$/;
const excluded = /(?:^|\/)(?:node_modules|dist|docs|output|test|tests|__tests__|\.git|\.ai|\.claude)(?:\/|$)|\.(?:test|spec)\./;
const sourceExtension = /\.(?:[cm]?js|tsx?|vue|json|ya?ml|sql|toml)$/;
const frontendAsset = /\.(?:css|scss|less|html|svg|png|jpe?g|webp|gif|woff2?)$/;
const binaryAsset = /\.(?:png|jpe?g|webp|gif|woff2?)$/;
const generatedRoutes = new Set(["router", "account_client_routes", "action_registry", "admin_routes", "pm_pf_routes"].map(name => `server/backend/core/esport-api/${name}.js`));
export function isVersionSource(file, role) {
  if (!["frontend", "backend"].includes(role)) throw Error("Unknown runtime role");
  if (excluded.test(file) || !(sourceExtension.test(file) || (role === "frontend" && frontendAsset.test(file))) || /(?:^|\/)\.env(?:\.|$)/.test(file)) return false;
  // Compiled routes are represented by tracked TS; heartbeats are runtime data.
  if (generatedRoutes.has(file) || /^server\/match\/matcher\/\.(?:composer|matcher)-heartbeat\.json$/.test(file)) return false;
  if (/^server\/backend\/(?:storage|scripts\/ops)\//.test(file)) return false;
  if (["package.json", "package-lock.json", "server/storage/runtime_version.js"].includes(file)) return true;
  // [changmen 扩展] 迁入 client 的包保留原 packages 的双端保守覆盖，既有排除规则仍先执行。
  if (file.startsWith("client/packages/")) return true;
  if (/^server\/packages\/(?:venue-node-(?:loader|registry)|venue-adapter-tools)\//.test(file)) return true;
  if (file.startsWith("devtools/runtime-tooling/")) return true;
  return role === "frontend"
    ? /^(?:client\/web\/(?:src\/|public\/|vite\/|vite\.config\.ts|package\.json|scripts\/run-production-build\.mjs)|packages\/)/.test(file)
    : /^(?:server\/|packages\/|devtools\/platform-probes\/)/.test(file);
}
const contractSource = file => /^packages\/api-contract\//.test(file)
  || ["packages/shared/pm_gtc.ts", "packages/shared/pm_gtc_recovery.ts"].includes(file);
function git(root, args, options = {}) {
  return execFileSync("git", ["-C", root, ...args], { encoding: "utf8", timeout: 3000, maxBuffer: 80 * 1024 * 1024, windowsHide: true, stdio: ["pipe", "pipe", "ignore"], ...options });
}
function walk(root) {
  const files = [];
  const visit = relative => {
    for (const item of fs.readdirSync(path.join(root, relative), { withFileTypes: true })) {
      const file = relative ? `${relative}/${item.name}` : item.name;
      if (excluded.test(file)) continue;
      if (item.isDirectory()) visit(file);
      else if (item.isFile()) files.push(file);
    }
  };
  for (const dir of ["client/web/src", "client/web/public", "client/web/vite", "client/web/scripts", "client/packages", "devtools/runtime-tooling", "packages", "server", "devtools/platform-probes"])
    if (fs.existsSync(path.join(root, dir))) visit(dir);
  for (const file of ["package.json", "package-lock.json", "client/web/package.json", "client/web/vite.config.ts"])
    if (fs.existsSync(path.join(root, file))) files.push(file);
  return files;
}
function fingerprint(files, read) {
  return digest([...new Set(files)].sort().map(file => {
    const value = read(file);
    return `${file}\0${value === null ? "missing" : `present\0${digest(value)}`}`;
  }).join("\n"));
}
function committedSources(root, commit, files) {
  const objects = Buffer.from(git(root, ["cat-file", "--batch"], { encoding: null, input: files.map(file => `${commit}:${file}`).join("\n") + "\n" }));
  const sources = new Map(); let offset = 0;
  for (const file of files) {
    const end = objects.indexOf(10, offset), header = objects.subarray(offset, end).toString().split(" ");
    if (header[1] !== "blob") throw Error("Source blob unavailable");
    const size = Number(header[2]);
    const bytes = objects.subarray(end + 1, end + 1 + size);
    sources.set(file, binaryAsset.test(file) ? bytes : normalize(bytes.toString("utf8"))); offset = end + 1 + size + 1;
  }
  return sources;
}
export function readSourceVersion(root, role) {
  let commit = null, provenance = "unknown", dirty = null, inventory;
  try {
    if (path.resolve(git(root, ["rev-parse", "--show-toplevel"]).trim()) !== path.resolve(root)) throw Error("Different repository");
    commit = git(root, ["rev-parse", "HEAD"]).trim();
    if (!shaPattern.test(commit)) throw Error("Invalid commit");
    provenance = "git";
    inventory = git(root, ["ls-files", "--cached", "--others", "--exclude-standard", "-z"]).split("\0").filter(Boolean);
  } catch {
    commit = path.basename(root).match(/^backend-([a-f0-9]{40})-/)?.[1] ?? null;
    provenance = commit ? "release-directory" : "unknown";
    inventory = walk(root);
  }
  const files = inventory.filter(file => isVersionSource(file, role));
  const read = file => {
    try { const bytes = fs.readFileSync(path.join(root, file)); return binaryAsset.test(file) ? bytes : normalize(bytes.toString("utf8")); }
    catch (error) { if (error.code === "ENOENT") return null; throw error; }
  };
  const sourceFingerprint = files.length ? fingerprint(files, read) : null;
  if (provenance === "git") {
    try {
      const baseline = git(root, ["ls-tree", "-r", "--name-only", "-z", commit]).split("\0").filter(file => file && isVersionSource(file, role));
      const sources = committedSources(root, commit, baseline);
      dirty = sourceFingerprint !== fingerprint(baseline, file => sources.get(file));
    } catch { dirty = null; }
  }
  const contracts = inventory.filter(file => contractSource(file) && !excluded.test(file) && sourceExtension.test(file));
  let contractVersion = null;
  try { contractVersion = JSON.parse(read("packages/api-contract/package.json")).version ?? null; } catch { /* unknown is explicit */ }
  return Object.freeze({ commit, provenance, dirty, sourceFingerprint, contractVersion, contractFingerprint: contracts.length ? fingerprint(contracts, read) : null });
}
/** No .git in a release archive: its release directory is the identity, not the mutable deployment checkout. */
export function captureRuntimeVersion(root, role, options = {}) {
  let source;
  try { source = readSourceVersion(root, role); }
  catch { source = { commit: null, provenance: "unknown", dirty: null, sourceFingerprint: null, contractVersion: null, contractFingerprint: null }; }
  return Object.freeze({ ...source, role, startedAt: options.startedAt ?? new Date(Date.now() - process.uptime() * 1000).toISOString(), capturedAt: new Date().toISOString() });
}

#!/usr/bin/env node
/**
 * 电竞业务冻结闸门：diff 命中 esport-freeze.json 路径且未 ALLOW_ESPORT_TOUCH=1 → 失败。
 *
 * 用法：
 *   node packages/venue-adapter/scripts/check-esport-freeze.mjs
 *   ESPORT_FREEZE_BASE=origin/main node ...
 *   ALLOW_ESPORT_TOUCH=1 node ...   # 显式解冻（仍应跑 quote-hub-contracts）
 *
 * Base 默认：与 origin/main|master 的 merge-base；否则 HEAD（仅查工作区相对 HEAD）。
 */
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { checkPmFolderFreeze } from "../../../scripts/verification/pm-folder-release-boundary.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, "../../..");
const PKG_ROOT = path.join(REPO_ROOT, "packages/venue-adapter");
const MANIFEST = path.join(PKG_ROOT, "esport-freeze.json");

const LIST_ONLY = process.argv.includes("--list");
const ALLOW_CLI = process.argv.includes("--allow");
const allowEnv = "ALLOW_ESPORT_TOUCH";

function git(args, opts = {}) {
  try {
    const output = execFileSync("git", args, {
      cwd: REPO_ROOT,
      encoding: "utf8",
      maxBuffer: 64 * 1024 * 1024,
      stdio: ["ignore", "pipe", "pipe"],
      ...opts,
    });
    return opts.trim === false ? output : output.trim();
  }
  catch (err) {
    if (opts.allowFail)
      return "";
    throw err;
  }
}

function loadManifest() {
  const raw = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
  const paths = (raw.paths || []).map(p => String(p).replace(/\\/g, "/"));
  return { ...raw, paths };
}

function detectBase() {
  if (process.env.ESPORT_FREEZE_BASE)
    return process.env.ESPORT_FREEZE_BASE.trim();
  for (const ref of ["origin/main", "origin/master", "main", "master"]) {
    const ok = git(["rev-parse", "--verify", ref], { allowFail: true });
    if (!ok)
      continue;
    const mb = git(["merge-base", "HEAD", ref], { allowFail: true });
    if (mb)
      return mb;
  }
  return "HEAD";
}

function changedFiles(base) {
  const out = new Set();
  const addLines = (text) => {
    for (const line of text.split(/\r?\n/)) {
      const p = line.trim().replace(/\\/g, "/");
      if (p)
        out.add(p);
    }
  };
  // 已提交相对 base
  addLines(git(["diff", "--name-only", `${base}...HEAD`]));
  // 工作区相对 base（含未提交）
  addLines(git(["diff", "--name-only", base]));
  addLines(git(["ls-files", "--others", "--exclude-standard", "--", "packages"]));
  // 暂存区
  addLines(git(["diff", "--name-only", "--cached"]));
  return [...out];
}

function isFrozen(file, freezePaths) {
  const norm = file.replace(/\\/g, "/");
  // 测试文件不挡（可补 lifecycle / isolation）
  if (/\.(test|spec)\.(ts|tsx|js|mjs)$/.test(norm))
    return false;
  return freezePaths.some(fp => norm === fp || norm.endsWith(`/${fp}`) || norm.startsWith(`${fp}/`));
}

function main() {
  const manifest = loadManifest();
  if (LIST_ONLY) {
    for (const p of manifest.paths)
      console.log(p);
    process.exit(0);
  }

  const base = detectBase();
  const changed = changedFiles(base);
  const { hits } = checkPmFolderFreeze(changed, fs.readFileSync(MANIFEST, "utf8"),
    file => fs.readFileSync(path.join(REPO_ROOT, file), "utf8"),
    (ref, file) => git(["show", `${ref}:${file}`], { trim: false }));

  if (!hits.length) {
    console.log(`[esport-freeze] ok (base=${base}, changed=${changed.length}, frozen hits=0)`);
    process.exit(0);
  }

  const unlocked = ALLOW_CLI
    || process.env[allowEnv] === "1"
    || process.env[allowEnv] === "true";
  console.error(`[esport-freeze] 命中电竞冻结面 (base=${base}):`);
  for (const h of hits)
    console.error(`  - ${h}`);
  console.error("");
  console.error("体育/N3.5 迭代不应改这些文件。冻结清单: packages/venue-adapter/esport-freeze.json");
  console.error(`解冻: ${allowEnv}=1 或 --allow（并说明原因；改 hub/collect 后请跑 test:quote-hub-contracts）`);

  if (unlocked) {
    console.warn(`[esport-freeze] ${ALLOW_CLI ? "--allow" : allowEnv} — 放行（请确认有意解冻）`);
    process.exit(0);
  }

  process.exit(1);
}

main();

