 const options=async c=>{const journal=[];return {journal,attestation:{target:await readTarget(c),allConsumersCompatible:true,oldExecutionSource:"pm_gtc_executions",legacyFlag:"0",minimalFlag:"1",projectionWritesPaused:true,financialFilteringRetained:true},persistPrepared:async r=>{writeImmutable(path.join(evidenceDir,r.batchId+".prepared.json"),r);journal.push(r);}};};
 const makePlan=async c=>planBatch(c,OWNER,[EXECUTION]);
 const receipt=async c=>applyBatch(c,await makePlan(c),await options(c));
 it("migration dry-run is read-only and contains no full control payload",async()=>{const s=await source(),c=await connectionClient(),plan=await makePlan(c);expect(plan.operations[0].action).toBe("insert-pending");expect(await row()).toBeUndefined();expect((await listPmGtcByIds(OWNER,[s.id]))[0]).toEqual(s);for(const key of ["walletKey","maker","pmAuthorized","fills","testUnknownExtension"])expect(JSON.stringify(plan)).not.toContain('"'+key+'"');await release(c);});
 it("durable apply and rollback preserve finance, source and notification behavior",async()=>{const s=await source(),c=await connectionClient(),opt=await options(c),hook=vi.fn();orders.setOrdersInsertedHook(hook);const r=await applyBatch(c,await makePlan(c),opt),stored=await row();expect(opt.journal).toHaveLength(1);expect(stored.financial_ready).toBe(false);expect(stored.create_at).toBe(String(s.createdAt));expect((await getPool().query("SELECT count(*)::int AS n FROM orders_financial")).rows[0].n).toBe(0);expect((await reconcileReceipt(c,r)).status).toBe("committed");const undo=await rollbackBatch(c,r,opt);expect(await row()).toBeUndefined();expect((await reconcileReceipt(c,r)).status).toBe("rolled-back");expect((await reconcileReceipt(c,undo)).status).toBe("committed");expect((await listPmGtcByIds(OWNER,[s.id]))[0]).toEqual(s);expect(hook).not.toHaveBeenCalled();await release(c);});
 it("historical seven-column copies attach and restore only new metadata",async()=>{const s=await source();await orders.upsertOrders([financialRow(HASH.toUpperCase(),{original:"ledger",pmShares:9})]);await getPool().query("UPDATE orders SET execution_id=$1,execution_record=$2",[s.id,s]);const before=await row(),c=await connectionClient(),r=await receipt(c),after=await row();for(const key of Object.keys(before).filter(k=>!["execution_id","pm_order_mode","pm_order_snapshot"].includes(k)))expect(after[key]).toEqual(before[key]);expect(after.order_id).toBe(HASH.toUpperCase());await rollbackBatch(c,r,await options(c));expect(await row()).toEqual(before);await release(c);});
 it("a repeated plan is a no-op without changing original source time",async()=>{const s=await source(),c=await connectionClient();await receipt(c);const p=await makePlan(c);expect(p.operations).toHaveLength(0);expect(p.skipped[0].reason).toBe("ALREADY_CURRENT");expect((await applyBatch(c,p)).status).toBe("no-op");expect((await listPmGtcByIds(OWNER,[s.id]))[0]).toEqual(s);await release(c);});
 it.each(["unknown","prepared","rejected"])("backfill cannot invent an accepted %s source",async submit=>{const s=accepted();s.submit=submit;await source(s);const c=await connectionClient(),p=await makePlan(c);expect(p.operations).toHaveLength(0);expect(p.skipped[0].reason).toBe("NO_ACCEPTED_ORDER");await release(c);});
 it("backfill skips the original open first-order window",async()=>{await source(accepted(),false);const c=await connectionClient(),p=await makePlan(c);expect(p.operations).toHaveLength(0);expect(p.skipped[0].reason).toBe("FIRST_ORDER_WINDOW_OPEN");await release(c);});
 it.each(["FOK","foreign raw","duplicate case","newer snapshot","unknown snapshot"])("preflight reports %s conflicts rather than guessing",async conflict=>{const s=await source();await orders.upsertOrders([financialRow(HASH)]);if(conflict==="FOK")await getPool().query("UPDATE orders SET pm_order_mode='FOK'");else if(conflict==="foreign raw")await getPool().query("UPDATE orders SET raw=jsonb_build_object('pmGtcExecutionId','other')");else if(conflict==="duplicate case")await orders.upsertOrders([financialRow(HASH.toUpperCase())]);else if(conflict==="newer snapshot")await getPool().query("UPDATE orders SET pm_order_snapshot=$1",[{executionId:s.id,revision:999}]);else await getPool().query("UPDATE orders SET pm_order_snapshot=$1",[{version:1,executionId:s.id,revision:0,plan:{authorization:"not copied"}}]);const c=await connectionClient(),p=await makePlan(c);expect(p.conflicts).toHaveLength(1);await expect(applyBatch(c,p,await options(c))).rejects.toThrow("PLAN_HAS_CONFLICTS");await release(c);});
 it("multiple old executions for one original block the plan",async()=>{await source();await source(accepted("00000000-0000-4000-8000-000000000012"));const c=await connectionClient(),p=await makePlan(c);expect(p.conflicts[0].reason).toBe("MULTIPLE_EXECUTIONS_FOR_ORIGINAL");await release(c);});
 it("wrong owner and oversized selections cannot write",async()=>{await source();const c=await connectionClient();const p=await planBatch(c,"00000000-0000-4000-8000-000000000099",[EXECUTION]);expect(p.conflicts[0].reason).toBe("SOURCE_NOT_OWNED_OR_MISSING");await expect(planBatch(c,OWNER,Array(26).fill(EXECUTION))).rejects.toThrow("BOUNDED");await release(c);});
 it.each(["source","target","payload"])("apply rejects %s drift atomically",async drift=>{await source();const c=await connectionClient();let p=await makePlan(c);if(drift==="source")await getPool().query("UPDATE pm_gtc_executions SET updated_at=updated_at+1");else if(drift==="target")await orders.upsertOrders([financialRow(HASH)]);else{const {digest:_,...b}=p;b.operations[0].insert.raw={injected:true};p=seal(b);}await expect(applyBatch(c,p,await options(c))).rejects.toThrow();if(drift!=="target")expect(await row()).toBeUndefined();await release(c);});
 it("receipt persistence failure rolls back the batch before COMMIT",async()=>{const s=await source(),c=await connectionClient(),opt=await options(c);opt.persistPrepared=async()=>{throw Error("disk unavailable");};await expect(applyBatch(c,await makePlan(c),opt)).rejects.toThrow("disk unavailable");expect(await row()).toBeUndefined();expect((await listPmGtcByIds(OWNER,[s.id]))[0]).toEqual(s);await release(c);});
 it("deferred COMMIT failure retains a reconcilable prepared receipt",async()=>{await source();await getPool().query("CREATE FUNCTION minimal_test_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'minimal injected fault'; END $$; CREATE CONSTRAINT TRIGGER minimal_test_fault AFTER INSERT ON orders DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION minimal_test_fault()");const c=await connectionClient(),opt=await options(c);await expect(applyBatch(c,await makePlan(c),opt)).rejects.toThrow("injected");expect(opt.journal).toHaveLength(1);expect((await reconcileReceipt(c,opt.journal[0])).status).toBe("rolled-back");await release(c);});
 it("a busy ordinary writer makes the bounded backfill exit without blocking it",async()=>{await source();const c=await connectionClient(),p=await makePlan(c),blocker=await connectionClient();await blocker.query("BEGIN");await blocker.query("INSERT INTO orders(user_id,player_id,order_id,create_at) VALUES($1,1,'busy-fok',1)",[OWNER]);await expect(applyBatch(c,p,await options(c))).rejects.toMatchObject({code:"55P03"});await blocker.query("COMMIT");await release(blocker);expect(await row()).toBeUndefined();expect((await getPool().query("SELECT count(*)::int AS n FROM orders WHERE order_id='busy-fok'")).rows[0].n).toBe(1);await release(c);});
 it("busy execution authorization makes backfill exit without consuming it",async()=>{await source();const c=await connectionClient(),p=await makePlan(c),blocker=await connectionClient();await blocker.query("BEGIN");await blocker.query("SELECT pg_advisory_xact_lock(hashtextextended($1,0))",[EXECUTION]);await expect(applyBatch(c,p,await options(c))).rejects.toThrow("EXECUTION_BUSY");await blocker.query("ROLLBACK");await release(blocker);expect(await row()).toBeUndefined();await release(c);});
 it.each(["source","financial promotion","target metadata"])("rollback stops on %s changes",async change=>{const s=await source(),c=await connectionClient(),r=await receipt(c);if(change==="source")await getPool().query("UPDATE pm_gtc_executions SET updated_at=updated_at+1");else if(change==="financial promotion")await mutatePmGtc(OWNER,s.id,s.revision,facts());else await getPool().query("UPDATE orders SET pm_order_snapshot=jsonb_set(pm_order_snapshot,'{updatedAt}','1')");const before=await row();await expect(rollbackBatch(c,r,await options(c))).rejects.toThrow();expect(await row()).toEqual(before);await release(c);});
 it("both apply and rollback refuse disabled financial filtering",async()=>{await source();const c=await connectionClient(),p=await makePlan(c),opt=await options(c);const bad={...opt,attestation:{...opt.attestation,minimalFlag:"0"}};await expect(applyBatch(c,p,bad)).rejects.toThrow("COMPATIBLE_READS");const r=await applyBatch(c,p,opt);await expect(rollbackBatch(c,r,bad)).rejects.toThrow("COMPATIBLE_READS");expect(await row()).toBeDefined();await release(c);});
 it("drift in the second original rolls back the entire bounded batch",async()=>{await source();const id="00000000-0000-4000-8000-000000000012",hash="0x"+"b".repeat(64);await source(accepted(id,hash));const c=await connectionClient(),p=await planBatch(c,OWNER,[EXECUTION,id]),opt=await options(c);await orders.upsertOrders([financialRow(hash)]);const before=(await getPool().query("SELECT * FROM orders")).rows;await expect(applyBatch(c,p,opt)).rejects.toThrow("TARGET_OR_PLANNED");expect((await getPool().query("SELECT * FROM orders")).rows).toEqual(before);expect(opt.journal).toHaveLength(0);await release(c);});
 it("prepared rollback receipts also reconcile after an uncertain acknowledgement",async()=>{await source();const c=await connectionClient(),r=await receipt(c),undo=await rollbackBatch(c,r,await options(c));expect((await reconcileReceipt(c,undo)).status).toBe("committed");expect((await reconcileReceipt(c,r)).status).toBe("rolled-back");await expect(rollbackBatch(c,r,await options(c))).rejects.toThrow("TARGET_CHANGED");await release(c);});
 it("schema installer refuses a busy table without dropping or rewriting objects",async()=>{const c=await connectionClient(),p=await planSchema(c),opt=await options(c),blocker=await connectionClient();opt.attestation.minimalFlag="0";await blocker.query("BEGIN");await blocker.query("SELECT * FROM orders");await expect(installSchema(c,p,opt)).rejects.toMatchObject({code:"55P03"});await blocker.query("ROLLBACK");await release(blocker);expect((await planSchema(c)).digest).toBe(p.digest);await release(c);});
 it("paused projections keep original facts and financial promotion running",async()=>{const s=await source();vi.stubEnv("PM_ORDERS_MINIMAL_PROJECTION_WRITE","0");const a=await mutatePmGtc(OWNER,s.id,s.revision,zero());expect(await row()).toBeUndefined();const b=await mutatePmGtc(OWNER,s.id,a.revision,facts());const financial=(await getPool().query("SELECT * FROM orders")).rows[0];expect(financial.financial_ready).toBe(true);expect(financial.bet_money).toBe(16.75);expect(b.financialOrder).toEqual(facts().financialOrder);expect((await listPmGtcByIds(OWNER,[s.id]))[0]).toEqual(b);});
 it("pausing does not expose an existing nonfinancial order to financial reads",async()=>{const s=await source(),a=await mutatePmGtc(OWNER,s.id,s.revision,zero()),before=await row();vi.stubEnv("PM_ORDERS_MINIMAL_PROJECTION_WRITE","0");await mutatePmGtc(OWNER,s.id,a.revision,zero());expect(await row()).toEqual(before);expect((await getPool().query("SELECT count(*)::int AS n FROM orders_financial")).rows[0].n).toBe(0);});
 it("schema install reentry only verifies compatible installed objects",async()=>{const c=await connectionClient(),p=await planSchema(c),opt=await options(c);expect(p.action).toBe("already-installed");opt.attestation.minimalFlag="0";expect((await installSchema(c,p,opt)).status).toBe("already-installed");expect(opt.journal).toHaveLength(0);await release(c);});
 it("fresh explicit schema install preserves original columns and old data",async()=>{await orders.upsertOrders([financialRow("original")]);const before=(await getPool().query("SELECT * FROM orders")).rows[0],c=await connectionClient();await c.query("DROP VIEW orders_financial; DROP FUNCTION validate_pm_orders_minimal_v1(); ALTER TABLE orders DROP CONSTRAINT pm_orders_minimal_mode, DROP CONSTRAINT pm_orders_minimal_pending, DROP COLUMN pm_order_mode, DROP COLUMN pm_order_snapshot");const p=await planSchema(c),opt=await options(c);opt.attestation.minimalFlag="0";expect(p.action).toBe("install");const r=await installSchema(c,p,opt);expect(opt.journal).toHaveLength(1);expect((await reconcileReceipt(c,r)).status).toBe("committed");expect((await getPool().query("SELECT * FROM orders")).rows[0]).toEqual(before);await release(c);});
 it("schema installation refuses incompatible partial objects instead of overwriting",async()=>{const c=await connectionClient();await c.query("CREATE OR REPLACE VIEW orders_financial AS SELECT * FROM orders");try{await expect(planSchema(c)).rejects.toThrow("schema mismatch");}finally{await c.query("CREATE OR REPLACE VIEW orders_financial AS SELECT * FROM orders WHERE financial_ready");}await release(c);});
 it("late durable persistence exceeds the batch budget and cannot COMMIT",async()=>{await source();const c=await connectionClient(),p=await makePlan(c),opt=await options(c),now=performance.now(),save=opt.persistPrepared;let clock;opt.persistPrepared=async r=>{await save(r);clock=vi.spyOn(performance,"now").mockReturnValue(now+4000);};try{await expect(applyBatch(c,p,opt)).rejects.toThrow("BATCH_DEADLINE");}finally{clock?.mockRestore();}expect(await row()).toBeUndefined();expect((await reconcileReceipt(c,opt.journal[0])).status).toBe("rolled-back");await release(c);});
 it("partial legacy execution constraints cannot enter minimal schema tooling",async()=>{const c=await connectionClient();await c.query("ALTER TABLE orders ADD CONSTRAINT orders_execution_record_v1 CHECK(financial_ready)");try{await expect(planSchema(c)).rejects.toThrow("LEGACY_FULL_SCHEMA");}finally{await c.query("ALTER TABLE orders DROP CONSTRAINT orders_execution_record_v1");}await release(c);});

}

