function gate(){let resolve;const promise=new Promise(r=>resolve=r);releases.add(resolve);return {promise,resolve};}
async function connectionClient(){const c=await pool.connect();clients.add(c);return c;}
async function release(c){clients.delete(c);c.release();}
async function source(row=accepted(),closed=true){if(closed){row.decision="closed";row.manual=true;}
  await pool.query("INSERT INTO pm_gtc_executions(id,owner,wallet_key,active,record,updated_at) VALUES($1,$2,$3,$4,$5,$6)",[row.id,row.owner,row.walletKey,!row.released,row,row.createdAt]);return row;}
const zero=()=>({kind:"facts",facts:{order:{id:HASH,original:"10",matched:"0",status:"LIVE",tradeIds:[]},fills:[],complete:true,observedAt:Date.now()}});
async function row(){return (await pool.query("SELECT * FROM orders WHERE execution_id=$1",[EXECUTION])).rows[0];}
async function blockedBy(waiter,blocker){const end=Date.now()+2500;while(Date.now()<end){if((await pool.query("SELECT $2::int=ANY(pg_blocking_pids($1)) AS yes",[waiter,blocker])).rows[0].yes)return;await new Promise(r=>setTimeout(r,10));}throw Error("expected real pg lock wait absent");}
async function injectFault(deferred=false){await pool.query("CREATE FUNCTION minimal_test_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'minimal injected fault'; END $$");
  await pool.query(`CREATE ${deferred?"CONSTRAINT ":""}TRIGGER minimal_test_fault ${deferred?"AFTER":"BEFORE"} INSERT OR UPDATE ON orders ${deferred?"DEFERRABLE INITIALLY DEFERRED":""} FOR EACH ROW EXECUTE FUNCTION minimal_test_fault()`);}

