      try { await assert.rejects(writer.writeClientMatches([{ ID: 1, Title: "uncommitted" }], 300), /phase2 injected/); }
      finally { await pool.query("DROP TRIGGER phase2_reject ON client_matches; DROP FUNCTION phase2_reject()"); }
