let sequence = 0;
function token(ttl = 60, secret = JWT_SECRET, extra = {}) {
  return signJwt({ sub: `u${++sequence}`, typ: "access", session_id: "current", ...extra }, secret, ttl);
}
beforeEach(() => { query.mockReset(); query.mockResolvedValue({ rows: [{ sid: "current" }] }); });
