#!/usr/bin/env node
/**
 * 场馆 HK 出海 relay 部署探针
 *
 * 1. VPS 直连 Polymarket / Predict.fun 上游
 * 2. 本机 http-relay 代发（Predict.fun；PM 已迁出至 Pm_HttpRequest）
 * 3. ws-forward：PM-MARKET（:3457）/ PREDICTFUN-MARKET（:3458）独立 hub；PM-USER 仍在 esport
 *
 * 用法（VPS / 本机 backend 目录）：
 *   node scripts/ops/diagnostics/probe-hk-relay.mjs
 *   node scripts/ops/diagnostics/probe-hk-relay.mjs --upstream-only
 *   ESPORT_TEST_BASE=http://127.0.0.1:3456 PROBE_TOKEN=xxx node scripts/ops/diagnostics/probe-hk-relay.mjs
 *
 * PM-MARKET WS 默认测独立 hub（PM_MARKET_HUB_PORT / PROBE_PM_MARKET_HUB_BASE，默认 :3457），
 * 勿对 esport :3456 做 upgrade（隔离后那里没有 handler）。
 *
 * PROBE_TOKEN 未设时：若 JWT_SECRET + RDS 可用，自动为首个 profiles 用户签发短期 JWT。
 */
import http from "node:http";
import https from "node:https";
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { buildHttpRelayUrl } from "@changmen/api-contract/urls";
import WebSocket from "ws";

loadChangmenEnv();

const args = new Set(process.argv.slice(2));
const upstreamOnly = args.has("--upstream-only");
const relayOnly = args.has("--relay-only");
const skipWs = args.has("--skip-ws") || upstreamOnly || relayOnly;

const UPSTREAM = {
  gamma: "https://gamma-api.polymarket.com/sports",
  clob: "https://clob.polymarket.com/time",
  predictTestnet: "https://api-testnet.predict.fun/v1/tags",
  predictMainnet: "https://api.predict.fun/v1/tags",
};

function resolvePredictFunApiKey() {
  return String(
    process.env.PREDICT_FUN_API_KEY
    || process.env.VITE_PREDICT_FUN_API_KEY
    || "",
  ).trim();
}

async function resolveProbeToken() {
  const fromEnv = String(process.env.PROBE_TOKEN || process.env.ESPORT_TEST_TOKEN || "").trim();
  if (fromEnv)
    return { token: fromEnv, source: "env" };

  const secret = String(process.env.JWT_SECRET || "").trim();
  if (secret.length < 16)
    return { token: "", source: "" };

  try {
    const { hasDatabaseUrlConfig, initDatabaseUrl, getPgPool } = await import("@changmen/db");
    if (!hasDatabaseUrlConfig())
      return { token: "", source: "" };
    await initDatabaseUrl();
    const pool = getPgPool("probe-hk-relay");
    if (!pool)
      return { token: "", source: "" };
    const { rows } = await pool.query(
      `SELECT p.id::text AS id FROM profiles p ORDER BY p.id LIMIT 1`,
    );
    const userId = String(rows[0]?.id || "").trim();
    if (!userId)
      return { token: "", source: "" };
    const { signJwt, JWT_ACCESS_TTL_SEC } = await import("../../../../db/rds/jwt.js");
    const token = signJwt(
      { sub: userId, typ: "access", session_id: "probe-hk-relay" },
      secret,
      JWT_ACCESS_TTL_SEC,
    );
    return { token, source: "auto-jwt" };
  }
  catch (err) {
    if (process.env.PROBE_DEBUG)
      console.warn("resolveProbeToken:", err instanceof Error ? err.message : err);
    return { token: "", source: "" };
  }
}

const PM_WS_FORWARD_PATH = "/esport/ws-forward/PM-MARKET";
const PREDICT_WS_FORWARD_PATH = "/esport/ws-forward/PREDICTFUN-MARKET";

const results = [];

function pass(name, detail = "") {
  results.push({ name, ok: true, detail });
  console.log(`OK   ${name}${detail ? ` — ${detail}` : ""}`);
}

function fail(name, detail = "") {
  results.push({ name, ok: false, detail });
  console.error(`FAIL ${name}${detail ? ` — ${detail}` : ""}`);
}

function resolveApiBase() {
  const fromEnv = String(process.env.ESPORT_TEST_BASE || process.env.PROBE_API_BASE || "").trim();
  if (fromEnv)
    return fromEnv.replace(/\/+$/, "");
  const port = Number(process.env.PORT || 3456);
  return `http://127.0.0.1:${port}`;
}

/** PM-MARKET 独立 hub（默认 :3457）；可用 PROBE_PM_MARKET_HUB_BASE 覆盖（例如经 Caddy :80） */
function resolvePmMarketHubBase() {
  const fromEnv = String(process.env.PROBE_PM_MARKET_HUB_BASE || "").trim();
  if (fromEnv)
    return fromEnv.replace(/\/+$/, "");
  const port = Number(process.env.PM_MARKET_HUB_PORT || 3457);
  return `http://127.0.0.1:${Number.isFinite(port) && port > 0 ? port : 3457}`;
}

function nodeFetch(url, options = {}) {
  return new Promise((resolve, reject) => {
    const parsed = new URL(url);
    const lib = parsed.protocol === "https:" ? https : http;
    const req = lib.request(
      parsed,
      {
        method: options.method || "GET",
        headers: options.headers || {},
        timeout: options.timeoutMs ?? 20_000,
      },
      (res) => {
        const chunks = [];
        res.on("data", c => chunks.push(c));
        res.on("end", () => {
          resolve({
            status: res.statusCode || 502,
            headers: res.headers,
            body: Buffer.concat(chunks),
          });
        });
      },
    );
    req.on("timeout", () => {
      req.destroy(new Error("timeout"));
    });
    req.on("error", reject);
    if (options.body)
      req.write(options.body);
    req.end();
  });
}

async function checkUpstreamDirect() {
  const predictApiKey = resolvePredictFunApiKey();
  for (const [label, url] of Object.entries(UPSTREAM)) {
    try {
      const headers = {};
      if (label === "predictMainnet" && predictApiKey)
        headers["x-api-key"] = predictApiKey;
      const res = await nodeFetch(url, { headers });
      if (res.status >= 200 && res.status < 400) {
        pass(`upstream:${label}`, `HTTP ${res.status}`);
      }
      else {
        fail(`upstream:${label}`, `HTTP ${res.status}`);
      }
    }
    catch (err) {
      fail(`upstream:${label}`, err instanceof Error ? err.message : String(err));
    }
  }
}

async function checkHttpRelay(apiBase) {
  const relayRequireToken = ["1", "true", "yes", "on"].includes(
    String(process.env.HTTP_RELAY_REQUIRE_TOKEN || "").trim().toLowerCase(),
  );
  const { token, source } = await resolveProbeToken();
  if (relayRequireToken && !token) {
    fail("http-relay:token", "HTTP_RELAY_REQUIRE_TOKEN=1 但未设置 PROBE_TOKEN / ESPORT_TEST_TOKEN，且无法 auto-jwt");
    fail("http-relay:predict-tags", "跳过（无 PROBE_TOKEN）");
    return;
  }
  if (relayRequireToken)
    pass("http-relay:token", source === "auto-jwt" ? "auto JWT（profiles）" : "已提供 PROBE_TOKEN");

  const relayUrl = buildHttpRelayUrl({ apiBase });
  const tokenHeaders = token ? { token } : {};

  try {
    const predictApiKey = resolvePredictFunApiKey();
    const predictHeaders = {
      ...tokenHeaders,
      "x-proxy-url": UPSTREAM.predictMainnet,
      "x-proxy-referer": "https://predict.fun/",
      "x-proxy-origin": "https://predict.fun",
    };
    if (predictApiKey)
      predictHeaders["x-api-key"] = predictApiKey;
    const res = await nodeFetch(relayUrl, {
      headers: predictHeaders,
      timeoutMs: 25_000,
    });
    if (res.status >= 200 && res.status < 400) {
      pass("http-relay:predict-tags", `HTTP ${res.status} via ${relayUrl}`);
    }
    else {
      const snippet = res.body.toString("utf8").slice(0, 120);
      fail("http-relay:predict-tags", `HTTP ${res.status} ${snippet}`);
    }
  }
  catch (err) {
    fail("http-relay:predict-tags", err instanceof Error ? err.message : String(err));
  }
}

async function checkProxyStatus(apiBase) {
  try {
    const res = await nodeFetch(`${apiBase}/api/proxy/status`);
    if (res.status !== 200) {
      fail("ws-forward:status", `HTTP ${res.status}`);
      return;
    }
    const data = JSON.parse(res.body.toString("utf8"));
    const platforms = Array.isArray(data.platforms) ? data.platforms : [];
    const hubs = data.hubs && typeof data.hubs === "object" ? data.hubs : {};
    // PM-MARKET / PREDICTFUN-MARKET 由独立进程承担：platforms 含 id，或 hubs.* 有状态即可
    const pmOk = platforms.includes("PM-MARKET") || Boolean(hubs.pmMarket);
    const pfOk = platforms.includes("PREDICTFUN-MARKET") || Boolean(hubs.predictFunMarket);
    if (!data.enabled && !pmOk && !pfOk) {
      fail("ws-forward:enabled", "ws_forward 未启用（检查 esport / market hubs）");
      return;
    }
    if (!pmOk) {
      fail(
        "ws-forward:PM-MARKET",
        "未检测到 PM-MARKET（独立 hub hubs.pmMarket）；检查 changmen-pm-market-hub :3457 与 Caddy",
      );
      return;
    }
    if (!pfOk) {
      fail(
        "ws-forward:PREDICTFUN-MARKET",
        "未检测到 PREDICTFUN-MARKET（独立 hub hubs.predictFunMarket）；检查 changmen-predictfun-market-hub :3458 与 Caddy",
      );
      return;
    }
    const bits = [
      "PREDICTFUN-MARKET",
      "PM-MARKET",
      platforms.includes("PM-USER") ? "PM-USER" : null,
    ].filter(Boolean);
    pass("ws-forward:platforms", bits.join(", "));
  }
  catch (err) {
    fail("ws-forward:status", err instanceof Error ? err.message : String(err));
  }
}

function checkWsForwardRelay(apiBase, path, label, { pingProbe = true } = {}) {
  return new Promise((resolve) => {
    const base = new URL(apiBase);
    const wsOrigin = `${base.protocol === "https:" ? "wss:" : "ws:"}//${base.host}`;
    const wsUrl = `${wsOrigin}${path}`;
    const timer = setTimeout(() => {
      fail(`ws-forward:${label}`, "连接超时（15s）");
      resolve();
    }, 15_000);

    let ws;
    try {
      ws = new WebSocket(wsUrl, { handshakeTimeout: 12_000 });
    }
    catch (err) {
      clearTimeout(timer);
      fail(`ws-forward:${label}`, err instanceof Error ? err.message : String(err));
      resolve();
      return;
    }

    ws.on("open", () => {
      if (!pingProbe) {
        clearTimeout(timer);
        pass(`ws-forward:${label}`, `connected ${wsUrl}`);
        ws.close();
        resolve();
        return;
      }
      ws.send("PING");
    });

    ws.on("message", (data) => {
      const text = String(data);
      clearTimeout(timer);
      ws.close();
      if (text === "PONG" || text.trim().startsWith("{") || text.trim().startsWith("[")) {
        pass(`ws-forward:${label}`, `connected ${wsUrl}`);
      }
      else {
        pass(`ws-forward:${label}`, `connected (frame: ${text.slice(0, 40)})`);
      }
      resolve();
    });

    ws.on("error", (err) => {
      clearTimeout(timer);
      fail(`ws-forward:${label}`, `${wsUrl} — ${err.message}`);
      resolve();
    });

    ws.on("close", () => {
      clearTimeout(timer);
      resolve();
    });
  });
}

function checkPmMarketWsRelay(hubBase) {
  return checkWsForwardRelay(hubBase, PM_WS_FORWARD_PATH, "PM-MARKET");
}

function checkPredictFunWsRelay(apiBase) {
  // PF hub 不响应 PING；upgrade 成功即可（订阅协议见 predictfun_market_hub.js）
  return checkWsForwardRelay(apiBase, PREDICT_WS_FORWARD_PATH, "PREDICTFUN-MARKET", { pingProbe: false });
}

async function main() {
  const apiBase = resolveApiBase();
  const pmHubBase = resolvePmMarketHubBase();
  console.log(`== probe-hk-relay apiBase=${apiBase} pmHubBase=${pmHubBase} ==`);

  if (!relayOnly)
    await checkUpstreamDirect();

  if (!upstreamOnly) {
    await checkHttpRelay(apiBase);
    await checkProxyStatus(apiBase);
    if (!skipWs) {
      await checkPmMarketWsRelay(pmHubBase);
      await checkPredictFunWsRelay(apiBase);
    }
  }

  const failed = results.filter(r => !r.ok);
  console.log("");
  if (failed.length) {
    console.error(`== FAIL (${failed.length}/${results.length}) ==`);
    for (const r of failed) console.error(`  - ${r.name}: ${r.detail}`);
    console.error("");
    console.error("修复提示:");
    console.error("  1. upstream 失败 → VPS 需能直连 polymarket.com（HK 出口）");
    console.error("  2. http-relay 失败 → 检查 HTTP_RELAY_ALLOWED_HOSTS、HTTP_RELAY_REQUIRE_TOKEN、pm2 restart changmen-esport");
    console.error("  3. ws-forward 失败 → PM-MARKET :3457 / PREDICTFUN-MARKET :3458 独立 hub + Caddy；再 pm2 restart");
    console.error("  4. predict.fun 失败 → curl -I https://api.predict.fun/v1/tags -H 'x-api-key: …'；检查 HTTP_RELAY_ALLOWED_HOSTS、PREDICT_FUN_API_KEY");
    process.exit(1);
  }
  console.log(`== PASS (${results.length}/${results.length}) ==`);
}

main().catch((err) => {
  console.error("probe-hk-relay:", err instanceof Error ? err.message : err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * GB14 player 90：platform_name 好博zmmzmm1 → 好博（仅显示标签，不改凭证）
 * Usage: node scripts/fix-gb14-haobo-platform-name.mjs [--apply]
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { ensurePgPoolReady, getPgPool, upsertTagPlatformByName } from "@changmen/db";
import { playerRowToAccountRecord } from "../../../../db/player_account_record.js";
import { loadAccountsForUser } from "../../../core/db/store.js";

const APPLY = process.argv.includes("--apply");
const PLAYER_ID = 90;
const NEW_PLATFORM_NAME = "好博";
const USER_NAME = "gb14";

loadChangmenEnv();
await ensurePgPoolReady();
const pool = getPgPool();

const { rows: users } = await pool.query(
  `SELECT id FROM profiles WHERE user_name ILIKE $1`,
  [USER_NAME],
);
const ownerUserId = users[0]?.id;
if (!ownerUserId)
  throw new Error(`user not found: ${USER_NAME}`);

const { rows: beforeRows } = await pool.query(
  `SELECT id, platform_id, platform_name, player_name, provider, account_data
   FROM players
   WHERE id = $1 AND owner_user_id = $2::uuid AND deleted_at IS NULL`,
  [PLAYER_ID, ownerUserId],
);
const before = beforeRows[0];
if (!before)
  throw new Error(`player ${PLAYER_ID} not found for ${USER_NAME}`);

const tag = await upsertTagPlatformByName(NEW_PLATFORM_NAME);
if (!tag?.id)
  throw new Error(`tag_platform upsert failed: ${NEW_PLATFORM_NAME}`);

const conflict = await pool.query(
  `SELECT id, platform_name, player_name
   FROM players
   WHERE owner_user_id = $1::uuid
     AND deleted_at IS NULL
     AND platform_id = $2
     AND player_name = $3
     AND id <> $4`,
  [ownerUserId, tag.id, before.player_name, PLAYER_ID],
);
if (conflict.rows.length) {
  throw new Error(
    `conflict: platform_id=${tag.id} player_name=${before.player_name} already used by player ${conflict.rows[0].id}`,
  );
}

console.log("=== before ===");
console.log(JSON.stringify({
  accountId: before.id,
  platformId: before.platform_id,
  platformName: before.platform_name,
  playerName: before.player_name,
  venueAccountName: before.account_data?.venueAccountName,
}, null, 2));

console.log("\n=== planned ===");
console.log(JSON.stringify({
  platformId: Number(tag.id),
  platformName: NEW_PLATFORM_NAME,
  playerName: before.player_name,
}, null, 2));

if (!APPLY) {
  console.log("\n[dry-run] pass --apply to write");
  await pool.end();
  process.exit(0);
}

const now = Date.now();
const { rowCount } = await pool.query(
  `UPDATE players
   SET platform_id = $2,
       platform_name = $3,
       updated_at = $4
   WHERE id = $1 AND owner_user_id = $5::uuid AND deleted_at IS NULL`,
  [PLAYER_ID, Number(tag.id), NEW_PLATFORM_NAME, now, ownerUserId],
);
if (!rowCount)
  throw new Error("update affected 0 rows");

await loadAccountsForUser(ownerUserId);

const { rows: afterRows } = await pool.query(
  `SELECT id, platform_id, platform_name, player_name, account_data
   FROM players WHERE id = $1`,
  [PLAYER_ID],
);
const wire = playerRowToAccountRecord({
  id: afterRows[0].id,
  platformId: afterRows[0].platform_id,
  platformName: afterRows[0].platform_name,
  playerName: afterRows[0].player_name,
  accountData: afterRows[0].account_data,
});

console.log("\n=== after ===");
console.log(JSON.stringify({
  accountId: wire.accountId,
  platformId: wire.platformId,
  platformName: wire.platformName,
  playerName: wire.playerName,
  venueAccountName: wire.venueAccountName,
  display: `${wire.platformName} / ${wire.venueAccountName || wire.playerName}`,
}, null, 2));

console.log("\ndone — 若生产环境请 pm2 restart changmen-esport 刷新其它进程缓存");
await pool.end();

#!/usr/bin/env node
/**
 * GB14：将 platform_name「品牌+账号」改为纯品牌名（对齐赢博/雷竞技显示）
 * Usage: node scripts/fix-gb14-platform-names.mjs [--apply]
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { ensurePgPoolReady, getPgPool, upsertTagPlatformByName } from "@changmen/db";
import { playerRowToAccountRecord } from "../../../../db/player_account_record.js";
import { loadAccountsForUser } from "../../../core/db/store.js";

const APPLY = process.argv.includes("--apply");
const USER_NAME = "gb14";

/** playerId → 目标平台标签（90 已改过，其余 OB 拼接名） */
const TARGET_BY_PLAYER = new Map([
  [90, "好博"],
  [91, "OD"],
  [92, "好博"],
  [93, "米兰"],
  [94, "好博"],
  [95, "星空"],
  [96, "好博"],
  [97, "九游"],
  [98, "好博"],
  [99, "开云"],
]);

loadChangmenEnv();
await ensurePgPoolReady();
const pool = getPgPool();

const { rows: users } = await pool.query(
  `SELECT id FROM profiles WHERE user_name ILIKE $1`,
  [USER_NAME],
);
const ownerUserId = users[0]?.id;
if (!ownerUserId)
  throw new Error(`user not found: ${USER_NAME}`);

const { rows: players } = await pool.query(
  `SELECT id, platform_id, platform_name, player_name, provider, account_data
   FROM players
   WHERE owner_user_id = $1::uuid AND deleted_at IS NULL
   ORDER BY id`,
  [ownerUserId],
);

const tagIdByName = new Map();
async function tagId(name) {
  const label = String(name || "").trim();
  if (!label)
    return null;
  if (tagIdByName.has(label))
    return tagIdByName.get(label);
  const row = await upsertTagPlatformByName(label);
  const id = row?.id ? Number(row.id) : null;
  tagIdByName.set(label, id);
  return id;
}

const planned = [];
for (const row of players) {
  const id = Number(row.id);
  const target = TARGET_BY_PLAYER.get(id);
  if (!target)
    continue;
  if (String(row.platform_name || "").trim() === target)
    continue;
  const platformId = await tagId(target);
  if (!platformId)
    throw new Error(`tag_platform failed: ${target}`);
  planned.push({
    id,
    from: row.platform_name,
    to: target,
    platformId,
    playerName: row.player_name,
  });
}

if (!planned.length) {
  console.log("nothing to change");
  await pool.end();
  process.exit(0);
}

console.log("=== planned updates ===");
for (const p of planned) {
  console.log(`${p.id}\t${p.from} → ${p.to}\t(player=${p.playerName})`);
}

for (const p of planned) {
  const { rows: conflict } = await pool.query(
    `SELECT id FROM players
     WHERE owner_user_id = $1::uuid AND deleted_at IS NULL
       AND platform_id = $2 AND player_name = $3 AND id <> $4`,
    [ownerUserId, p.platformId, p.playerName, p.id],
  );
  if (conflict.length) {
    throw new Error(
      `conflict player ${p.id} → ${p.to}: platform_id=${p.platformId} player_name=${p.playerName} taken by ${conflict[0].id}`,
    );
  }
}

if (!APPLY) {
  console.log("\n[dry-run] pass --apply to write");
  await pool.end();
  process.exit(0);
}

const now = Date.now();
for (const p of planned) {
  const { rowCount } = await pool.query(
    `UPDATE players
     SET platform_id = $2, platform_name = $3, updated_at = $4
     WHERE id = $1 AND owner_user_id = $5::uuid AND deleted_at IS NULL`,
    [p.id, p.platformId, p.to, now, ownerUserId],
  );
  if (!rowCount)
    throw new Error(`update failed for player ${p.id}`);
}

await loadAccountsForUser(ownerUserId);

console.log("\n=== after (display preview) ===");
const { rows: after } = await pool.query(
  `SELECT id, platform_id, platform_name, player_name, provider, account_data
   FROM players WHERE owner_user_id = $1::uuid AND deleted_at IS NULL ORDER BY id`,
  [ownerUserId],
);
for (const row of after) {
  const wire = playerRowToAccountRecord({
    id: row.id,
    platformId: row.platform_id,
    platformName: row.platform_name,
    playerName: row.player_name,
    provider: row.provider,
    accountData: row.account_data,
  });
  const right = wire.venueAccountName || wire.playerName;
  console.log(`${wire.accountId}\t${wire.platformName} / ${right}`);
}

console.log("\ndone — 生产环境请 pm2 restart changmen-esport");
await pool.end();

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 用场馆 API 判定重复 order_id 的真实归属 player，仅删除重复组内的多余副本。
 * 非重复 order_id 的订单一律不碰。
 *
 *   node scripts/resolve-dup-orders-by-venue.mjs --user GB14 --dry-run
 *   node scripts/resolve-dup-orders-by-venue.mjs --user GB14 --execute
 *   node scripts/resolve-dup-orders-by-venue.mjs --user GB13 --month 2026-07 --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { playerRowToAccountRecord } from "../../../../db/player_account_record.js";

loadChangmenEnv();
const { initDatabaseUrl, getPgPool } = await import("@changmen/db");

function parseArgs(argv) {
  const out = { dryRun: true, userName: "", month: "", provider: "OB", help: false };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--month")
      out.month = String(argv[++i] ?? "").trim();
    else if (a === "--provider")
      out.provider = String(argv[++i] ?? "OB").trim();
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function formatDateKey(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

function obHeaders(account) {
  const mobile = Boolean(account.userAgent && /mobile/i.test(account.userAgent));
  const h = {
    device: mobile ? "2" : "1",
    lang: "cn",
    token: account.token || "",
    "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
  };
  if (account.userAgent)
    h["User-Agent"] = account.userAgent;
  if (account.referer)
    h.Referer = account.referer;
  return h;
}

function obTimeChunks(startMs, endMs) {
  const chunks = [];
  const start = new Date(startMs);
  const end = new Date(endMs);
  let cur = new Date(start);
  while (cur <= end) {
    const chunkEnd = new Date(cur);
    chunkEnd.setDate(chunkEnd.getDate() + 6);
    if (chunkEnd > end)
      chunkEnd.setTime(end.getTime());
    chunks.push({
      begin: `${formatDateKey(cur)} 00:00:00`,
      end: `${formatDateKey(chunkEnd)} 23:59:59`,
    });
    cur = new Date(chunkEnd);
    cur.setDate(cur.getDate() + 1);
  }
  return chunks;
}

async function fetchObOrderIds(account, beginTime, endTime) {
  const ids = new Set();
  for (const status of [1, 2]) {
    let page = 1;
    for (;;) {
      const qs = new URLSearchParams({
        page: String(page),
        page_size: "100",
        begin_time: beginTime,
        end_time: endTime,
        status: String(status),
      });
      const url = `${String(account.gateway).replace(/\/$/, "")}/game/orderList?${qs}`;
      const res = await fetch(url, { method: "GET", headers: obHeaders(account) });
      const text = await res.text();
      if (res.status >= 400)
        throw new Error(`HTTP ${res.status}: ${text.slice(0, 100)}`);
      const data = JSON.parse(text);
      if (!data || data.status !== "true")
        break;
      const bets = data.data?.bet ?? [];
      for (const row of bets) {
        const id = String(row.id ?? "");
        if (id)
          ids.add(id);
      }
      if (bets.length < 100)
        break;
      page += 1;
      await sleep(200);
    }
    await sleep(200);
  }
  return ids;
}

async function fetchObPlayerIndex(account, startMs, endMs) {
  const all = new Set();
  for (const chunk of obTimeChunks(startMs, endMs)) {
    const part = await fetchObOrderIds(account, chunk.begin, chunk.end);
    for (const id of part)
      all.add(id);
    await sleep(400);
  }
  return all;
}

function backupTableName(userName) {
  const slug = userName.toLowerCase().replace(/[^a-z0-9]+/g, "");
  return `orders_dup_venue_resolve_backup_${slug}_20260712`;
}

function printHelp() {
  console.log(`
用法:
  node scripts/resolve-dup-orders-by-venue.mjs --user GB14 --dry-run
  node scripts/resolve-dup-orders-by-venue.mjs --user GB14 --execute

仅处理 RDS 内重复 order_id 组（同 user + provider + order_id 多 player）。
场馆 API 判定真实 owner；只删组内非 owner 副本。非重复单绝不删除。
`);
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help || !args.userName) {
    printHelp();
    process.exit(args.help ? 0 : 1);
  }

  await initDatabaseUrl();
  const pool = getPgPool();

  if (!pool) {
    console.error("DATABASE_URL 未配置");
    process.exit(1);
  }

  const { rows: users } = await pool.query(
    `SELECT id, user_name FROM users WHERE user_name ILIKE $1 LIMIT 1`,
    [args.userName],
  );
  const userId = users[0]?.id;
  if (!userId) {
    console.error(`用户 ${args.userName} 不存在`);
    process.exit(1);
  }

  const provider = args.provider;

  const dupGroups = await pool.query(
    `SELECT o.provider, o.order_id,
            COUNT(*)::int AS rows,
            array_agg(o.id ORDER BY o.player_id) AS order_row_ids,
            array_agg(o.player_id ORDER BY o.player_id) AS player_ids,
            MIN(o.create_at)::bigint AS min_create_at,
            MAX(o.create_at)::bigint AS max_create_at
     FROM ${financialOrdersRelation("o")}
     WHERE o.user_id = $1::uuid AND o.provider = $2
     GROUP BY o.provider, o.order_id
     HAVING COUNT(*) > 1
     ORDER BY o.order_id`,
    [userId, provider],
  );

  if (!dupGroups.rows.length) {
    console.log(`${args.userName} 无 ${provider} 重复 order_id`);
    await pool.end();
    return;
  }

  console.log(`${args.userName} ${provider} 重复组: ${dupGroups.rows.length}`);

  let startMs = Math.min(...dupGroups.rows.map(g => Number(g.min_create_at)));
  let endMs = Math.max(...dupGroups.rows.map(g => Number(g.max_create_at)));
  if (args.month) {
    const m = args.month.match(/^(\d{4})-(\d{2})$/);
    if (m) {
      const y = Number(m[1]);
      const mo = Number(m[2]);
      startMs = new Date(y, mo - 1, 1).getTime();
      endMs = new Date(y, mo, 0, 23, 59, 59, 999).getTime();
    }
  }
  // 前后各扩 1 天
  startMs -= 86400000;
  endMs += 86400000;

  const { rows: playerRows } = await pool.query(
    `SELECT pl.*
     FROM players pl
     WHERE pl.owner_user_id = $1::uuid
       AND pl.deleted_at IS NULL
       AND pl.provider = $2
     ORDER BY pl.id`,
    [userId, provider],
  );

  const players = playerRows.map(row => ({
    playerId: Number(row.id),
    label: `${row.id} ${row.platform_name}/${row.player_name}`,
    account: playerRowToAccountRecord({
      id: row.id,
      platformName: row.platform_name,
      playerName: row.player_name,
      provider: row.provider,
      accountData: row.account_data,
    }),
  }));

  console.log(`拉场馆 ${provider} orderList ${formatDateKey(new Date(startMs))} .. ${formatDateKey(new Date(endMs))}`);
  /** @type {Map<string, number>} order_id -> player_id */
  const venueOwner = new Map();
  /** @type {Map<string, Set<number>>} order_id -> players that have it */
  const venueHits = new Map();

  /** @type {Array<{playerId:number, label:string, error:string}>} */
  const fetchErrors = [];

  for (const p of players) {
    const { account, playerId, label } = p;
    if (!account.gateway || !account.token) {
      console.log(`  [SKIP] ${label} 无凭证`);
      continue;
    }
    try {
      const ids = await fetchObPlayerIndex(account, startMs, endMs);
      console.log(`  ${label}: 场馆 ${ids.size} 条`);
      for (const orderId of ids) {
        if (!venueHits.has(orderId))
          venueHits.set(orderId, new Set());
        venueHits.get(orderId).add(playerId);
      }
    }
    catch (err) {
      console.error(`  [ERR] ${label}: ${err.message}`);
      fetchErrors.push({ playerId, label, error: err.message });
    }
  }

  if (fetchErrors.length === players.length) {
    console.error("全部 OB 账号拉单失败，中止");
    process.exit(1);
  }

  for (const [orderId, hits] of venueHits) {
    if (hits.size === 1)
      venueOwner.set(orderId, [...hits][0]);
    else if (hits.size > 1)
      console.warn(`  [WARN] 场馆多账号同 order_id=${orderId}: ${[...hits].join(",")}`);
  }

  /** @type {Array<{id:number, order_id:string, player_id:number, keep:number, reason:string}>} */
  const toDelete = [];
  /** @type {Array<{order_id:string, reason:string}>} */
  const skipped = [];

  for (const g of dupGroups.rows) {
    const orderId = String(g.order_id);
    const rowIds = g.order_row_ids.map(Number);
    const playerIds = g.player_ids.map(Number);
    const owner = venueOwner.get(orderId);

    if (!owner) {
      skipped.push({ order_id: orderId, reason: "场馆未命中任何账号" });
      continue;
    }
    if (!playerIds.includes(owner)) {
      skipped.push({ order_id: orderId, reason: `场馆 owner=${owner} 不在 RDS 重复组 [${playerIds.join(",")}]` });
      continue;
    }

    for (let i = 0; i < rowIds.length; i += 1) {
      const rowId = rowIds[i];
      const pid = playerIds[i];
      if (pid !== owner) {
        toDelete.push({
          id: rowId,
          order_id: orderId,
          player_id: pid,
          keep: owner,
          reason: `场馆归属 player ${owner}`,
        });
      }
    }
  }

  console.log(`\n将删除 ${toDelete.length} 条（仅重复组内非 owner 副本）`);
  for (const d of toDelete) {
    console.log(`  DELETE id=${d.id} player=${d.player_id} order=${d.order_id} keep=${d.keep}`);
  }

  if (skipped.length) {
    console.log(`\n跳过 ${skipped.length} 组（不删任何行）:`);
    for (const s of skipped)
      console.log(`  ${s.order_id}: ${s.reason}`);
  }

  // 安全：非重复 order 总数不变
  const nonDupCount = await pool.query(
    `SELECT COUNT(*)::int AS n
     FROM ${financialOrdersRelation("o")}
     WHERE o.user_id = $1::uuid AND o.provider = $2
       AND (o.user_id, o.provider, o.order_id) NOT IN (
         SELECT user_id, provider, order_id
         FROM ${financialOrdersRelation()}
         WHERE user_id = $1::uuid AND provider = $2
         GROUP BY user_id, provider, order_id
         HAVING COUNT(*) > 1
       )`,
    [userId, provider],
  );
  console.log(`\n非重复 ${provider} 订单: ${nonDupCount.rows[0].n} 条（脚本不会删除）`);

  if (!toDelete.length) {
    console.log("\n无需删除");
    await pool.end();
    return;
  }

  if (args.dryRun) {
    console.log("\n[dry-run] 无变更");
    console.log(`执行: node scripts/resolve-dup-orders-by-venue.mjs --user ${args.userName} --execute`);
    await pool.end();
    return;
  }

  const deleteIds = toDelete.map(d => d.id);
  const BACKUP_TABLE = backupTableName(args.userName);
  const client = await pool.connect();

  try {
    await client.query("BEGIN");
    await client.query(`DROP TABLE IF EXISTS ${BACKUP_TABLE}`);
    await client.query(
      `CREATE TABLE ${BACKUP_TABLE} AS
       SELECT * FROM ${financialOrdersRelation()} WHERE user_id = $1::uuid AND id = ANY($2::bigint[])`,
      [userId, deleteIds],
    );
    const del = await client.query(
      `DELETE FROM ${financialOrdersRelation()} WHERE user_id = $1::uuid AND id = ANY($2::bigint[])`,
      [userId, deleteIds],
    );
    await client.query("COMMIT");
    console.log(`\n已删 ${del.rowCount ?? 0} 条，备份 ${BACKUP_TABLE}`);
  }
  catch (err) {
    await client.query("ROLLBACK");
    console.error("rollback:", err.message);
    process.exit(1);
  }
  finally {
    client.release();
    await pool.end();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 从场馆 API 拉取指定用户活跃 player 某月订单，经 saveOrder 写入 RDS。
 *
 *   node scripts/sync-venue-orders-month.mjs --user GB13 --month 2026-07 --dry-run
 *   node scripts/sync-venue-orders-month.mjs --user GB13 --month 2026-07 --execute
 *   node scripts/sync-venue-orders-month.mjs --user GB13 --month 2026-07 --player-id 79 --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { parseVenueCreateAt } from "@changmen/shared/time/match_time";
import { accountMultiplyScale } from "@changmen/shared/account_multiply";
import { buildPbAuthHeaders } from "./lib/pb_auth.mjs";
import { playerRowToAccountRecord } from "../../../../db/player_account_record.js";
import { saveOrder } from "../../../core/account/order_store.js";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool } = await import("@changmen/db");

function parseArgs(argv) {
  const out = {
    dryRun: true,
    userName: "",
    month: "",
    playerId: 0,
    help: false,
  };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--month")
      out.month = String(argv[++i] ?? "").trim();
    else if (a === "--player-id")
      out.playerId = Number(argv[++i]) || 0;
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function parseMonth(monthStr) {
  const m = String(monthStr).trim().match(/^(\d{4})-(\d{2})$/);
  if (!m)
    throw new Error(`无效 --month: ${monthStr}，应为 YYYY-MM`);
  const year = Number(m[1]);
  const month = Number(m[2]);
  if (month < 1 || month > 12)
    throw new Error(`无效月份: ${monthStr}`);
  const start = new Date(year, month - 1, 1, 0, 0, 0, 0);
  const end = new Date(year, month, 0, 23, 59, 59, 999);
  return {
    label: monthStr,
    startMs: start.getTime(),
    endMs: end.getTime(),
    startKey: formatDateKey(start),
    endKey: formatDateKey(end),
  };
}

function formatDateKey(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

function formatDateTime(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  const hh = String(d.getHours()).padStart(2, "0");
  const min = String(d.getMinutes()).padStart(2, "0");
  const sec = String(d.getSeconds()).padStart(2, "0");
  return `${y}-${m}-${day} ${hh}:${min}:${sec}`;
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

function obNum(v) {
  if (v && typeof v.toNumber === "function")
    return v.toNumber();
  return Number(v) || 0;
}

function normalizeProvider(p) {
  return String(p ?? "").trim().toLowerCase();
}

function inMonthRange(createAt, range) {
  const ts = parseVenueCreateAt(createAt, 0);
  return ts >= range.startMs && ts <= range.endMs;
}

function obHeaders(account) {
  const mobile = Boolean(account.userAgent && /mobile/i.test(account.userAgent));
  const base = {
    device: mobile ? "2" : "1",
    lang: "cn",
    token: account.token || "",
    "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
  };
  if (account.userAgent)
    base["User-Agent"] = account.userAgent;
  if (account.referer)
    base.Referer = account.referer;
  return base;
}

function obUrl(account, path) {
  return `${String(account.gateway).replace(/\/$/, "")}${path.startsWith("/") ? path : `/${path}`}`;
}

async function obGet(account, path) {
  const res = await fetch(obUrl(account, path), {
    method: "GET",
    headers: obHeaders(account),
  });
  const text = await res.text();
  if (res.status >= 400)
    throw new Error(`OB HTTP ${res.status}: ${text.slice(0, 160)}`);
  return JSON.parse(text);
}

function mapObBetStatus(raw) {
  let money = 0;
  let status = "none";
  switch (Number(raw)) {
    case 2:
      status = "reject";
      break;
    case 4:
    case 7:
      status = "return";
      break;
    case 5:
      status = "win";
      break;
    case 6:
      status = "lose";
      break;
    default:
      status = "none";
  }
  return { status, money };
}

function mapObOrderRow(row, provider) {
  const teams = String(row.team_cn_names ?? "")
    .split(",")
    .map(t => t.replace(/&nbsp;/g, " "));
  const round = obNum(row.round);
  const stageLabel = round === 0 ? "全场" : `地图${round}`;
  const marketName = String(row.market_cn_name ?? "").replace(/&nbsp;/g, " ");
  let item = String(row.odd_name ?? "");
  if (item === "@T1")
    item = teams[0] ?? item;
  if (item === "@T2")
    item = teams[1] ?? item;

  const betMoney = obNum(row.bet_amount);
  const reward = obNum(row.win_amount);
  let { status, money } = mapObBetStatus(row.bet_status);
  if (status === "win" || status === "lose")
    money = reward - betMoney;

  return {
    provider: provider || "OB",
    orderId: String(row.id ?? ""),
    odds: obNum(row.odd),
    createAt: parseVenueCreateAt(row.bet_time),
    betMoney,
    reward,
    money,
    status,
    game: String(row.game_id ?? ""),
    match: teams.join(" vs "),
    bet: `[${stageLabel}]${marketName}`,
    item,
  };
}

/** 按 7 天切片拉 OB orderList，支持分页 */
async function fetchObOrdersForRange(account, beginTime, endTime) {
  const byId = new Map();
  for (const status of [1, 2]) {
    let page = 1;
    for (;;) {
      const qs = new URLSearchParams({
        page: String(page),
        page_size: "100",
        begin_time: beginTime,
        end_time: endTime,
        status: String(status),
      });
      const data = await obGet(account, `/game/orderList?${qs.toString()}`);
      if (!data || data.status !== "true")
        break;
      const bets = data.data?.bet ?? [];
      if (!bets.length)
        break;
      for (const row of bets) {
        const order = mapObOrderRow(row, account.provider);
        if (order.orderId)
          byId.set(order.orderId, order);
      }
      if (bets.length < 100)
        break;
      page += 1;
      await sleep(300);
    }
    await sleep(300);
  }
  return [...byId.values()];
}

function obTimeChunks(range) {
  const chunks = [];
  const start = new Date(range.startMs);
  const end = new Date(range.endMs);
  let cur = new Date(start);
  while (cur <= end) {
    const chunkEnd = new Date(cur);
    chunkEnd.setDate(chunkEnd.getDate() + 6);
    if (chunkEnd > end)
      chunkEnd.setTime(end.getTime());
    chunks.push({
      begin: `${formatDateKey(cur)} 00:00:00`,
      end: `${formatDateKey(chunkEnd)} 23:59:59`,
    });
    cur = new Date(chunkEnd);
    cur.setDate(cur.getDate() + 1);
  }
  return chunks;
}

async function fetchObOrdersMonth(account, range) {
  const byId = new Map();
  for (const chunk of obTimeChunks(range)) {
    const rows = await fetchObOrdersForRange(account, chunk.begin, chunk.end);
    for (const o of rows) {
      if (inMonthRange(o.createAt, range))
        byId.set(o.orderId, o);
    }
    await sleep(500);
  }
  return [...byId.values()].sort((a, b) => b.createAt - a.createAt);
}

function mapPbWagerRow(u, multiply) {
  const gameFull = String(u[28] ?? "");
  const game = gameFull.split(" - ")[0] ?? "";
  const match = String(u[9] ?? "");
  const mapNum = Number(u[42]) || 0;
  const bet = mapNum === 0 ? "全场" : `地图${mapNum}`;
  const item = String(u[22] ?? "");
  const orderId = String(u[7] ?? "");
  const odds = Number(u[16]) || 0;
  const reward = Number(u[29]) + Number(u[0] || 0);
  const betMoney = Number(u[29]) || 0;
  const createAt = Number(u[19]) || 0;
  const state = String(u[18] ?? "");

  let status = "none";
  let money = 0;
  if (state === "SETTLED") {
    status = reward > 0 ? "win" : "lose";
    money = reward - betMoney;
  }
  else if (state === "CANCELLED") {
    status = "return";
    money = 0;
  }

  return {
    provider: "PB",
    orderId,
    odds,
    createAt,
    betMoney: betMoney * multiply,
    reward: reward * multiply,
    money: money * multiply,
    status,
    game,
    match,
    bet,
    item,
  };
}

async function pbPost(account, path, body, extraHeaders = {}) {
  const headers = buildPbAuthHeaders(account, extraHeaders);
  if (!headers)
    throw new Error("PB token 无法解析 auth headers");
  const url = `${String(account.gateway).replace(/\/$/, "")}${path}`;
  const res = await fetch(url, {
    method: "POST",
    headers: {
      ...headers,
      ...(typeof body === "string"
        ? { "content-type": "application/x-www-form-urlencoded; charset=UTF-8" }
        : { "content-type": "application/json; charset=UTF-8" }),
    },
    body: typeof body === "string"
      ? body
      : JSON.stringify(body),
  });
  const text = await res.text();
  if (res.status >= 400)
    throw new Error(`PB HTTP ${res.status}: ${text.slice(0, 160)}`);
  if (!text)
    return null;
  return JSON.parse(text);
}

function wagerFilterBody(fields) {
  return new URLSearchParams(
    Object.fromEntries(Object.entries(fields).map(([k, v]) => [k, String(v)])),
  ).toString();
}

async function fetchPbOrdersMonth(account, range) {
  const multiply = accountMultiplyScale(account.multiply);
  const path = `/member-service/v2/wager-filter?locale=zh_CN`;
  const begin = `${range.startKey} 00:00:00`;
  const end = `${range.endKey} 23:59:59`;

  const filters = [
    {
      f: begin,
      t: end,
      d: -1,
      s: "SETTLED",
      sd: false,
      type: "WAGER",
      product: "SB",
      timezone: "GMT-4",
      sportId: "",
      leagueId: "",
    },
    {
      f: begin,
      t: end,
      d: -1,
      s: "OPEN",
      sd: false,
      type: "EVENT",
      product: "SB",
      timezone: "GMT-4",
      sportId: "",
      leagueId: "",
    },
  ];

  const byId = new Map();
  for (const filter of filters) {
    const data = await pbPost(account, path, wagerFilterBody(filter));
    if (!data || (typeof data === "object" && !Array.isArray(data) && "error" in data))
      continue;
    if (!Array.isArray(data))
      continue;
    for (const raw of data) {
      if (!Array.isArray(raw))
        continue;
      const order = mapPbWagerRow(raw, multiply);
      if (!order.orderId)
        continue;
      if (!inMonthRange(order.createAt, range))
        continue;
      byId.set(order.orderId, order);
    }
    await sleep(500);
  }
  return [...byId.values()].sort((a, b) => b.createAt - a.createAt);
}

function rayHeaders(account) {
  return {
    authorization: account.token || "",
    "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
  };
}

function rayUrl(account, path) {
  return `${String(account.gateway).replace(/\/$/, "")}${path.startsWith("/") ? path : `/${path}`}`;
}

function mapRayOrderRow(row) {
  const detail = row.detail?.[0];
  if (!detail)
    return null;

  let status = "none";
  let money = 0;
  const stake = Number(detail.stake) || 0;
  const totalBonus = Number(row.total_bonus) || 0;

  if (row.status === 0) {
    status = "none";
  }
  else if (row.status === 1) {
    money = totalBonus - stake;
    if (row.win === 1)
      status = "win";
    else if (row.win === 0)
      status = "lose";
  }
  else if (row.status === 4) {
    status = "reject";
  }

  const titleParts = String(detail.title ?? "").split("\n");
  let bet = titleParts.join(" ");
  let item = "";
  if (titleParts.length === 2) {
    bet = titleParts[0] ?? "";
    item = titleParts[1] ?? "";
  }

  return {
    provider: "RAY",
    orderId: String(row.order_number ?? ""),
    odds: Number(detail.odds) || 0,
    createAt: parseVenueCreateAt(row.create_time),
    game: String(detail.game_id ?? ""),
    match: String(detail.match_name ?? ""),
    bet: `${detail.match_stage ?? ""} ${bet}`.trim(),
    item,
    betMoney: stake,
    reward: totalBonus,
    status,
    money,
  };
}

async function fetchRayOrdersMonth(account, range) {
  const res = await fetch(rayUrl(account, "/v2/order"), {
    method: "GET",
    headers: rayHeaders(account),
  });
  const text = await res.text();
  if (res.status >= 400)
    throw new Error(`RAY HTTP ${res.status}: ${text.slice(0, 160)}`);
  const data = JSON.parse(text);
  if (data.code !== 200 || !Array.isArray(data.result))
    return [];
  const orders = [];
  for (const row of data.result) {
    const mapped = mapRayOrderRow(row);
    if (mapped && inMonthRange(mapped.createAt, range))
      orders.push(mapped);
  }
  return orders.sort((a, b) => b.createAt - a.createAt);
}

async function fetchVenueOrdersMonth(account, range) {
  const p = normalizeProvider(account.provider);
  if (p === "ob" || p.includes("ob"))
    return fetchObOrdersMonth(account, range);
  if (p === "pb" || p.includes("pb"))
    return fetchPbOrdersMonth(account, range);
  if (p === "ray" || p.includes("ray"))
    return fetchRayOrdersMonth(account, range);
  throw new Error(`不支持的平台 provider=${account.provider}`);
}

async function loadActivePlayers(pool, userName, playerIdFilter) {
  const params = [userName];
  let sql = `
    SELECT pl.*, u.user_name
    FROM players pl
    JOIN users u ON u.id = pl.owner_user_id
    WHERE u.user_name ILIKE $1
      AND pl.deleted_at IS NULL
      AND pl.owner_user_id IS NOT NULL
  `;
  if (playerIdFilter > 0) {
    params.push(playerIdFilter);
    sql += ` AND pl.id = $${params.length}`;
  }
  sql += " ORDER BY pl.id ASC";
  const { rows } = await pool.query(sql, params);
  return rows.map((row) => {
    const account = playerRowToAccountRecord({
      id: row.id,
      platformId: row.platform_id,
      platformName: row.platform_name,
      playerName: row.player_name,
      provider: row.provider,
      credit: row.credit,
      totalBalance: row.total_balance,
      accountData: row.account_data,
      updatedAt: row.updated_at,
    });
    return {
      playerId: Number(row.id),
      userId: String(row.owner_user_id),
      userName: row.user_name,
      account,
    };
  });
}

async function countRdsOrdersInMonth(pool, userId, playerId, range) {
  const { rows } = await pool.query(
    `SELECT COUNT(*)::int AS n
     FROM ${financialOrdersRelation()}
     WHERE user_id = $1::uuid
       AND player_id = $2
       AND create_at >= $3
       AND create_at <= $4`,
    [userId, playerId, range.startMs, range.endMs],
  );
  return rows[0]?.n ?? 0;
}

function printHelp() {
  console.log(`
用法:
  node scripts/sync-venue-orders-month.mjs --user GB13 --month 2026-07 --dry-run
  node scripts/sync-venue-orders-month.mjs --user GB13 --month 2026-07 --execute
  node scripts/sync-venue-orders-month.mjs --user GB13 --month 2026-07 --player-id 79 --execute

从场馆 API 拉取活跃 player 指定月份订单，经 saveOrder upsert 到 RDS。
默认 --dry-run 只拉单统计，不写库。
`);
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help || !args.userName || !args.month) {
    printHelp();
    process.exit(args.help ? 0 : 1);
  }

  const range = parseMonth(args.month);
  await initDatabaseUrl();
  const pool = getPgPool();
  if (!pool) {
    console.error("DATABASE_URL 未配置");
    process.exit(1);
  }

  const players = await loadActivePlayers(pool, args.userName, args.playerId);
  if (!players.length) {
    console.error(`用户 ${args.userName} 无活跃 player${args.playerId ? ` id=${args.playerId}` : ""}`);
    process.exit(1);
  }

  console.log(`user=${args.userName} month=${range.label} players=${players.length} mode=${args.dryRun ? "dry-run" : "execute"}`);
  console.log(`range=${range.startKey} .. ${range.endKey} (${range.startMs} .. ${range.endMs})`);

  const summary = [];
  for (const row of players) {
    const { playerId, userId, account } = row;
    const label = `${playerId} ${account.provider}/${account.platformName}/${account.playerName}`;
    if (!account.gateway || !account.token) {
      console.log(`\n[SKIP] ${label} — 缺少 gateway 或 token`);
      summary.push({ playerId, label, skip: "no-creds", venue: 0, rds: 0, saved: 0 });
      continue;
    }

    const rdsBefore = await countRdsOrdersInMonth(pool, userId, playerId, range);
    console.log(`\n[${label}] RDS ${range.label} 现有 ${rdsBefore} 条，拉场馆…`);

    let venueOrders = [];
    try {
      venueOrders = await fetchVenueOrdersMonth(account, range);
    }
    catch (err) {
      console.error(`  [ERR] ${err.message}`);
      summary.push({ playerId, label, skip: "fetch-error", venue: 0, rds: rdsBefore, saved: 0, err: err.message });
      continue;
    }

    console.log(`  场馆 ${range.label} ${venueOrders.length} 条`);
    if (venueOrders.length) {
      const sample = venueOrders.slice(0, 3).map(o =>
        `    ${o.orderId} ${new Date(o.createAt).toISOString().slice(0, 19)} ${o.status} ${o.match?.slice(0, 40)}`,
      );
      console.log(sample.join("\n"));
      if (venueOrders.length > 3)
        console.log(`    … +${venueOrders.length - 3} more`);
    }

    let saved = 0;
    if (!args.dryRun && venueOrders.length) {
      const ok = await saveOrder(playerId, venueOrders, userId, account.provider || "");
      saved = ok ? venueOrders.length : 0;
      console.log(`  saveOrder => ${saved} 条`);
    }

    const rdsAfter = args.dryRun
      ? rdsBefore
      : await countRdsOrdersInMonth(pool, userId, playerId, range);
    summary.push({
      playerId,
      label,
      venue: venueOrders.length,
      rds: rdsAfter,
      rdsBefore,
      saved,
    });
  }

  console.log("\n=== SUMMARY ===");
  console.log("playerId\tvenue\trdsBefore\trdsAfter\tsaved\tlabel");
  for (const s of summary) {
    if (s.skip) {
