#!/usr/bin/env node
import { financialOrdersRelation } from "@changmen/db";
/**
 * 扫描 / 修复 PM 买单卖出盈亏双计：
 * - 0.99 纸面 win money + 卖出 PnL 累加 → money ≈ 2× 真实卖出盈亏
 * - 卖单仍保留 money 且买单也有 money（迁移双计风险）
 *
 *   node scripts/ops/incidents/scan-fix-pm-sell-pnl-double.mjs --dry-run
 *   node scripts/ops/incidents/scan-fix-pm-sell-pnl-double.mjs --execute
 *   node scripts/ops/incidents/scan-fix-pm-sell-pnl-double.mjs --match "SAW Youngsters" --execute
 *   node scripts/ops/incidents/scan-fix-pm-sell-pnl-double.mjs --user gb14 --dry-run
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";

loadChangmenEnv();

const { initDatabaseUrl, getPgPool, fetchProfiles } = await import("@changmen/db");

function parseArgs(argv) {
  const out = {
    dryRun: true,
    userName: "",
    match: "",
    help: false,
    /** 仅列出，不按「≈2×」自动改（仍可用 --match 点修） */
    scanOnly: false,
  };
  for (let i = 2; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === "--execute")
      out.dryRun = false;
    else if (a === "--dry-run")
      out.dryRun = true;
    else if (a === "--scan-only")
      out.scanOnly = true;
    else if (a === "--user")
      out.userName = String(argv[++i] ?? "").trim();
    else if (a === "--match")
      out.match = String(argv[++i] ?? "").trim();
    else if (a === "--help" || a === "-h")
      out.help = true;
  }
  return out;
}

function rawObj(row) {
  const raw = row?.raw;
  return raw && typeof raw === "object" && !Array.isArray(raw) ? { ...raw } : {};
}

function num(v, d = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
}

function shTime(ms) {
  const t = Number(ms) || 0;
  if (!t)
    return "";
  return new Date(t).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai", hour12: false });
}

function shortId(id) {
  const s = String(id ?? "");
  return s.length > 14 ? `${s.slice(0, 10)}…` : s;
}

/** 期望买单已实现盈亏 CNY：优先卖单 pmRealizedPnlUsdc 之和 */
function expectedBuyMoneyCny(sells, fx) {
  let fromPnl = 0;
  let fromProceedsCost = 0;
  let hasPnl = false;
  for (const s of sells) {
    const raw = rawObj(s);
    const pnlUsdc = num(raw.pmRealizedPnlUsdc);
    if (Math.abs(pnlUsdc) > 1e-9) {
      hasPnl = true;
      fromPnl += Math.round(pnlUsdc * fx);
    }
    const proceedsCny = num(s.bet_money);
    const costUsdc = num(raw.pmStakeUsdc);
    if (proceedsCny > 0 && costUsdc > 0)
      fromProceedsCost += Math.round(proceedsCny - costUsdc * fx);
  }
  if (hasPnl)
    return fromPnl;
  return fromProceedsCost;
}

function classifyIssue(buy, sells, fx) {
  const raw = rawObj(buy);
  const buyMoney = num(buy.money);
  const expected = expectedBuyMoneyCny(sells, fx);
  const sellMoneySum = sells.reduce((sum, s) => sum + num(s.money), 0);
  const state = String(raw.pmSellState ?? "").toLowerCase();
  const reasons = [];

  if (!(state === "closed" || state === "partial"))
    return null;
  if (!sells.length)
    return null;

  const near = (a, b, tol = 2) => Math.abs(a - b) <= tol;
  const absBuy = Math.abs(buyMoney);
  const absExp = Math.abs(expected);

  // 主问题：≈ 2× 卖出盈亏（纸面 + 卖出）
  if (absExp >= 5 && near(absBuy, absExp * 2) && !near(absBuy, absExp))
    reasons.push("money_approx_2x_sell_pnl");

  // 买单有盈亏且关联卖单仍非 0（旧模型残留 / 迁移双计）
  if (Math.abs(sellMoneySum) > 1 && absBuy > 1)
    reasons.push("buy_and_sell_both_have_money");

  // 买单 money 与卖单 pnl 差一整份 expected（且接近 sellMoneySum + expected）
  if (
    absExp >= 5
    && Math.abs(sellMoneySum) > 1
    && near(absBuy, absExp + Math.abs(sellMoneySum))
  ) {
    reasons.push("buy_money_equals_sell_money_plus_pnl");
  }

  // 期望可得但买单为 0（另一类：漏记）
  if (absExp >= 5 && absBuy <= 1)
    reasons.push("buy_money_zero_but_sell_pnl_nonzero");

  // 期望可得但偏差大（非 2×，供人工看）
  if (
    absExp >= 5
    && absBuy > 1
    && !near(absBuy, absExp)
    && !near(absBuy, absExp * 2)
    && Math.abs(absBuy - absExp) / absExp > 0.25
  ) {
    reasons.push("buy_money_far_from_sell_pnl");
  }

  if (!reasons.length)
    return null;

  return {
    orderId: buy.order_id,
    orderIdShort: shortId(buy.order_id),
    userId: buy.user_id,
    playerId: buy.player_id,
    match: buy.match,
    item: buy.item,
    bet: buy.bet,
    link: buy.link,
    createAtShanghai: shTime(buy.create_at),
    pmSellState: state,
    buyMoney,
    expectedMoneyCny: expected,
    suggestedMoneyCny: expected,
    sellMoneySum,
    sellCount: sells.length,
    sells: sells.map(s => ({
      orderId: shortId(s.order_id),
      money: num(s.money),
      betMoney: num(s.bet_money),
      pnlUsdc: num(rawObj(s).pmRealizedPnlUsdc),
      createAtShanghai: shTime(s.create_at),
    })),
    reasons,
    autoFixable: reasons.includes("money_approx_2x_sell_pnl")
      || reasons.includes("buy_money_zero_but_sell_pnl_nonzero"),
  };
}

async function main() {
  const args = parseArgs(process.argv);
  if (args.help) {
    console.log(`Usage:
  node scripts/ops/incidents/scan-fix-pm-sell-pnl-double.mjs [--dry-run|--execute] [--user NAME] [--match SUBSTR]
`);
    process.exit(0);
  }

  initDatabaseUrl();
  const pool = getPgPool();

  if (!pool) {
    console.error("No DATABASE_URL / pool");
    process.exit(1);
  }

  let userIds = null;
  if (args.userName) {
    const profiles = await fetchProfiles();
    const want = args.userName.toLowerCase();
    userIds = profiles
      .filter(p => String(p.user_name ?? p.userName ?? "").toLowerCase() === want)
      .map(p => String(p.id ?? p.user_id ?? ""));
    if (!userIds.length) {
      console.error(`user not found: ${args.userName}`);
      process.exit(1);
    }
  }

  const params = [];
  const filters = [`LOWER(TRIM(provider)) = 'polymarket'`];
  if (userIds) {
    params.push(userIds);
    filters.push(`user_id = ANY($${params.length}::text[])`);
  }
  if (args.match) {
    params.push(`%${args.match}%`);
    filters.push(`match ILIKE $${params.length}`);
  }

  const sql = `
    SELECT order_id, user_id, player_id, provider, link, match, bet, item,
           money, bet_money, status, create_at, raw
    FROM ${financialOrdersRelation()}
    WHERE ${filters.join(" AND ")}
    ORDER BY create_at DESC
  `;
  const { rows } = await pool.query(sql, params);
  const fx = getExchange(Currency.USDT);

  const buys = [];
  const sellsByBuy = new Map();
  for (const r of rows) {
    const side = String(rawObj(r).pmSide ?? "").toLowerCase();
    if (side === "sell") {
      const buyId = String(rawObj(r).pmBuyOrderId ?? "").trim().toLowerCase();
      if (!buyId)
        continue;
      if (!sellsByBuy.has(buyId))
        sellsByBuy.set(buyId, []);
      sellsByBuy.get(buyId).push(r);
      continue;
    }
    buys.push(r);
  }

  const issues = [];
  for (const buy of buys) {
    const id = String(buy.order_id).trim().toLowerCase();
    const sells = sellsByBuy.get(id) || [];
    const issue = classifyIssue(buy, sells, fx);
    if (issue)
      issues.push(issue);
  }

  const byReason = {};
  for (const iss of issues) {
    for (const r of iss.reasons) {
      byReason[r] = (byReason[r] || 0) + 1;
    }
  }

  const toFix = issues.filter((iss) => {
    if (args.match)
      return iss.autoFixable || iss.reasons.includes("money_approx_2x_sell_pnl");
    // 全库 execute：只自动修明确的 2× / 漏记
    return iss.autoFixable;
  });

  console.log(JSON.stringify({
    mode: args.dryRun ? "dry-run" : "execute",
    fx,
    scannedOrders: rows.length,
    buys: buys.length,
    issueCount: issues.length,
    byReason,
    issues,
    autoFixPlan: toFix.map(i => ({
      orderId: i.orderId,
      match: i.match,
      from: i.buyMoney,
      to: i.suggestedMoneyCny,
      reasons: i.reasons,
    })),
  }, null, 2));

  if (args.dryRun || args.scanOnly) {
    console.log(args.dryRun ? "[dry-run] no writes" : "[scan-only] no writes");
    process.exit(0);
  }

  if (!toFix.length) {
    console.log(JSON.stringify({ applied: false, updated: 0, note: "nothing auto-fixable" }, null, 2));
    process.exit(0);
  }

  const client = await pool.connect();

  try {
    await client.query("BEGIN");
    let updated = 0;
    for (const item of toFix) {
      const { rows: found } = await client.query(
        `SELECT order_id, money, raw FROM ${financialOrdersRelation()} WHERE order_id = $1 FOR UPDATE`,
        [item.orderId],
      );
      const row = found[0];
      if (!row)
        continue;
      const raw = rawObj(row);
      const prev = num(row.money);
      raw.money = item.suggestedMoneyCny;
      raw.pmMoneyFixedFromDoubleSellPnl = {
        prev,
        next: item.suggestedMoneyCny,
        expectedFromSellPnl: item.expectedMoneyCny,
        reasons: item.reasons,
        fixedAt: Date.now(),
      };
      if (Math.abs(num(raw.pmRealizedPnlUsdc)) < 1e-9 && item.sells?.length) {
        const pnlSum = item.sells.reduce((s, x) => s + num(x.pnlUsdc), 0);
        if (Math.abs(pnlSum) > 1e-9)
          raw.pmRealizedPnlUsdc = Math.round(pnlSum * 10000) / 10000;
      }
      await client.query(
        `UPDATE ${financialOrdersRelation()} SET money = $2, raw = $3::jsonb WHERE order_id = $1`,
        [item.orderId, item.suggestedMoneyCny, JSON.stringify(raw)],
      );
      updated += 1;
    }
    await client.query("COMMIT");
    console.log(JSON.stringify({ applied: true, updated }, null, 2));
  }
  catch (err) {
    await client.query("ROLLBACK");
    throw err;
  }
  finally {
    client.release();
    await pool.end?.();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * River：只保留一个活跃 PredictFun 账号，token 写入主号 predictAccount（无私钥）。
 * Privy 由本机 Vite `VITE_PREDICT_FUN_PRIVY_PRIVATE_KEY` 注入（见 configure 配套步骤），不上 RDS。
 *
 * Usage (from server/backend):
 *   node scripts/ops/incidents/seed-river-pf-from-house-env.mjs
 *   node scripts/ops/incidents/seed-river-pf-from-house-env.mjs --apply
 */
import { config } from "dotenv";
import pg from "pg";

config({ path: ".env" });

const apply = process.argv.includes("--apply");
const url = process.env.DATABASE_URL_PUBLIC || process.env.DATABASE_URL || process.env.DATABASE_URL_INTERNAL;
if (!url) {
  console.error("缺少 DATABASE_URL");
  process.exit(1);
}

const predictAccount = String(process.env.PREDICT_FUN_PREDICT_ACCOUNT || "").trim();
const hasPrivy = Boolean(String(process.env.PREDICT_FUN_PRIVY_PRIVATE_KEY || "").trim());
if (!/^0x[0-9a-fA-F]{40}$/.test(predictAccount)) {
  console.error("PREDICT_FUN_PREDICT_ACCOUNT 无效或未配置");
  process.exit(1);
}
if (!hasPrivy)
  console.warn("警告：.env 无 PREDICT_FUN_PRIVY_PRIVATE_KEY；请同步到 client/web/.env.local 的 VITE_ 变量");

const persistToken = JSON.stringify({ predictAccount });
const pool = new pg.Pool({
  connectionString: url,
  ssl: /sslmode=require/i.test(url) ? { rejectUnauthorized: false } : undefined,
});

function mergeAccountDataToken(accountData, tokenJson, predictAccount) {
  const data
    = accountData && typeof accountData === "object" && !Array.isArray(accountData)
      ? { ...accountData }
      : {};
  data.token = tokenJson;
  data.currency = "USDT";
  data.venueMemberId = predictAccount;
  data.venueAccountName = predictAccount;
  delete data.balance;
  delete data.Balance;
  delete data.mode;
  delete data.house;
  return data;
}

async function main() {
  const users = await pool.query(
    `SELECT u.id, u.user_name FROM users u WHERE u.user_name ILIKE 'river' LIMIT 1`,
  );
  if (!users.rows.length)
    throw new Error("找不到用户 River");
  const userId = String(users.rows[0].id);
  const userName = String(users.rows[0].user_name);
  console.log(`user=${userName} id=${userId}`);
  console.log(`predictAccount=${predictAccount}`);
  console.log(`mode=${apply ? "APPLY" : "DRY-RUN"}`);

  const pl = await pool.query(
    `SELECT id, player_name, total_balance, account_data, provider, platform_name, deleted_at
     FROM players
     WHERE owner_user_id = $1::uuid
       AND (provider ILIKE '%predict%' OR platform_name ILIKE '%predict%')
     ORDER BY id ASC`,
    [userId],
  );
  const allPf = pl.rows.map((r) => ({
    id: Number(r.id),
    playerName: String(r.player_name || userName),
    totalBalance: Number(r.total_balance) || 0,
    accountData: r.account_data,
    deleted: r.deleted_at != null,
  }));
  const active = allPf.filter((r) => !r.deleted);
  if (!active.length && !allPf.length)
    throw new Error("River 尚无 PredictFun players 行；请先在 UI 新建 PredictFun 账号后再跑");

  // 保留：优先已有活跃行；多个则留 id 最大的一条
  let keep = active.sort((a, b) => b.id - a.id)[0] || null;
  if (!keep) {
    // 全部已删：复活 id 最大的一条
    keep = allPf.slice().sort((a, b) => b.id - a.id)[0];
    console.log(`will undelete player id=${keep.id}`);
  }
  const dropIds = active.filter((r) => r.id !== keep.id).map((r) => r.id);
  console.log(`keep PF accountId=${keep.id} total_balance=${keep.totalBalance}`);
  if (dropIds.length)
    console.log(`soft-delete extra PF ids=${dropIds.join(",")}`);

  const nextData = mergeAccountDataToken(keep.accountData, persistToken, predictAccount);
  const venueAccountKey = `predictfun:member:${predictAccount}`;

  const prof = await pool.query(`SELECT accounts FROM profiles WHERE id = $1`, [userId]);
  /** @type {any[]} */
  const prevAccounts = Array.isArray(prof.rows[0]?.accounts) ? [...prof.rows[0].accounts] : [];
  const nonPf = prevAccounts.filter(
    (a) => String(a?.provider ?? a?.Provider ?? "").trim() !== "PredictFun",
  );
  const pfRow = {
    accountId: keep.id,
    provider: "PredictFun",
    platformName: "PredictFun",
    playerName: predictAccount,
    token: persistToken,
    credit: 0,
    currency: "USDT",
    pause: false,
    venueMemberId: predictAccount,
    venueAccountName: predictAccount,
  };
  const nextAccounts = [...nonPf, pfRow];

  if (!apply) {
    console.log("dry-run ok；加 --apply 写入 players + profiles.accounts");
    return;
  }

  const now = Date.now();
  if (keep.deleted) {
    await pool.query(
      `UPDATE players
       SET deleted_at = NULL, delete_description = NULL, updated_at = $2
       WHERE id = $1 AND owner_user_id = $3::uuid`,
      [keep.id, now, userId],
    );
  }

  await pool.query(
    `UPDATE players
     SET provider = 'PredictFun',
         platform_name = 'PredictFun',
         player_name = $5,
         venue_member_id = $6,
         venue_account_key = $7,
         account_data = $3::jsonb,
         credit = 0,
         updated_at = $4
     WHERE id = $1 AND owner_user_id = $2::uuid`,
    [keep.id, userId, JSON.stringify(nextData), now, predictAccount, predictAccount, venueAccountKey],
  );

  if (dropIds.length) {
    await pool.query(
      `UPDATE players
       SET deleted_at = $2, delete_description = $3, updated_at = $2
       WHERE owner_user_id = $1::uuid AND id = ANY($4::bigint[]) AND deleted_at IS NULL`,
      [userId, now, "River 仅保留一个 PF 测试账号", dropIds],
    );
  }

  await pool.query(`UPDATE profiles SET accounts = $2::jsonb WHERE id = $1`, [
    userId,
    JSON.stringify(nextAccounts),
  ]);

  console.log(`applied: sole PF accountId=${keep.id}`);
  console.log("Privy：请确保 client/web/.env.local 有 VITE_PREDICT_FUN_PRIVY_PRIVATE_KEY + VITE_PREDICT_FUN_PREDICT_ACCOUNT（与 backend .env 主号一致），硬刷新后再刷余额");
}

main()
  .catch((err) => {
    console.error(err);
    process.exitCode = 1;
  })
  .finally(() => pool.end());

#!/usr/bin/env node
/**
 * 一次性：从 RDS 清掉 PredictFun 电竞赛事（platform_* + 合场 matchs/bets 中的 PF）。
 * 不删 orders / 账号。体育 sport_venue_* 的 PF 行一并清。
 *
 *   node scripts/ops/incidents/wipe-pf-esport-matches.mjs
 *   node scripts/ops/incidents/wipe-pf-esport-matches.mjs --apply
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { ensurePgPoolReady } from "@changmen/db";

loadChangmenEnv();

const APPLY = process.argv.includes("--apply");
const PF = ["PredictFun", "PF"];

function keysOf(row) {
  return Object.fromEntries(
    Object.entries(row).map(([k, v]) => [k, Number(v) || 0]),
  );
}

async function countPf(pool) {
  const [
    platforms,
    bets,
    timers,
    cmPf,
    cmPfOnlyActive,
    sportVenue,
    sportBets,
    sportCmPf,
  ] = await Promise.all([
    pool.query(
      `SELECT platform, count(*)::int AS n FROM platform_matches
       WHERE platform = ANY($1::text[]) GROUP BY 1`,
      [PF],
    ),
    pool.query(
      `SELECT platform, count(*)::int AS n FROM platform_bets
       WHERE platform = ANY($1::text[]) GROUP BY 1`,
      [PF],
    ),
    pool.query(
      `SELECT platform, count(*)::int AS n FROM live_timers
       WHERE platform = ANY($1::text[]) GROUP BY 1`,
      [PF],
    ),
    pool.query(
      `SELECT count(*)::int AS n FROM client_matches
       WHERE matchs ?| $1::text[]`,
      [PF],
    ),
    pool.query(
      `SELECT count(*)::int AS n FROM client_matches
       WHERE ended_at IS NULL
         AND matchs ?| $1::text[]
         AND (SELECT count(*) FROM jsonb_object_keys(COALESCE(matchs, '{}'::jsonb)) k
              WHERE k NOT IN ('PredictFun','PF')) = 0`,
      [PF],
    ),
    pool.query(
      `SELECT venue, count(*)::int AS n FROM sport_venue_matches
       WHERE venue = ANY($1::text[]) GROUP BY 1`,
      [PF],
    ),
    pool.query(
      `SELECT venue, count(*)::int AS n FROM sport_venue_bets
       WHERE venue = ANY($1::text[]) GROUP BY 1`,
      [PF],
    ),
    pool.query(
      `SELECT count(*)::int AS n FROM sport_client_matches
       WHERE matchs ?| $1::text[]`,
      [PF],
    ),
  ]);
  return {
    platform_matches: platforms.rows,
    platform_bets: bets.rows,
    live_timers: timers.rows,
    client_matches_with_pf: cmPf.rows[0]?.n || 0,
    client_matches_pf_only_active: cmPfOnlyActive.rows[0]?.n || 0,
    sport_venue_matches: sportVenue.rows,
    sport_venue_bets: sportBets.rows,
    sport_client_matches_with_pf: sportCmPf.rows[0]?.n || 0,
  };
}

function stripPfSql(table) {
  return `
    UPDATE ${table}
    SET
      matchs = (COALESCE(matchs, '{}'::jsonb) - 'PredictFun' - 'PF'),
      bets = (
        SELECT COALESCE(jsonb_agg(
          CASE
            WHEN jsonb_typeof(elem->'Sources') = 'object'
            THEN jsonb_set(elem, '{Sources}', (elem->'Sources') - 'PredictFun' - 'PF', true)
            ELSE elem
          END
        ), '[]'::jsonb)
        FROM jsonb_array_elements(
          CASE WHEN jsonb_typeof(COALESCE(bets, '[]'::jsonb)) = 'array'
               THEN bets ELSE '[]'::jsonb END
        ) elem
      ),
      reverse = CASE
        WHEN jsonb_typeof(reverse) = 'array' THEN (
          SELECT COALESCE(jsonb_agg(x), '[]'::jsonb)
          FROM jsonb_array_elements(reverse) x
          WHERE x #>> '{}' NOT IN ('PredictFun', 'PF')
        )
        WHEN jsonb_typeof(reverse) = 'object' THEN reverse - 'PredictFun' - 'PF'
        ELSE reverse
      END
    WHERE matchs ?| $1::text[]
  `;
}

const pool = await ensurePgPoolReady();
if (!pool) {
  console.error("无法连接 RDS");
  process.exit(1);
}

const before = await countPf(pool);
console.log(APPLY ? "APPLY" : "DRY-RUN", JSON.stringify(before, null, 2));

if (!APPLY) {
  console.log("未改库。确认后加 --apply");
  process.exit(0);
}

const client = await pool.connect();
try {
  await client.query("BEGIN");

  await client.query(
    `WITH moved AS (
       DELETE FROM platform_matches
       WHERE platform = ANY($1::text[])
       RETURNING *
     )
     INSERT INTO platform_matches_history (
       platform, source_match_id, source_game_id, start_time, home_id, home,
       away_id, away, bo, is_live, rot_num, teams, synced_at, match_id
     )
     SELECT platform, source_match_id, source_game_id, start_time, home_id, home,
            away_id, away, bo, is_live, rot_num, teams, synced_at, match_id
     FROM moved`,
    [PF],
  );
  const betsDel = await client.query(
    `DELETE FROM platform_bets WHERE platform = ANY($1::text[])`,
    [PF],
  );
  const timersDel = await client.query(
    `DELETE FROM live_timers WHERE platform = ANY($1::text[])`,
    [PF],
  );

  const cmStrip = await client.query(stripPfSql("client_matches"), [PF]);
  const nowMs = Date.now();
  const cmEnded = await client.query(
    `UPDATE client_matches
     SET ended_at = COALESCE(ended_at, $1)
     WHERE ended_at IS NULL
       AND (matchs IS NULL OR matchs = '{}'::jsonb)`,
    [nowMs],
  );

  await client.query(
    `DELETE FROM sport_venue_bets WHERE venue = ANY($1::text[])`,
    [PF],
  );
  await client.query(
    `DELETE FROM sport_venue_matches WHERE venue = ANY($1::text[])`,
    [PF],
  );

  const sportStrip = await client.query(stripPfSql("sport_client_matches"), [PF]);
  const sportDelEmpty = await client.query(
    `DELETE FROM sport_client_matches
     WHERE matchs IS NULL OR matchs = '{}'::jsonb`,
  );

  await client.query("COMMIT");
  console.log("deleted", {
    platform_bets: betsDel.rowCount,
    live_timers: timersDel.rowCount,
    client_matches_stripped: cmStrip.rowCount,
    client_matches_ended_empty: cmEnded.rowCount,
    sport_client_matches_stripped: sportStrip.rowCount,
    sport_client_matches_deleted_empty: sportDelEmpty.rowCount,
  });
}
catch (err) {
  await client.query("ROLLBACK");
  throw err;
}
finally {
  client.release();
}

const after = await countPf(pool);
console.log("AFTER", JSON.stringify(after, null, 2));
process.exit(0);

import { financialOrdersRelation } from "@changmen/db";
/**
 * 回填：订单栏可见的 PM 买单 Money → 与 bet_money 含费口径对齐
 *
 * 输：money = -bet_money
 * 赢：money = shares*FX - bet_money；reward = shares*FX
 *
 * 排除：partial/closed 或已有卖出归因
 *
 *   node scripts/ops/migrations/align-pm-buy-money-to-bet.mjs --dry-run
 *   node scripts/ops/migrations/align-pm-buy-money-to-bet.mjs --execute
 */
import { loadChangmenEnv } from "@changmen/storage/load_env.js";
import { Currency, getExchange } from "@changmen/shared/currency";

loadChangmenEnv();
const { initDatabaseUrl, getPgPool } = await import("@changmen/db");

const dryRun = !process.argv.includes("--execute");
initDatabaseUrl();
const pool = getPgPool();

const FX = getExchange(Currency.USDT);

const { rows } = await pool.query(`
  SELECT
    o.id,
    o.order_id,
    o.status,
    o.bet_money::float8 AS bet,
    o.money::float8 AS money,
    o.raw,
    NULLIF(COALESCE(raw->>'pmShares', raw->>'PmShares'),'')::float8 AS shares,
    COALESCE(p.user_name, o.user_id::text) AS user_name,
    to_char(to_timestamp(o.create_at/1000.0) AT TIME ZONE 'Asia/Shanghai', 'YYYY-MM-DD') AS day_cst
  FROM ${financialOrdersRelation("o")}
  LEFT JOIN profiles p ON p.id = o.user_id
  WHERE o.provider = 'Polymarket'
    AND COALESCE(raw->>'pmSide', raw->>'PmSide', 'buy') ILIKE 'buy'
    AND LOWER(o.status) IN ('win', 'lose', 'lost')
    AND COALESCE(o.bet_money, 0) > 0
    AND NULLIF(COALESCE(raw->>'pmShares', raw->>'PmShares'),'')::float8 > 0.0001
    AND COALESCE(raw->>'pmSellState', raw->>'PmSellState', '') NOT IN ('partial', 'closed')
    AND COALESCE(NULLIF(raw->>'pmAttributedSellShares', '')::float8, 0) <= 0.0001
`);

const plan = [];
for (const r of rows) {
  const st = String(r.status || "").toLowerCase();
  const bet = Number(r.bet) || 0;
  const money = Number(r.money) || 0;
  const shares = Number(r.shares) || 0;
  if (!(bet > 0) || !(shares > 0))
    continue;

  const fair = st === "win" ? shares * FX - bet : -bet;
  const visible = st === "win"
    ? Math.round(money) !== Math.round(shares * FX - bet)
    : Math.round(bet) !== Math.round(Math.abs(money));
  if (!visible)
    continue;

  const nextMoney = Math.round(fair * 10000) / 10000;
  const nextReward = st === "win" ? Math.round(shares * FX * 10000) / 10000 : 0;
  const delta = money - nextMoney;
  if (Math.abs(delta) < 0.005)
    continue;

  plan.push({
    id: r.id,
    order_id: r.order_id,
    user_name: r.user_name,
    day_cst: r.day_cst,
    status: st,
    bet,
    shares,
    oldMoney: money,
    nextMoney,
    nextReward,
    delta,
    raw: r.raw,
  });
}

const sumDelta = plan.reduce((s, p) => s + p.delta, 0);
const byUser = {};
const byDay = {};
for (const p of plan) {
  byUser[p.user_name] ??= { n: 0, reduce: 0 };
  byUser[p.user_name].n += 1;
  byUser[p.user_name].reduce += p.delta;
  byDay[p.day_cst] ??= { n: 0, reduce: 0 };
  byDay[p.day_cst].n += 1;
  byDay[p.day_cst].reduce += p.delta;
}

console.log(JSON.stringify({
  mode: dryRun ? "dry-run" : "execute",
  fx: FX,
  count: plan.length,
  totalReduceCny: Math.round(sumDelta * 100) / 100,
  byDay: Object.fromEntries(
    Object.entries(byDay)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([k, v]) => [k, { n: v.n, reduce: Math.round(v.reduce * 100) / 100 }]),
  ),
  byUser: Object.fromEntries(
    Object.entries(byUser)
      .map(([k, v]) => [k, { n: v.n, reduce: Math.round(v.reduce * 100) / 100 }])
      .sort((a, b) => b[1].reduce - a[1].reduce),
  ),
  sample: plan.slice(0, 3).map(p => ({
    user: p.user_name,
    st: p.status,
    bet: Math.round(p.bet),
    oldMoney: Math.round(p.oldMoney),
    nextMoney: Math.round(p.nextMoney),
  })),
}, null, 2));

if (dryRun) {
  console.log("[dry-run] no writes");
  await pool.end();
  process.exit(0);
}

const client = await pool.connect();

let updated = 0;
const BATCH = 50;
try {
  // 按 id 排序，缩短单事务，降低与线上写入死锁概率
  plan.sort((a, b) => Number(a.id) - Number(b.id));
  for (let i = 0; i < plan.length; i += BATCH) {
    const chunk = plan.slice(i, i + BATCH);
    for (let attempt = 1; attempt <= 3; attempt++) {
      try {
        await client.query("BEGIN");
        for (const item of chunk) {
          const raw = item.raw && typeof item.raw === "object" && !Array.isArray(item.raw)
            ? { ...item.raw }
            : {};
          raw.money = item.nextMoney;
          if (item.status === "win")
            raw.reward = item.nextReward;
          raw.pmMoneyAlignedToBetAt = Date.now();
          raw.pmMoneyAlignedFrom = item.oldMoney;

          const oldRealized = Number(raw.pmRealizedPnlUsdc ?? raw.PmRealizedPnlUsdc);
          if (Number.isFinite(oldRealized) && Math.abs(oldRealized) > 1e-9)
            raw.pmRealizedPnlUsdc = Math.round((item.nextMoney / FX) * 10000) / 10000;

          const res = await client.query(
            `UPDATE ${financialOrdersRelation()}
             SET money = $2,
                 raw = $3::jsonb
             WHERE id = $1
               AND provider = 'Polymarket'
               AND COALESCE(raw->>'pmSide', raw->>'PmSide', 'buy') ILIKE 'buy'
               AND ABS(COALESCE(money, 0) - $4) < 0.01`,
            [item.id, item.nextMoney, JSON.stringify(raw), item.oldMoney],
          );
          if (res.rowCount === 1)
            updated += 1;
        }
        await client.query("COMMIT");
        break;
      }
      catch (err) {
        await client.query("ROLLBACK").catch(() => {});
        if (err && err.code === "40P01" && attempt < 3) {
          console.warn(`deadlock batch@${i} attempt ${attempt}, retry…`);
          await new Promise(r => setTimeout(r, 200 * attempt));
          continue;
        }
        throw err;
      }
    }
    process.stdout.write(`\rupdated ${Math.min(i + BATCH, plan.length)}/${plan.length}`);
  }
  console.log("\n" + JSON.stringify({ applied: true, updated, planned: plan.length }, null, 2));
}
catch (err) {
  await client.query("ROLLBACK").catch(() => {});
  throw err;
}
finally {
  client.release();
  await pool.end();
}

