    expect(client.query.mock.calls[0][0]).toBe("BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY");
    expect(client.query.mock.calls.at(-1)[0]).toBe("COMMIT");
    for (const [sql] of client.query.mock.calls)
      expect(sql).toMatch(/^(SELECT |BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY$|SET LOCAL search_path|COMMIT$)/);
  });

  it("rejects missing fields without committing, repairing, or adopting a migration ledger", async () => {
    const client = catalogClient({ missing: true });
    await expect(verifyRdsSchema(client)).rejects.toThrow("columns.platform_bets.line_id: missing");
    expect(client.query.mock.calls.at(-1)[0]).toBe("ROLLBACK");
    expect(client.query.mock.calls.some(([sql]) => sql === "COMMIT")).toBe(false);
  });

  it("still rejects a changed historical checksum when a ledger already exists", async () => {
    const client = catalogClient({ badChecksum: true });
    await expect(verifyRdsSchema(client)).rejects.toThrow("已执行的迁移内容发生变化");
    expect(client.query.mock.calls.at(-1)[0]).toBe("ROLLBACK");
  });
});

// Explicit, one-off maintenance. Never imported by application startup/release.
import assert from 'node:assert/strict';
import { readRdsMigrationSql } from './assets.mjs';
import { migrationBody } from './rds-migrations.mjs';
import { migrationChecksum, readRdsSchema, readSchemaBaseline, schemaDifferences } from './rds-schema-check.mjs';

export const RECONCILE_MIGRATION = '20261015_reconcile_archive_schema.sql';
export const RECONCILE_TABLES = ['client_matches_history', 'platform_matches_history', 'team_venue_maps'];

// Migration source precondition, NOT an alternative accepted by the checker.
// Only the reviewed source layout or the single final standard may be maintained.
export function reconciliationSourceSchema(target) {
  const source = structuredClone(target);
  const alter = (key, fields) => Object.assign(source.columns[key], fields);
  for (const table of RECONCILE_TABLES.slice(0, 2)) alter(`${table}.archived_at`, {
    type: 'bigint', default: '((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint',
  });
  alter('client_matches_history.id', { type: 'integer', notNull: false });
  for (const field of ['bo', 'round']) alter(`client_matches_history.${field}`, { type: 'smallint' });
  for (const field of ['title', 'built_at']) alter(`client_matches_history.${field}`, { notNull: false });
  alter('client_matches_history.reverse', { notNull: false, default: null });
  alter('platform_matches_history.match_id', { type: 'integer' });
  for (const field of ['home', 'away', 'synced_at', 'teams']) alter(`platform_matches_history.${field}`, { notNull: false });
  for (const [kind, from, to] of [
    ['constraints', 'team_venue_maps.team_venue_maps_gb_team_id_fkey', 'team_venue_maps.team_platform_maps_canonical_id_fkey'],
    ['constraints', 'team_venue_maps.team_venue_maps_pkey', 'team_venue_maps.team_platform_maps_pkey'],
    ['indexes', 'team_venue_maps.team_venue_maps_pkey', 'team_venue_maps.team_platform_maps_pkey'],
    ['sequences', 'team_venue_maps_id_seq', 'team_platform_maps_id_seq'],
  ]) {
    source[kind][to] = source[kind][from]; delete source[kind][from];
    if (kind === 'indexes') source[kind][to].definition = source[kind][to].definition.replace(
      'CREATE UNIQUE INDEX team_venue_maps_pkey ON', 'CREATE UNIQUE INDEX team_platform_maps_pkey ON');
  }
  return source;
}

/** Full-row multiset fingerprints, retaining duplicates and numeric precision. */
export async function reconciliationSnapshot(client, schema) {
  const tables = {};
  for (const table of RECONCILE_TABLES) {
    let row = 'to_jsonb(t)';
    if (table.endsWith('_history')) {
      const type = schema.columns[`${table}.archived_at`]?.type;
      assert(['bigint', 'timestamp with time zone'].includes(type), 'Unexpected archive time type');
      // Normalize numeric scale, never round: exact milliseconds match the old
      // bigint representation, while even a one-microsecond change stays visible.
      const time = type === 'bigint' ? 't.archived_at' : 'trim_scale(EXTRACT(epoch FROM t.archived_at)*1000)';
      row = `(to_jsonb(t)-'archived_at') || jsonb_build_object('archived_at_ms',${time})`;
    }
    tables[table] = (await client.query(`SELECT count(*)::text AS rows,
      md5(coalesce(string_agg(h,'' ORDER BY h COLLATE "C"),'')) AS digest
      FROM (SELECT md5((${row})::text) AS h FROM public.${table} t) s`)).rows[0];
  }
  const seq = (await client.query("SELECT pg_get_serial_sequence('public.team_venue_maps','id') AS name")).rows[0].name;
  assert(['public.team_platform_maps_id_seq', 'public.team_venue_maps_id_seq'].includes(seq), 'Unexpected identity sequence');
  const sequence = (await client.query(`SELECT last_value::text,is_called FROM ${seq}`)).rows[0];
  const sequenceOid = (await client.query('SELECT $1::regclass::oid::text AS oid', [seq])).rows[0].oid;
  return { tables, sequence: { ...sequence, oid: sequenceOid } };
}

/** Backup callback must durably store affected rows/schema before any ALTER. */
export async function reconcileRdsSchema(client, { apply = false, backup, sql = readRdsMigrationSql(RECONCILE_MIGRATION) } = {}) {
  const baseline = readSchemaBaseline(), checksum = migrationChecksum(sql);
  assert.equal(checksum, baseline.migrations[RECONCILE_MIGRATION], 'Unreviewed reconciliation SQL');
  if (apply && typeof backup !== 'function') throw new Error('Applying reconciliation requires a durable backup callback');
  await client.query('BEGIN');
  try {
    await client.query("SET LOCAL lock_timeout='2s'; SET LOCAL statement_timeout='30s'; SET LOCAL idle_in_transaction_session_timeout='60s'; SET LOCAL search_path=public,pg_catalog; SET LOCAL timezone='UTC'");
    await client.query("SELECT pg_advisory_xact_lock(hashtextextended('changmen:rds-schema',0))");
    await client.query(`LOCK TABLE ${RECONCILE_TABLES.map(t => 'public.' + t).join(',')} IN ACCESS EXCLUSIVE MODE`);
    const actual = await readRdsSchema(client);
    const canonical = schemaDifferences(actual, baseline.schema).length === 0;
    const errors = schemaDifferences(actual, canonical ? baseline.schema : reconciliationSourceSchema(baseline.schema));
    if (errors.length) throw new Error(`Unreviewed migration source; no changes:\n${errors.join('\n')}`);
    const before = await reconciliationSnapshot(client, actual);
    // Inspect an existing ledger before DDL, without replaying/adopting old entries.
    const ledger = (await client.query("SELECT to_regclass('public.changmen_schema_migrations') AS name")).rows[0].name;
    if (ledger) {
      for (const record of (await client.query('SELECT name,checksum FROM public.changmen_schema_migrations')).rows) {
        if (baseline.migrations[record.name] && baseline.migrations[record.name] !== record.checksum)
          throw new Error(`Migration checksum changed: ${record.name}`);
      }
    }
    const backupReceipt = apply ? await backup(client, { schema: actual, before, migration: RECONCILE_MIGRATION, checksum }) : null;
    if (apply && !backupReceipt) throw new Error('Missing durable backup receipt');
    // Already canonical: do not rewrite tables or replay any migration.
    if (!canonical) await client.query(migrationBody(sql));
    const afterSchema = await readRdsSchema(client);
    const remaining = schemaDifferences(afterSchema, baseline.schema);
    if (remaining.length) throw new Error(`Canonical schema verification failed:\n${remaining.join('\n')}`);
    const after = await reconciliationSnapshot(client, afterSchema);
    assert.deepEqual(after, before, 'Reconciliation changed business data or sequence state');
    if (!canonical) {
      await client.query(`CREATE TABLE IF NOT EXISTS public.changmen_schema_migrations (
        name text PRIMARY KEY,checksum text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now())`);
      await client.query('INSERT INTO public.changmen_schema_migrations(name,checksum) VALUES($1,$2) ON CONFLICT(name) DO NOTHING', [RECONCILE_MIGRATION, checksum]);
    }
    await client.query(apply ? 'COMMIT' : 'ROLLBACK');
    return { applied: apply && !canonical, dryRun: !apply, alreadyCanonical: canonical, migration: RECONCILE_MIGRATION,
      checksum, before, after, dataUnchanged: true, schemaDifferences: 0, backup: backupReceipt };
  } catch (error) {
    await client.query('ROLLBACK').catch(() => {});
    throw error;
  }
}

#!/usr/bin/env node
/**
 * 阶段一 036 team_provider_ids 只读巡检（不写库）。
 *
 * 注意：036 文件自带 BEGIN/COMMIT，切勿在本脚本里再套外层事务
 *（嵌套 BEGIN 会被忽略，文件内 COMMIT 会提交整个外层事务 → 误落库）。
 *
 * 运行：node server/db/maintenance/verify-team-provider-ids.mjs
 */
import { buildPgClientConfig, initDatabaseUrl } from "@changmen/db";
import pg from "@changmen/db/pg.js";

await initDatabaseUrl();
const url = process.env.DATABASE_URL;
if (!url) {
  console.error("缺少 DATABASE_URL");
  process.exit(1);
}

const client = new pg.Client(buildPgClientConfig(url, 30000));
client.on("error", (err) => console.warn("[verify] client error:", err.message));
await client.connect();

let exitCode = 0;

try {
  const { rows: exists } = await client.query(
    `SELECT EXISTS (SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'team_provider_ids') AS ok`,
  );
  if (!exists[0].ok) {
    console.error("[verify] ✘ team_provider_ids 表不存在（尚未执行 036）");
    process.exit(1);
  }

  const { rows: stats } = await client.query(
    `SELECT COUNT(*)::int AS n,
            COUNT(DISTINCT provider)::int AS providers
     FROM team_provider_ids`,
  );
  console.log(`[verify] team_provider_ids: ${stats[0].n} 行 / ${stats[0].providers} 个 provider`);

  const { rows: mismatch } = await client.query(
    `SELECT COUNT(*)::int AS n
     FROM canonical_teams ct
     LEFT JOIN team_provider_ids tpi
       ON tpi.team_id = ct.id AND tpi.provider = 'pandascore'
     WHERE ct.pandascore_id IS NOT NULL AND tpi.provider_id IS NULL`,
  );
  console.log(`[verify] pandascore 回填缺失: ${mismatch[0].n} 行`);
  if (mismatch[0].n > 0) {
    console.error("[verify] ✘ 存在未回填的 pandascore_id");
    exitCode = 1;
  }

  const { rows: extra } = await client.query(
    `SELECT COUNT(*)::int AS n
     FROM team_provider_ids tpi
     LEFT JOIN canonical_teams ct ON ct.id = tpi.team_id
     WHERE ct.id IS NULL`,
  );
  console.log(`[verify] 孤儿 team_id: ${extra[0].n} 行`);
  if (extra[0].n > 0) {
    console.error("[verify] ✘ 存在指向不存在 canonical_teams 的 team_id");
    exitCode = 1;
  }

  const { rows: cols } = await client.query(
    `SELECT column_name, data_type
     FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'team_provider_ids'
     ORDER BY ordinal_position`,
  );
  console.log("[verify] 表结构:", cols.map(c => `${c.column_name}:${c.data_type}`).join(", "));
}
catch (err) {
  console.error("[verify] ✘ 失败:", err.message);
  exitCode = 1;
}
finally {
  await client.end();
}

if (exitCode === 0)
  console.log("[verify] ✅ 036 巡检通过");
else
  console.error("[verify] ❌ 存在异常");
process.exit(exitCode);

/**
 * [changmen 扩展] SaveOrder 入库：用 user_logs 判定 changmen 主动下注（手动/自动），非 A8 被动 sync。
 *
 * 优先级：
 *   1. 下注日志 orderId 精确匹配 +「下注 => true」
 *   2. 下注日志 平台 + 时间窗 + 金额/赔率弱匹配
 *   3. fallback：预检「请求盘口数据 => true」+ 平台 + match/金额/赔率对齐
 */

export const BET_LOG_BEFORE_MS = 5 * 60 * 1000;
export const BET_LOG_AFTER_MS = 60 * 1000;

/** 客户端列表筛选（已取消，查询返回全量；保留常量供运维脚本引用） */
export const CHANGMEN_ORDER_LIST_SQL = "changmen_bet = true";

export function orderChangmenBetSqlAnd(baseWhere) {
  const w = String(baseWhere || "").trim();
  if (!w)
    return CHANGMEN_ORDER_LIST_SQL;
  return `${w} AND ${CHANGMEN_ORDER_LIST_SQL}`;
}

export function parseBetLogData(raw) {
  if (raw == null || raw === "")
    return null;
  if (typeof raw === "object")
    return raw;
  try {
    return JSON.parse(String(raw));
  }
  catch {
    return null;
  }
}

export function isSuccessBetLogTitle(title) {
  const t = String(title || "");
  return t.includes("下注 =>") && /下注\s*=>\s*true/i.test(t);
}

/** 预检成功（有盘口 data）；仅作下注日志缺失时的 fallback */
export function isSuccessCheckLogTitle(title) {
  const t = String(title || "");
  return t.includes("请求盘口数据") && /请求盘口数据\s*=>\s*true/i.test(t);
}

export function extractBetLogProvider(title, parsed) {
  const bracket = String(title || "").match(/^\[([^\]]+)\]/);
  if (bracket?.[1])
    return String(bracket[1]).trim();
  if (parsed?.result?.provider)
    return String(parsed.result.provider).trim();
  if (parsed?.options?.type)
    return String(parsed.options.type).trim();
  return "";
}

/** 下注结果里的场馆 orderId（与 user_log_lookup.extractLogOrderId 对齐） */
export function extractBetLogOrderId(parsed) {
  const oid = parsed?.result?.orderId ?? parsed?.result?.order_id;
  if (oid == null || oid === "")
    return "";
  return String(oid).trim();
}

function normProvider(p) {
  return String(p || "").trim().toUpperCase();
}

function normMoney(n) {
  const v = Number(n);
  return Number.isFinite(v) ? Math.round(v) : null;
}

function normOdds(n) {
  const v = Number(n);
  return Number.isFinite(v) ? Math.round(v * 1000) / 1000 : null;
}

function orderTimeWindow(order, opts) {
  const createAt = Number(order?.create_at ?? order?.createAt) || 0;
  const provider = normProvider(order?.provider ?? order?.Type);
  if (!createAt || !provider)
    return null;
  const beforeMs = Number(opts.beforeMs) || BET_LOG_BEFORE_MS;
  const afterMs = Number(opts.afterMs) || BET_LOG_AFTER_MS;
  return {
    createAt,
    provider,
    from: createAt - beforeMs,
    to: createAt + afterMs,
  };
}

function logInWindow(row, from, to) {
  const logAt = Number(row.create_at ?? row.createAt) || 0;
  return logAt > 0 && logAt >= from && logAt <= to;
}

/** 日志 options 与订单字段弱匹配（降误关联） */
export function betLogMatchesOrder(parsed, order) {
  if (!parsed || !order)
    return true;
  const opts = parsed.options || parsed.result?.request?.options;
  if (!opts || typeof opts !== "object")
    return true;

  const logMoney = normMoney(opts.betMoney ?? opts.bet_money);
  const orderMoney = normMoney(order.bet_money ?? order.betMoney);
  if (logMoney != null && orderMoney != null && logMoney !== orderMoney)
    return false;

  const logOdds = normOdds(opts.odds);
  const orderOdds = normOdds(order.odds);
  if (logOdds != null && orderOdds != null && logOdds !== orderOdds)
    return false;

  return true;
}

/** 预检 options 与订单对齐（比下注 fallback 更严，避免「只点预检」误判） */
export function checkLogMatchesOrder(parsed, order) {
  if (!parsed || !order)
    return false;
  const opts = parsed.options;
  if (!opts || typeof opts !== "object")
    return false;

  const orderProvider = normProvider(order?.provider ?? order?.Type);
  if (opts.type && normProvider(opts.type) !== orderProvider)
    return false;

  const logMatch = String(opts.match || "").trim();
  const orderMatch = String(order.match ?? order.Match ?? "").trim();
  if (logMatch && orderMatch && logMatch !== orderMatch)
    return false;

  return betLogMatchesOrder(parsed, order);
}

function matchBetLogByOrderId(order, logs, win) {
  const orderId = String(order?.order_id ?? order?.orderId ?? "").trim();
  if (!orderId)
    return false;

  for (const row of logs || []) {
    if (!logInWindow(row, win.from, win.to))
      continue;
    if (!isSuccessBetLogTitle(row.title))
      continue;
    const parsed = parseBetLogData(row.data);
    if (extractBetLogOrderId(parsed) !== orderId)
      continue;
    const logProvider = normProvider(extractBetLogProvider(row.title, parsed));
    if (logProvider !== win.provider)
      continue;
    return true;
  }
  return false;
}

function matchBetLogByProvider(order, logs, win) {
  for (const row of logs || []) {
    if (!logInWindow(row, win.from, win.to))
      continue;
    if (!isSuccessBetLogTitle(row.title))
      continue;
    const parsed = parseBetLogData(row.data);
    const logProvider = normProvider(extractBetLogProvider(row.title, parsed));
    if (logProvider !== win.provider)
      continue;
    if (!betLogMatchesOrder(parsed, order))
      continue;
    return true;
  }
  return false;
}

function matchCheckLogFallback(order, logs, win) {
  for (const row of logs || []) {
    if (!logInWindow(row, win.from, win.to))
      continue;
    if (!isSuccessCheckLogTitle(row.title))
      continue;
    const parsed = parseBetLogData(row.data);
    const logProvider = normProvider(extractBetLogProvider(row.title, parsed));
    if (logProvider !== win.provider)
      continue;
    if (!checkLogMatchesOrder(parsed, order))
      continue;
    return true;
  }
  return false;
}

/**
 * 单笔订单是否能在日志窗内找到 changmen 主动下注痕迹。
 * @param {object} order — order_id, provider, create_at, match, bet_money, odds
 * @param {object[]} logs — user_logs 行（title, data, create_at）
 */
export function matchChangmenBetFromLogs(order, logs, opts = {}) {
  const win = orderTimeWindow(order, opts);
  if (!win)
    return false;

  if (matchBetLogByOrderId(order, logs, win))
    return true;
  if (matchBetLogByProvider(order, logs, win))
    return true;
  if (matchCheckLogFallback(order, logs, win))
    return true;
  return false;
}

/** 一批订单共用一次日志查询时的窗口 */
export function betLogWindowForOrders(orders, opts = {}) {
  const beforeMs = Number(opts.beforeMs) || BET_LOG_BEFORE_MS;
  const afterMs = Number(opts.afterMs) || BET_LOG_AFTER_MS;
  const times = (orders || [])
    .map(o => Number(o.create_at ?? o.createAt) || 0)
    .filter(t => t > 0);
  if (!times.length)
    return null;
  const min = Math.min(...times);
  const max = Math.max(...times);
  return { fromMs: min - beforeMs, toMs: max + afterMs };
}

import assert from "node:assert/strict";
import { describe, it } from "vitest";
import {
  BET_LOG_AFTER_MS,
  BET_LOG_BEFORE_MS,
  isSuccessBetLogTitle,
  isSuccessCheckLogTitle,
  matchChangmenBetFromLogs,
} from "./order_changmen_bet.js";

describe("order_changmen_bet", () => {
  const createAt = 1_781_890_577_200;
  const matchTitle = "Vitality vs Falcons";

  it("isSuccessBetLogTitle detects changmen bet success", () => {
    assert.equal(isSuccessBetLogTitle("[OB](星空,4) 下注 => true / 耗时:114ms"), true);
    assert.equal(isSuccessBetLogTitle("[RAY] 下注 => false / 耗时:345ms"), false);
  });

  it("isSuccessCheckLogTitle detects pre-check success", () => {
    assert.equal(
      isSuccessCheckLogTitle("[OB](星空,4) 请求盘口数据 => true / 耗时12ms / 2.1:2.1"),
      true,
    );
    assert.equal(
      isSuccessCheckLogTitle("[OB](星空,4) 请求盘口数据 => false / 耗时12ms"),
      false,
    );
  });

  it("matches provider and time window", () => {
    const logs = [
      {
        title: "[OB](星空,4) 下注 => true / 耗时:114ms",
        data: JSON.stringify({
          result: { provider: "OB", success: true },
          options: { betMoney: 60, odds: 2.652 },
        }),
        create_at: createAt + 72,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs(
        { provider: "OB", create_at: createAt, bet_money: 60, odds: 2.652 },
        logs,
      ),
      true,
    );
    assert.equal(
      matchChangmenBetFromLogs({ provider: "RAY", create_at: createAt }, logs),
      false,
    );
  });

  it("matches bet log by orderId even when money differs", () => {
    const logs = [
      {
        title: "[PB](平,1) 下注 => true",
        data: JSON.stringify({
          result: { provider: "PB", success: true, orderId: "pb-order-99" },
        }),
        create_at: createAt,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs(
        {
          order_id: "pb-order-99",
          provider: "PB",
          create_at: createAt,
          bet_money: 60,
          odds: 1.9,
        },
        logs,
      ),
      true,
    );
  });

  it("rejects bet money mismatch when matching by provider", () => {
    const logs = [
      {
        title: "[OB](星空,4) 下注 => true",
        data: JSON.stringify({ options: { betMoney: 100, odds: 2.652 } }),
        create_at: createAt,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs(
        { provider: "OB", create_at: createAt, bet_money: 60, odds: 2.652 },
        logs,
      ),
      false,
    );
  });

  it("rejected venue order still matches prior bet success log", () => {
    const logs = [
      {
        title: "[PB](平,1) 下注 => true / 耗时:200ms",
        data: JSON.stringify({
          result: { provider: "PB", success: true, orderId: "pb-reject-1" },
        }),
        create_at: createAt - 30_000,
      },
      {
        title: "[PB] - pb-reject-1 拒单检测 => REJECTED",
        data: "[]",
        create_at: createAt + 5_000,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs(
        {
          order_id: "pb-reject-1",
          provider: "PB",
          create_at: createAt,
          status: "Reject",
        },
        logs,
      ),
      true,
    );
  });

  it("falls back to successful pre-check when bet log missing", () => {
    const logs = [
      {
        title: "[OB](星空,4) 请求盘口数据 => true / 耗时10ms / 2.6:2.6",
        data: JSON.stringify({
          options: {
            type: "OB",
            match: matchTitle,
            betMoney: 60,
            odds: 2.652,
          },
        }),
        create_at: createAt - 2000,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs(
        {
          provider: "OB",
          create_at: createAt,
          match: matchTitle,
          bet_money: 60,
          odds: 2.652,
        },
        logs,
      ),
      true,
    );
  });

  it("does not fallback to pre-check with wrong match title", () => {
    const logs = [
      {
        title: "[OB](星空,4) 请求盘口数据 => true",
        data: JSON.stringify({
          options: {
            type: "OB",
            match: "Other Match",
            betMoney: 60,
            odds: 2.652,
          },
        }),
        create_at: createAt,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs(
        {
          provider: "OB",
          create_at: createAt,
          match: matchTitle,
          bet_money: 60,
          odds: 2.652,
        },
        logs,
      ),
      false,
    );
  });

  it("respects time window constants", () => {
    const logs = [
      {
        title: "[OB] 下注 => true",
        data: "{}",
        create_at: createAt - BET_LOG_BEFORE_MS - 1,
      },
    ];
    assert.equal(
      matchChangmenBetFromLogs({ provider: "OB", create_at: createAt }, logs),
      false,
    );
    logs[0].create_at = createAt + BET_LOG_AFTER_MS + 1;
    assert.equal(
      matchChangmenBetFromLogs({ provider: "OB", create_at: createAt }, logs),
      false,
    );
  });
});

/** 套利 LinkID 下限（与 SaveOrderBind Date.now() 对齐） */
export const ARB_LINK_MIN = 1_000_000_000_000;

/** 与 client-core format.VALUE_BET_LINK_BASE 对齐：正 EV 编码基线 */
export const VALUE_BET_LINK_BASE = 7_000_000_000_000_000;

/**
 * 侧栏/改绑排序键：正 EV 还原真实时间戳，其余取绝对值。
 * 与 packages/client-core orderLinkSortKey 一致。
 */
export function orderLinkSortKey(link) {
  const n = Math.abs(Number(link)) || 0;
  if (n >= VALUE_BET_LINK_BASE)
    return n - VALUE_BET_LINK_BASE;
  return n;
}

/** PostgreSQL：把 Link 还原成开弓毫秒（正 EV 去掉 7e15 基线） */
export function sqlLinkHomeTsExpr(linkExpr = "link") {
  return `(CASE WHEN ABS(${linkExpr}) >= ${VALUE_BET_LINK_BASE} THEN ABS(${linkExpr}) - ${VALUE_BET_LINK_BASE} ELSE ABS(${linkExpr}) END)`;
}

/**
 * 按日/按月列表归属 SQL：[start, end) 毫秒。
 * 时间戳 Link（套利 / 9999 / 正 EV）跟开弓时间；否则回退 create_at。
 * 这样开弓日没有成交、次日才补单时，开弓日仍能捞到种子。
 */
export function sqlOrderBelongsToRange(startParam, endParam, opts = {}) {
  const alias = opts.alias ? `${String(opts.alias).replace(/\.$/, "")}.` : "";
  const link = `${alias}link`;
  const createAt = `${alias}create_at`;
  const home = sqlLinkHomeTsExpr(link);
  const s = `$${Number(startParam)}`;
  const e = `$${Number(endParam)}`;
  return `((ABS(${link}) >= ${ARB_LINK_MIN} AND ${home} >= ${s} AND ${home} < ${e})`
    + ` OR ((${link} IS NULL OR ABS(${link}) < ${ARB_LINK_MIN}) AND ${createAt} >= ${s} AND ${createAt} < ${e}))`;
}

/** 与 sqlOrderBelongsToRange 同一套规则（单测 / 文档） */
export function orderBelongsToMsRange(link, createAt, start, end) {
  const n = Math.abs(Number(link)) || 0;
  const ts = n >= VALUE_BET_LINK_BASE ? n - VALUE_BET_LINK_BASE : n;
  if (ts >= ARB_LINK_MIN)
    return ts >= start && ts < end;
  const at = Number(createAt) || 0;
  return at >= start && at < end;
}

/**
 * [changmen 扩展] 手动改绑：仅允许把较新的 Link 改到较老的 Link。
 * from !== to 且双方非 0。
 */
export function canRebindLinkNewerToOlder(fromLink, toLink) {
  const from = Number(fromLink);
  const to = Number(toLink);
  if (!Number.isFinite(from) || !Number.isFinite(to) || from === 0 || to === 0)
    return false;
  if (from === to)
    return false;
  return orderLinkSortKey(from) > orderLinkSortKey(to);
}

/** 从 bet 抽出地图槽（全场 / 地图N）；无法识别则 "—" */
export function parseBetMapLabel(bet) {
  const s = String(bet || "").trim();
  if (!s)
    return "—";
  const bracketMap = /^\[地图\s*(\d+)\]/.exec(s);
  if (bracketMap)
    return `地图${bracketMap[1]}`;
  const bracketFull = /^\[全场\]/.exec(s);
  if (bracketFull)
    return "全场";
  const plainMap = /^地图\s*(\d+)/.exec(s);
  if (plainMap)
    return `地图${plainMap[1]}`;
  const enMap = /^Map\s*(\d+)\b/i.exec(s);
  if (enMap)
    return `地图${enMap[1]}`;
  if (/全场/.test(s))
    return "全场";
  return "—";
}

/** 归一化对阵标题：去 HTML、运动前缀、Game/Map 后缀；主客对调视为同场 */
export function normalizeOrderMatchKey(match) {
  let raw = String(match || "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
  if (!raw)
    return "";
  // PM 等：`LoL: Team A vs Team B - Game 2 Winner`
  raw = raw.replace(
    /^(lol|league of legends|dota\s*2?|cs:?go|cs2|counter[- ]?strike|valorant|val|kog|王者荣耀|英雄联盟)\s*[:：\-–—]\s*/i,
    "",
  );
  const parts = raw.split(/\s+vs\.?\s+|\s+v\.?\s+/i);
  if (parts.length === 2) {
    const clean = (s) => String(s || "")
      .replace(/\s*[-–—]\s*(game|map|地图)\s*\d+\b.*$/i, "")
      .replace(/\s*[-–—]\s*.*\b(winner|获胜|胜负)\b.*$/i, "")
      .trim();
    const a = clean(parts[0]);
    const b = clean(parts[1]);
    if (a && b)
      return [a, b].sort().join(" vs ");
  }
  return raw;
}

/**
 * [changmen 扩展] 手动改绑：须同场（Match）且同地图槽（Bet 前缀）。
 * 无法解析地图时拒绝。
 */
export function isSameOrderMatchMap(a, b) {
  const matchA = normalizeOrderMatchKey(a?.match ?? a?.Match);
  const matchB = normalizeOrderMatchKey(b?.match ?? b?.Match);
  if (!matchA || !matchB || matchA !== matchB)
    return false;
  const mapA = parseBetMapLabel(a?.bet ?? a?.Bet);
  const mapB = parseBetMapLabel(b?.bet ?? b?.Bet);
  if (mapA === "—" || mapB === "—")
    return false;
  return mapA === mapB;
}

/**
 * [changmen 推测] 旧占位：link = create_at（场馆时间 ms）；仅 legacy 读路径/迁移用。
 */
export function placeholderLinkFromCreateAt(createAt, fallbackMs = Date.now()) {
  const ts = Number(createAt);
  if (Number.isFinite(ts) && ts > 0)
    return ts;
  const fb = Number(fallbackMs);
  return Number.isFinite(fb) && fb > 0 ? fb : Date.now();
}

/** 未绑单 SaveOrder 占位 Link = RDS 入库时刻（ms） */
export function placeholderLinkFromInsertAt(insertMs = Date.now()) {
  const ts = Number(insertMs);
  if (Number.isFinite(ts) && ts > 0)
    return ts;
  return Date.now();
}

/** 非套利 SaveOrder 后端绑定：略早于 create_at，满足 link < create_at */
export function backendBindLinkFromCreateAt(createAt) {
  const ca = Number(createAt);
  if (Number.isFinite(ca) && ca > 1)
    return ca - 1;
  const now = Date.now();
  return now > 1 ? now - 1 : 0;
}

/** 旧 changmen 占位 hash：link 为 0 / null 或 0 < link < 1e12 */
export function isHashLink(link) {
  const n = Number(link);
  if (!Number.isFinite(n) || n === 0)
    return true;
  if (n > 0 && n < ARB_LINK_MIN)
    return true;
  return false;
}

/** legacy 未绑单占位：link 与 create_at 同为 ms 时间戳 */
export function isCreateAtPlaceholderLink(link, createAt) {
  const l = Number(link);
  const ca = Number(createAt);
  if (!Number.isFinite(l) || l < ARB_LINK_MIN)
    return false;
  if (!Number.isFinite(ca) || ca <= 0)
    return false;
  return l === ca;
}

/**
 * SaveOrder 未绑占位：link = create_at - 1（backendBindLinkFromCreateAt）。
 * 与前端 isUnboundPlaceholderLink / auto-rebind 对齐；须允许改绑到继承的 arb linkId
 *（补单成交常晚于 attempt 数分钟，不能走「近 create_at 优先」距离门控）。
 */
export function isBackendBindPlaceholderLink(link, createAt) {
  const l = Number(link);
  const ca = Number(createAt);
  if (!Number.isFinite(l) || l < ARB_LINK_MIN)
    return false;
  if (!Number.isFinite(ca) || ca <= 1)
    return false;
  return l === ca - 1;
}

/** 未绑单 RDS 入库占位：≥ 1e12 且晚于场馆 create_at（与 legacy create_at 占位区分） */
export function isInsertTimePlaceholderLink(link, createAt) {
  const l = Number(link);
  const ca = Number(createAt);
  if (!Number.isFinite(l) || l < ARB_LINK_MIN)
    return false;
  if (isCreateAtPlaceholderLink(l, ca))
    return false;
  if (isBackendBindPlaceholderLink(l, ca))
    return false;
  if (!Number.isFinite(ca) || ca <= 0)
    return true;
  return l > ca;
}

/** SaveOrderBind 写入的套利/共享 LinkID（≥ 1e12） */
export function isArbBindLink(link) {
  const n = Number(link);
  return Number.isFinite(n) && n >= ARB_LINK_MIN;
}

/** 正 EV 单边：`-(VALUE_BET_LINK_BASE + ts)`（与 client-core isValueBetLink 对齐） */
export function isValueBetLink(link) {
  const n = Number(link);
  return Number.isFinite(n) && n < 0 && Math.abs(n) >= VALUE_BET_LINK_BASE;
}

/** 比例 9999 单边：负时间戳且非正 EV */
export function isSingleLegRateLink(link) {
  const n = Number(link);
  return Number.isFinite(n) && n < 0 && Math.abs(n) < VALUE_BET_LINK_BASE;
}

/**
 * SaveOrder 已确认的客户端分组 link（套利 / 正 EV / 9999），同步时不得被场馆占位覆盖。
 */
export function isConfirmedClientBindLink(link) {
  return isArbBindLink(link) || isValueBetLink(link) || isSingleLegRateLink(link);
}

/** 套利 linkId 与场馆 create_at 允许偏差（SaveOrderBind 用 Date.now()，通常 ≤ 数秒） */
export const ARB_LINK_CREATE_AT_TOLERANCE_MS = 90_000;

/**
 * SaveOrderBind 是否允许把已有套利 link 改成另一套利 link。
 * 防止拒单复检时 orders[0] 误绑历史订单（如 PM delayed 列表尚未含新单）。
 */
export function shouldAllowOrderBind(prevRow, linkVal) {
  const prevLink = Number(prevRow?.link);
  const next = Number(linkVal);
  if (!isArbBindLink(next))
    return true;
  if (!isArbBindLink(prevLink))
    return true;
  if (prevLink === next)
    return true;
  if (isCreateAtPlaceholderLink(prevLink, prevRow?.create_at))
    return true;
  if (isBackendBindPlaceholderLink(prevLink, prevRow?.create_at))
    return true;
  if (isHashLink(prevLink))
    return true;
  const ca = Number(prevRow?.create_at);
  if (!Number.isFinite(ca) || ca <= 0)
    return false;
  const prevDist = Math.abs(prevLink - ca);
  const nextDist = Math.abs(next - ca);
  if (prevDist < nextDist && nextDist > ARB_LINK_CREATE_AT_TOLERANCE_MS)
    return false;
  return true;
}

/** SaveOrderBind：从占位 link 改为共享 LinkID 时触发 bound 通知 */
export function shouldFireOrderBoundHook(prevRow, linkVal) {
  const prevLink = Number(prevRow?.link);
  const next = Number(linkVal);
  if (!isArbBindLink(next))
    return false;
  if (prevLink === next)
    return false;
  if (isHashLink(prevLink))
    return true;
  if (isCreateAtPlaceholderLink(prevLink, prevRow?.create_at))
    return true;
  if (isBackendBindPlaceholderLink(prevLink, prevRow?.create_at))
    return true;
  return isInsertTimePlaceholderLink(prevLink, prevRow?.create_at);
}

/** 仅 PB 平台的 hash 占位单（读路径与通知均排除） */
export function isPbHashOrder(link, provider) {
  if (!isHashLink(link))
    return false;
  return String(provider ?? "").trim() === "PB";
}

/** [A8 可证实] bundle 无客户端过滤；通知等辅助判断（非 changmen 侧栏 SQL） */
export function isOrderListVisible(link, provider) {
  const n = Number(link);
  if (Number.isFinite(n) && n < 0)
    return true;
  if (Number.isFinite(n) && n >= ARB_LINK_MIN)
    return true;
  return String(provider ?? "").trim() !== "PB";
}

/**
 * [已废弃] 曾用 link < create_at 隐藏 A8 同步单；订单查询现返回全量。
 */
export const CLIENT_ORDER_LIST_SQL = "link < create_at";

export function isClientOrderListVisible(link, createAt) {
  const l = Number(link);
  const ca = Number(createAt);
  if (!Number.isFinite(l) || !Number.isFinite(ca))
    return false;
  return l < ca;
}

/** 拼到已有 WHERE 后：`base AND link < create_at` */
export function orderVisibleSqlAnd(baseWhere) {
  const w = String(baseWhere || "").trim();
  if (!w)
    return CLIENT_ORDER_LIST_SQL;
  return `${w} AND ${CLIENT_ORDER_LIST_SQL}`;
}

import assert from "node:assert/strict";
import { describe, it } from "vitest";
import {
  ARB_LINK_MIN,
  VALUE_BET_LINK_BASE,
  backendBindLinkFromCreateAt,
  CLIENT_ORDER_LIST_SQL,
  canRebindLinkNewerToOlder,
  isSameOrderMatchMap,
  normalizeOrderMatchKey,
  parseBetMapLabel,
  isArbBindLink,
  isConfirmedClientBindLink,
  isBackendBindPlaceholderLink,
  isClientOrderListVisible,
  isCreateAtPlaceholderLink,
  isHashLink,
  isInsertTimePlaceholderLink,
  isOrderListVisible,
  isPbHashOrder,
  isSingleLegRateLink,
  isValueBetLink,
  orderBelongsToMsRange,
  orderLinkSortKey,
  orderVisibleSqlAnd,
  placeholderLinkFromCreateAt,
  sqlOrderBelongsToRange,
  placeholderLinkFromInsertAt,
  shouldAllowOrderBind,
  shouldFireOrderBoundHook,
} from "./order_link_filter.js";

describe("order_link_filter", () => {
  it("isHashLink detects placeholder links", () => {
    assert.equal(isHashLink(12345), true);
    assert.equal(isHashLink(1_000_000_000_001), false);
    assert.equal(isHashLink(-1), false);
  });

  it("isPbHashOrder only matches PB hash orders", () => {
    assert.equal(isPbHashOrder(12345, "PB"), true);
    assert.equal(isPbHashOrder(12345, "OB"), false);
    assert.equal(isPbHashOrder(1_000_000_000_001, "PB"), false);
  });

  it("orderVisibleSqlAnd appends link filter", () => {
    assert.equal(orderVisibleSqlAnd("user_id = $1"), "user_id = $1 AND link < create_at");
    assert.equal(orderVisibleSqlAnd(""), "link < create_at");
  });

  it("isClientOrderListVisible uses link < create_at", () => {
    const ca = 1_781_890_412_000;
    assert.equal(isClientOrderListVisible(1_781_890_411_000, ca), true);
    assert.equal(isClientOrderListVisible(ca + 50_000, ca), false);
    assert.equal(isClientOrderListVisible(-ca, ca), true);
    assert.equal(CLIENT_ORDER_LIST_SQL, "link < create_at");
  });

  it("isOrderListVisible matches A8 JS helper (not SQL)", () => {
    assert.equal(isOrderListVisible(1_000_000_000_001, "PB"), true);
    assert.equal(isOrderListVisible(12345, "OB"), true);
    assert.equal(isOrderListVisible(12345, "PB"), false);
    assert.equal(isOrderListVisible(-1, "RAY"), true);
  });

  it("orderBelongsToMsRange uses Link bind time for timestamp links", () => {
    const bind = Date.parse("2026-09-04T23:46:13+08:00");
    const fill = Date.parse("2026-09-05T00:08:27+08:00");
    const dayStart = Date.parse("2026-09-04T00:00:00+08:00");
    const dayEnd = Date.parse("2026-09-05T00:00:00+08:00");
    const nextStart = dayEnd;
    const nextEnd = Date.parse("2026-09-06T00:00:00+08:00");
    assert.equal(orderBelongsToMsRange(bind, fill, dayStart, dayEnd), true);
    assert.equal(orderBelongsToMsRange(bind, fill, nextStart, nextEnd), false);
  });

  it("orderBelongsToMsRange falls back to create_at for small placeholder links", () => {
    const fill = Date.parse("2026-09-05T00:08:27+08:00");
    const dayStart = Date.parse("2026-09-04T00:00:00+08:00");
    const dayEnd = Date.parse("2026-09-05T00:00:00+08:00");
    const nextStart = dayEnd;
    const nextEnd = Date.parse("2026-09-06T00:00:00+08:00");
    assert.equal(orderBelongsToMsRange(42, fill, dayStart, dayEnd), false);
    assert.equal(orderBelongsToMsRange(42, fill, nextStart, nextEnd), true);
  });

  it("orderBelongsToMsRange decodes value-bet links", () => {
    const ts = Date.parse("2026-09-04T12:00:00+08:00");
    const vb = -(VALUE_BET_LINK_BASE + ts);
    const dayStart = Date.parse("2026-09-04T00:00:00+08:00");
    const dayEnd = Date.parse("2026-09-05T00:00:00+08:00");
    assert.equal(orderBelongsToMsRange(vb, ts + 86400000, dayStart, dayEnd), true);
  });

  it("sqlOrderBelongsToRange uses Link home then create_at fallback", () => {
    const sql = sqlOrderBelongsToRange(2, 3);
    assert.match(sql, /ABS\(link\) >= 1000000000000/);
    assert.match(sql, /7000000000000000/);
    assert.match(sql, /\$2/);
    assert.match(sql, /\$3/);
    assert.match(sql, /create_at >= \$2 AND create_at < \$3/);
  });

  it("placeholderLinkFromCreateAt uses create_at ms", () => {
    assert.equal(placeholderLinkFromCreateAt(1_781_882_462_790), 1_781_882_462_790);
    assert.equal(placeholderLinkFromCreateAt(0, 99), 99);
    assert.equal(placeholderLinkFromCreateAt("bad", 42), 42);
  });

  it("isCreateAtPlaceholderLink matches link === create_at", () => {
    const ca = 1_781_882_462_790;
    assert.equal(isCreateAtPlaceholderLink(ca, ca), true);
    assert.equal(isCreateAtPlaceholderLink(ca + 1, ca), false);
    assert.equal(isCreateAtPlaceholderLink(12345, ca), false);
  });

  it("backendBindLinkFromCreateAt is before create_at", () => {
    const ca = 1_781_882_462_790;
    assert.equal(backendBindLinkFromCreateAt(ca), ca - 1);
    assert.ok(backendBindLinkFromCreateAt(ca) < ca);
  });

  it("isBackendBindPlaceholderLink matches create_at - 1", () => {
    const ca = 1_781_882_462_790;
    assert.equal(isBackendBindPlaceholderLink(ca - 1, ca), true);
    assert.equal(isBackendBindPlaceholderLink(ca, ca), false);
    assert.equal(isBackendBindPlaceholderLink(ca - 2, ca), false);
  });

  it("placeholderLinkFromInsertAt uses insert ms", () => {
    assert.equal(placeholderLinkFromInsertAt(1_781_900_000_000), 1_781_900_000_000);
    assert.ok(placeholderLinkFromInsertAt(0) >= ARB_LINK_MIN);
  });

  it("isInsertTimePlaceholderLink requires link after create_at", () => {
    const ca = 1_781_882_462_790;
    assert.equal(isInsertTimePlaceholderLink(ca + 50_000, ca), true);
    assert.equal(isInsertTimePlaceholderLink(ca, ca), false);
    assert.equal(isInsertTimePlaceholderLink(ca - 1, ca), false);
  });

  it("shouldFireOrderBoundHook covers hash and create_at placeholders", () => {
    const arb = 1_700_000_000_123;
    assert.equal(
      shouldFireOrderBoundHook({ link: 12345, create_at: 1 }, arb),
      true,
    );
    const ca = 1_781_882_462_790;
    assert.equal(
      shouldFireOrderBoundHook({ link: ca, create_at: ca }, arb),
      true,
    );
    assert.equal(
      shouldFireOrderBoundHook({ link: ca - 1, create_at: ca }, arb),
      true,
    );
    assert.equal(
      shouldFireOrderBoundHook({ link: ca + 60_000, create_at: ca }, arb),
      true,
    );
    assert.equal(
      shouldFireOrderBoundHook({ link: arb, create_at: ca }, arb + 1),
      false,
    );
    assert.equal(shouldFireOrderBoundHook({ link: 12345 }, 99999), false);
  });

  it("isArbBindLink requires ms-scale link", () => {
    assert.equal(isArbBindLink(1_000_000_000_001), true);
    assert.equal(isArbBindLink(12345), false);
  });

  it("classifies value-bet and 9999 links", () => {
    const ts = 1_756_000_000_000;
    const vb = -(VALUE_BET_LINK_BASE + ts);
    const single = -ts;
    assert.equal(isValueBetLink(vb), true);
    assert.equal(isSingleLegRateLink(vb), false);
    assert.equal(isValueBetLink(single), false);
    assert.equal(isSingleLegRateLink(single), true);
    assert.equal(isConfirmedClientBindLink(vb), true);
    assert.equal(isConfirmedClientBindLink(single), true);
    assert.equal(isConfirmedClientBindLink(ts), true);
    assert.equal(isConfirmedClientBindLink(12345), false);
  });

  it("shouldAllowOrderBind refuses far link overwriting near arb link", () => {
    const ca = 1_783_195_621_000;
    const prevLink = 1_783_195_619_962;
    assert.equal(
      shouldAllowOrderBind({ link: prevLink, create_at: ca }, 1_783_199_338_220),
      false,
    );
    assert.equal(
      shouldAllowOrderBind({ link: ca, create_at: ca }, 1_700_000_000_123),
      true,
    );
    assert.equal(
      shouldAllowOrderBind({ link: 12345, create_at: ca }, 1_700_000_000_123),
      true,
    );
    assert.equal(
      shouldAllowOrderBind({ link: prevLink, create_at: ca }, prevLink),
      true,
    );
  });

  it("shouldAllowOrderBind allows makeup rebind from create_at-1 to inherited arb link", () => {
    // Shopify map2 makeup: PM create_at minutes after RAY attempt linkId
    const createAt = 1_783_645_770_000;
