        { match: "A vs B", bet: "[地图2] 获胜" },
        { match: "B vs A", bet: "[地图2] 让分" },
      ),
      true,
    );
    assert.equal(
      isSameOrderMatchMap(
        { match: "A vs B", bet: "[地图2] 获胜" },
        { match: "A vs B", bet: "[地图1] 获胜" },
      ),
      false,
    );
    assert.equal(
