/**
 * JWT 签发与校验（RDS auth 段使用）。
 */

import crypto from "node:crypto";

export const JWT_SECRET = process.env.JWT_SECRET || "";
export const JWT_ISSUER = process.env.JWT_ISSUER || "changmen-auth";
export const JWT_AUDIENCE = process.env.JWT_AUDIENCE || "changmen-api";

export function parseJwtTtl(raw, fallbackSec) {
  const s = String(raw || "").trim();
  if (!s)
    return fallbackSec;
  const m = s.match(/^(\d+)([smhd])?$/i);
  if (!m)
    return fallbackSec;
  const n = Number(m[1]);
  const u = (m[2] || "s").toLowerCase();
  const mult = { s: 1, m: 60, h: 3600, d: 86400 };
  return n * (mult[u] || 1);
}

export const JWT_ACCESS_TTL_SEC = parseJwtTtl(process.env.JWT_ACCESS_TTL, 15 * 60);
export const JWT_BROWSER_ACCESS_TTL_SEC = parseJwtTtl(process.env.JWT_BROWSER_ACCESS_TTL, 15 * 60);
export const JWT_REFRESH_TTL_SEC = parseJwtTtl(process.env.JWT_REFRESH_TTL, 30 * 86400);

export function signJwt(payload, secret, ttlSec) {
  const header = { alg: "HS256", typ: "JWT" };
  const now = Math.floor(Date.now() / 1000);
  const body = {
    iss: JWT_ISSUER,
    aud: JWT_AUDIENCE,
    jti: crypto.randomUUID(),
    ...payload,
    iat: now,
    exp: now + ttlSec,
  };
  const h = Buffer.from(JSON.stringify(header)).toString("base64url");
  const p = Buffer.from(JSON.stringify(body)).toString("base64url");
  const sig = crypto.createHmac("sha256", secret).update(`${h}.${p}`).digest("base64url");
  return `${h}.${p}.${sig}`;
}

export function verifyJwt(token, secret, { allowExpired = false } = {}) {
  const parts = String(token || "").split(".");
  if (parts.length !== 3)
    return null;
  const [h, p, sig] = parts;
  let header;
  try { header = JSON.parse(Buffer.from(h, "base64url").toString("utf8")); }
  catch { return null; }
  if (header?.alg !== "HS256" || header?.typ !== "JWT")
    return null;
  const expected = crypto.createHmac("sha256", secret).update(`${h}.${p}`).digest();
  let supplied;
  try { supplied = Buffer.from(sig, "base64url"); }
  catch { return null; }
  if (supplied.length !== expected.length || !crypto.timingSafeEqual(supplied, expected))
    return null;
  try {
    const payload = JSON.parse(Buffer.from(p, "base64url").toString("utf8"));
    if (!Number.isFinite(payload.exp) || (!allowExpired && payload.exp * 1000 <= Date.now()))
      return null;
    const hasModernClaims = payload.iss != null || payload.aud != null || payload.jti != null;
    if (hasModernClaims && (payload.iss !== JWT_ISSUER || payload.aud !== JWT_AUDIENCE || !payload.jti))
      return null;
    return payload;
  }
  catch {
    return null;
  }
}

export function decodeJwtPayload(token) {
  try {
    const p = String(token || "").split(".")[1];
    if (!p)
      return null;
    return JSON.parse(Buffer.from(p, "base64url").toString("utf8"));
  }
  catch {
    return null;
  }
}

/**
 * Matcher 数据访问 — 读写均走 RDS（PostgreSQL）。
 */

import { getPgPool, jsonb } from "./common.js";

function pool() {
  return getPgPool();
}

async function rdsQuery(sql, params = []) {
  const p = pool();
  if (!p)
    throw new Error("RDS 未配置");
  return p.query(sql, params);
}

export function isMatcherStoreReady() {
  return !!pool();
}

/** M3：仅活跃行参与 merge_key / 平台重叠身份复用（ended 不得占坑） */
export async function fetchClientMatchIdIndex() {
  const { rows } = await rdsQuery(
    `SELECT id, merge_key, matchs FROM client_matches
     WHERE ended_at IS NULL`,
  );
  return rows.map(r => ({
    id: Number(r.id),
    merge_key: r.merge_key,
    matchs: r.matchs || {},
  }));
}

export async function findClientMatchIdByMergeKey(mergeKey) {
  const key = String(mergeKey || "").trim();
  if (!key)
    return null;
  const { rows } = await rdsQuery(
    `SELECT id FROM client_matches
     WHERE merge_key = $1 AND ended_at IS NULL
     LIMIT 1`,
    [key],
  );
  return rows[0] ? Number(rows[0].id) : null;
}

async function insertClientMatchStubRds(mergeKey, stub) {
  const builtAt = Date.now();
  const params = [
    mergeKey,
    String(stub.title || ""),
    stub.game != null ? String(stub.game) : null,
    stub.game_id != null ? String(stub.game_id) : null,
    Number(stub.start_time) || 0,
    Number(stub.bo) || 0,
    Number(stub.round) || 0,
    Number(stub.round_start) || 0,
    jsonb(stub.matchs, {}),
    jsonb([], []),
    builtAt,
  ];
  const insertSql = `INSERT INTO client_matches (
        merge_key, title, game, game_id, start_time, bo, round, round_start, matchs, bets, built_at
      ) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9::jsonb,$10::jsonb,$11)
      RETURNING id`;

  async function tryInsert() {
    const { rows } = await rdsQuery(insertSql, params);
    return Number(rows[0].id);
  }

  try {
    return await tryInsert();
  }
  catch (err) {
    if (err.code !== "23505")
      throw err;

    // M3：优先复用仍活跃的同 key；勿把 sticky ended id 交回给新场
    const active = await rdsQuery(
      `SELECT id FROM client_matches
       WHERE merge_key = $1 AND ended_at IS NULL
       LIMIT 1`,
      [mergeKey],
    );
    if (active.rows.length)
      return Number(active.rows[0].id);

    // 仅 ended 占坑：改名腾出 merge_key，再 insert 新活场
    await rdsQuery(
      `UPDATE client_matches
       SET merge_key = merge_key || '@ended:' || id::text
       WHERE merge_key = $1 AND ended_at IS NOT NULL`,
      [mergeKey],
    );
    try {
      return await tryInsert();
    }
    catch (err2) {
      if (err2.code !== "23505")
        throw err2;
      const again = await rdsQuery(
        `SELECT id FROM client_matches
         WHERE merge_key = $1 AND ended_at IS NULL
         LIMIT 1`,
        [mergeKey],
      );
      if (again.rows.length)
        return Number(again.rows[0].id);
      throw err2;
    }
  }
}

export async function insertClientMatchStub(mergeKey, stub = {}) {
  const key = String(mergeKey || "").trim();
  if (!key)
    throw new Error("merge_key 不能为空");
  return insertClientMatchStubRds(key, stub);
}

export function getClientMatchIdAdapter() {
  return {
    fetchClientMatchIndex: fetchClientMatchIdIndex,
    insertClientMatchStub,
    findClientMatchIdByMergeKey,
  };
}

