/** 单条账号 upsert 到 players（SaveData ACCOUNT / 余额刷新） */
export async function savePlayerAccountRecord(ownerUserId, record) {
  const uid = String(ownerUserId || "").trim();
  const patch = accountRecordToPlayerPatch(record);
  const id = Number(patch.playerId);
  if (!uid || !Number.isFinite(id) || id <= 0)
    return false;
  const pool = getPgPool();
  if (!pool)
    return false;
  const now = Number(patch.updatedAt) || Date.now();
  const platformId = patch.platformId;
  try {
    const params = [
      id,
      uid,
      patch.platformName,
      patch.playerName,
      patch.provider,
      String(patch.venueMemberId || ""),
      String(patch.venueAccountKey || ""),
      patch.credit,
      patch.totalBalance,
      _jsonb(patch.accountData, {}),
      now,
    ];
    let platformClause = "";
    if (platformId != null && Number.isFinite(platformId) && platformId > 0) {
      params.push(platformId);
      platformClause = `, platform_id = $${params.length}`;
    }
    // PredictFun：仅当库内 provider 已是 PF 时保护账本（勿用入参 provider，否则伪造可清 OB credit）；
    // 若历史误写在 credit 且 total_balance=0，顺带迁入（对齐 resolvePfBalance）。
    const { rowCount } = await pool.query(
      `UPDATE players SET
         platform_name = $3,
         player_name = $4,
         provider = CASE
           WHEN lower(provider) = 'predictfun' THEN provider
           ELSE $5
         END,
         venue_member_id = $6,
         venue_account_key = $7,
         total_balance = CASE
           WHEN lower(provider) = 'predictfun' THEN
             CASE
               WHEN coalesce(total_balance, 0) = 0 AND coalesce(credit, 0) > 0 THEN credit
               ELSE total_balance
             END
           ELSE $9
         END,
         credit = CASE
           WHEN lower(provider) = 'predictfun' THEN 0
           ELSE $8
         END,
         account_data = $10::jsonb,
         updated_at = $11${platformClause}
       WHERE id = $1 AND owner_user_id = $2::uuid AND deleted_at IS NULL`,
      params,
    );
    return (rowCount ?? 0) > 0;
  }
  catch (err) {
    if (isVenueAccountKeyUniqueViolation(err))
      throw new VenueAccountKeyConflictError("该场馆操盘账号已被其他用户使用");
    console.warn("[rds] savePlayerAccountRecord:", err.message);
    return false;
  }
}

/** SaveData ACCOUNT: default is a confirmed batch; replaceWith adds locked merge + prune. */
export async function saveAccountRecordsForOwner(ownerUserId, records, { replaceWith, prune = true, skipUnchanged } = {}) {
  if (replaceWith) {
    return replaceAccountRecordsForOwner(ownerUserId,
      (records || []).map(row => row?.accountId ?? row?.AccountId), replaceWith, { prune, skipUnchanged });
  }
  const uid = String(ownerUserId || "").trim();
  if (!uid || !Array.isArray(records) || !records.length)
    return 0;
  return batchSavePlayerAccountRecords(uid, records);
}

/** 批量 UPDATE players（SaveData ACCOUNT 落库） */
export async function batchSavePlayerAccountRecords(ownerUserId, records, { client } = {}) {
  const uid = String(ownerUserId || "").trim();
  if (!uid || !Array.isArray(records) || !records.length)
    return 0;
  const patches = records
    .map(r => accountRecordToPlayerPatch(r))
    .filter(p => Number.isFinite(p.playerId) && p.playerId > 0);
  if (patches.length !== records.length || new Set(patches.map(p => p.playerId)).size !== patches.length)
    throw new Error("账号保存包含无效或重复的 accountId");
  const pool = client || getPgPool();
  if (!pool)
    throw new Error("数据库不可用，账号未保存");
  if (!client) {
    const connection = await pool.connect();
    try {
      await connection.query("BEGIN");
      const count = await batchSavePlayerAccountRecords(uid, records, { client: connection });
      await connection.query("COMMIT");
      return count;
    }
    catch (err) {
      await connection.query("ROLLBACK").catch(() => {});
      throw err;
    }
    finally { connection.release(); }
  }
  const now = Date.now();
  const ids = [];
  const platformNames = [];
  const playerNames = [];
  const providers = [];
  const venueMemberIds = [];
  const venueAccountKeys = [];
  const credits = [];
  const totalBalances = [];
  const accountDatas = [];
  const updatedAts = [];
  const platformIds = [];
  for (const patch of patches) {
    ids.push(Number(patch.playerId));
    platformNames.push(String(patch.platformName || ""));
    playerNames.push(String(patch.playerName || ""));
    providers.push(String(patch.provider || ""));
    venueMemberIds.push(String(patch.venueMemberId || ""));
    venueAccountKeys.push(String(patch.venueAccountKey || ""));
    credits.push(Number(patch.credit) || 0);
    totalBalances.push(Number(patch.totalBalance) || 0);
    accountDatas.push(JSON.parse(_jsonb(patch.accountData, {})));
    updatedAts.push(Number(patch.updatedAt) || now);
    platformIds.push(
      patch.platformId != null && Number.isFinite(Number(patch.platformId)) && Number(patch.platformId) > 0
        ? Number(patch.platformId)
        : null,
    );
  }
  for (const patch of patches) {
    const key = String(patch.venueAccountKey || "").trim();
    if (!key)
      continue;
    let conflict;
    try {
      conflict = await findVenueAccountKeyConflictStrict(key, { playerId: patch.playerId, client });
    }
    catch (err) {
      console.error("[rds] findVenueAccountKeyConflictStrict 失败，已中止 SaveData:", err?.message);
      throw new Error("场馆账号占用检查失败，请稍后重试（已阻止保存）");
    }
    if (!conflict)
      continue;
    const sameOwner = conflict.ownerUserId && conflict.ownerUserId === uid;
    if (sameOwner && conflict.deleted) {
      throw new VenueAccountKeyConflictError(
        ownSoftDeletedVenueAccountMessage(conflict),
        conflict,
      );
    }
    throw new VenueAccountKeyConflictError(venueAccountKeyConflictMessage(conflict), conflict);
  }
  try {
    // PredictFun：只认库内 p.provider（勿 OR u.provider，否则伪造 PredictFun 会把 OB credit 清 0）；
    // ACCOUNT 不得绝对 SET total_balance；credit>0 且 total_balance=0 时迁入。
    const { rowCount } = await pool.query(
      `UPDATE players AS p SET
         platform_name = u.platform_name,
         player_name = u.player_name,
         provider = CASE
           WHEN lower(p.provider) = 'predictfun' THEN p.provider
           ELSE u.provider
         END,
         venue_member_id = u.venue_member_id,
         venue_account_key = u.venue_account_key,
         total_balance = CASE
           WHEN lower(p.provider) = 'predictfun' THEN
             CASE
               WHEN coalesce(p.total_balance, 0) = 0 AND coalesce(p.credit, 0) > 0 THEN p.credit
               ELSE p.total_balance
             END
           ELSE u.total_balance
         END,
         credit = CASE
           WHEN lower(p.provider) = 'predictfun' THEN 0
           ELSE u.credit
         END,
         account_data = u.account_data,
         updated_at = u.updated_at,
         platform_id = COALESCE(u.platform_id, p.platform_id)
       FROM unnest(
         $1::bigint[],
         $2::text[],
         $3::text[],
         $4::text[],
         $5::text[],
         $6::text[],
         $7::float8[],
         $8::float8[],
         $9::jsonb[],
         $10::bigint[],
         $11::bigint[]
       ) AS u(
         id, platform_name, player_name, provider, venue_member_id, venue_account_key, credit, total_balance,
         account_data, updated_at, platform_id
       )
       WHERE p.id = u.id
         AND p.owner_user_id = $12::uuid
         AND p.deleted_at IS NULL`,
      [
        ids,
        platformNames,
        playerNames,
        providers,
        venueMemberIds,
        venueAccountKeys,
        credits,
        totalBalances,
        accountDatas,
        updatedAts,
        platformIds,
        uid,
      ],
    );
    if (rowCount !== ids.length)
      throw new Error("账号保存未全部确认：账号不存在、已删除或归属已变更");
    return rowCount;
  }
  catch (err) {
    if (isVenueAccountKeyUniqueViolation(err))
      throw new VenueAccountKeyConflictError("该场馆操盘账号已被其他用户使用");
    console.warn("[rds] batchSavePlayerAccountRecords:", err.message);
    throw err;
  }
}

/**
 * One ACCOUNT replacement: lock owner, read authoritative rows, validate/merge, write and prune.
 * prepare is a side-effect-free business transformation; no cache is published before COMMIT.
 */
export async function replaceAccountRecordsForOwner(ownerUserId, accountIds, prepare, { prune = true, skipUnchanged } = {}) {
  const uid = String(ownerUserId || "").trim();
  if (!uid)
    throw new Error("请先登录");
  const pool = getPgPool();
  if (!pool)
    throw new Error("数据库不可用，账号未保存");
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    // Owner-level serialization also protects the empty-owned-list case across processes.
    const owner = await client.query("SELECT id FROM profiles WHERE id=$1::uuid FOR UPDATE", [uid]);
    if (!owner.rows.length)
      throw new Error("用户 profile 不存在");
    const owned = await client.query(
      `SELECT ${PLAYER_SELECT} FROM players
       WHERE owner_user_id=$1::uuid AND deleted_at IS NULL ORDER BY id FOR UPDATE`, [uid],
    );
    const ids = [...new Set((accountIds || []).map(Number).filter(id => Number.isSafeInteger(id) && id > 0))];
    const foreign = ids.length ? await client.query(
      `SELECT ${PLAYER_SELECT} FROM players
       WHERE id=ANY($1::bigint[]) AND owner_user_id IS DISTINCT FROM $2::uuid AND deleted_at IS NULL`,
      [ids, uid],
    ) : { rows: [] };
    const players = [...owned.rows, ...foreign.rows].map(_mapPlayerRow);
    const existing = owned.rows.map(row => playerRowToAccountRecord(_mapPlayerRow(row)));
    const records = await prepare({ existing: structuredClone(existing), players });
    if (!Array.isArray(records))
      throw new Error("ACCOUNT 必须是数组");
    if (!records.length && existing.length)
      throw new Error("禁止用空列表覆盖已有账号，请刷新页面后重试");
    if (records.length) {
      const requested = new Set(ids);
      const writeRows = prune ? records : records.filter(row => requested.has(Number(row.accountId ?? row.AccountId)));
      if (writeRows.length && !skipUnchanged?.(existing, records))
        await batchSavePlayerAccountRecords(uid, writeRows, { client });
      if (prune)
        await softDeletePlayersNotInList(uid, records.map(row => row.accountId ?? row.AccountId), undefined, { client });
    }
    // SQL guards (notably the PF balance ledger) may retain values from the database.
    // Publish the committed representation, never an unconfirmed planned patch.
    const saved = await client.query(
      `SELECT ${PLAYER_SELECT} FROM players WHERE owner_user_id=$1::uuid AND deleted_at IS NULL ORDER BY id`, [uid],
    );
    await client.query("COMMIT");
    return saved.rows.map(row => playerRowToAccountRecord(_mapPlayerRow(row)));
  }
  catch (err) {
    await client.query("ROLLBACK").catch(() => {});
    throw err;
  }
  finally {
    client.release();
  }
}

/** 部分字段更新（余额刷新 syncAccountRowInKv） */
export async function patchPlayerAccountRecord(ownerUserId, playerId, updates) {
  const uid = String(ownerUserId || "").trim();
  const id = Number(playerId);
  if (!uid || !Number.isFinite(id) || id <= 0)
    return null;
  let found = false;
  const saved = await replaceAccountRecordsForOwner(uid, [id], ({ existing }) => existing.map(row => {
    if (Number(row.accountId) !== id) return row;
    found = true;
    return { ...row, ...updates, accountId: id, updateTime: Date.now() };
  }), { prune: false });
  return found ? saved.find(row => Number(row.accountId) === id) : null;
}

