}

function formatTeamPlatformMapWriteError(row) {
  return [
    "队伍关联失败：同一 gb_team_id 在该平台已有同名队伍映射",
    `${row.venue} · 「${row.venue_name}」· 场馆队伍 id ${row.venue_team_id}`,
    "请刷新 matcher 页面后重试；若两侧为同一平台且队名相同，同一标准队伍只能保留一个平台 id",
