let venueTeamIdColumn = null;

export async function resolveVenueTeamIdColumn(pool = getPgPool()) {
  if (venueTeamIdColumn)
    return venueTeamIdColumn;
  if (!pool)
    throw new Error("DATABASE_URL 未配置");
  const { rows } = await pool.query(
    `SELECT column_name FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'team_venue_maps'
       AND column_name IN ('venue_team_id', 'venue_id')`,
  );
  const names = new Set(rows.map(r => r.column_name));
  if (names.has("venue_team_id"))
    venueTeamIdColumn = "venue_team_id";
  else if (names.has("venue_id"))
    venueTeamIdColumn = "venue_id";
  else
    throw new Error("team_venue_maps 缺少 venue_team_id / venue_id 列");
  return venueTeamIdColumn;
}

export function readVenueTeamId(row) {
  if (row?.venue_team_id != null && row.venue_team_id !== "")
    return String(row.venue_team_id);
  if (row?.venue_id != null && row.venue_id !== "")
    return String(row.venue_id);
  return "";
}

/** YYYY-MM → 本地时区当月 [start, end) 毫秒 */
export function localMonthBounds(monthKey) {
  const parts = String(monthKey || "").split("-").map(Number);
  const y = parts[0];
  const m = parts[1];
  if (!y || !m) {
    const now = new Date();
    return localMonthBounds(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`);
  }
  const monthStart = new Date(y, m - 1, 1, 0, 0, 0, 0).getTime();
  const monthEnd = new Date(y, m, 1, 0, 0, 0, 0).getTime();
  return { monthStart, monthEnd };
}

/** YYYY-MM-DD → 本地时区当日 [start, end) 毫秒 */
export function localDayBounds(dateKey) {
  const parts = String(dateKey || "").split("-").map(Number);
  if (parts.length < 3 || parts.some(n => !Number.isFinite(n))) {
    const now = Date.now();
    const start = new Date(now);
    start.setHours(0, 0, 0, 0);
    return { dayStart: start.getTime(), dayEnd: start.getTime() + 86400000 };
  }
  const [y, m, d] = parts;
  const dayStart = new Date(y, m - 1, d, 0, 0, 0, 0).getTime();
  const dayEnd = new Date(y, m - 1, d + 1, 0, 0, 0, 0).getTime();
  return { dayStart, dayEnd };
}

import { describe, expect, it } from "vitest";
import { localDayBounds, localMonthBounds } from "./time_bounds.js";

describe("localDayBounds", () => {
  it("returns local midnight bounds for YYYY-MM-DD", () => {
    const { dayStart, dayEnd } = localDayBounds("2026-06-18");
    expect(dayEnd - dayStart).toBe(86400000);
    const d = new Date(dayStart);
    expect(d.getFullYear()).toBe(2026);
    expect(d.getMonth()).toBe(5);
    expect(d.getDate()).toBe(18);
    expect(d.getHours()).toBe(0);
  });
});

describe("localMonthBounds", () => {
  it("returns local month bounds for YYYY-MM", () => {
    const { monthStart, monthEnd } = localMonthBounds("2026-06");
    expect(monthEnd - monthStart).toBeGreaterThan(28 * 86400000);
    const d = new Date(monthStart);
    expect(d.getFullYear()).toBe(2026);
    expect(d.getMonth()).toBe(5);
    expect(d.getDate()).toBe(1);
  });
});

