/** vitest：match-identity 全部 *.test.mjs 参与 npm test / CI */
export default {
  test: {
    exclude: ["**/node_modules/**"],
  },
};

/**
 * ID/队名两阶段之后的补合并：
 * 4a 贴漏网馆 → 4b 并相似场（队名交集 / gb 桥，含队名反查 gb）
 */
import {
  lookupGbTeamIdByName,
  normalizeTeam,
} from "@changmen/match-identity/teams/team_key.js";
import { isPlaceholderTeamName } from "@changmen/match-identity/teams/match_utils.js";
import { sameTeamPair } from "../sides/orientation_lock.js";
import {
  ID_START_TOLERANCE_MS,
  NAME_START_TOLERANCE_MS,
  normalizeEpochMs,
} from "../util/time.js";

/** 多候选贴馆：最优与次优都够近且彼此差 &lt; 此值 → 歧义不贴 */
export const AMBIGUOUS_ATTACH_GAP_MS = 10 * 60 * 1000;

function gameKeyOf(entryOrRow) {
  const gid = entryOrRow.GameID ?? entryOrRow.gameId;
  if (gid != null && String(gid).trim() !== "" && String(gid) !== "0")
    return String(gid);
  return String(entryOrRow.gameCode || "").trim() || "";
}

function namePairOf(homeN, awayN) {
  if (!homeN || !awayN)
    return null;
  if (isPlaceholderTeamName(homeN) || isPlaceholderTeamName(awayN))
    return null;
  const [a, b] = homeN < awayN ? [homeN, awayN] : [awayN, homeN];
  return `${a}|${b}`;
}

function namePairFromEntry(entry) {
  return namePairOf(entry.homeN, entry.awayN);
}

function enrichGb(entry) {
  let homeGb = entry.homeGb || null;
  let awayGb = entry.awayGb || null;
  if (!homeGb && entry.homeN && entry.gameCode)
    homeGb = String(lookupGbTeamIdByName(entry.homeName || entry.homeN, entry.gameCode) || "").trim() || null;
  if (!awayGb && entry.awayN && entry.gameCode)
    awayGb = String(lookupGbTeamIdByName(entry.awayName || entry.awayN, entry.gameCode) || "").trim() || null;
  return { homeGb, awayGb };
}

function entryIndex(allEntries) {
  const map = new Map();
  for (const e of allEntries || [])
    map.set(e.rowKey, e);
  return map;
}

function membersOfRow(row, byKey) {
  const out = [];
  for (const [platform, sid] of Object.entries(row.Matchs || {})) {
    const e = byKey.get(`${platform}:${sid}`);
    if (e)
      out.push(e);
  }
  return out;
}

function clusterMeta(row, byKey) {
  const members = membersOfRow(row, byKey);
  const namePairs = new Set();
  let homeGb = null;
  let awayGb = null;
  let gbConflict = false;
  let bo = Number(row.BO) || 0;
  const gKey = gameKeyOf(row) || (members[0] ? gameKeyOf(members[0]) : "");

  for (const e of members) {
    const np = namePairFromEntry(e);
    if (np)
      namePairs.add(np);
    const g = enrichGb(e);
    if (g.homeGb && g.awayGb && g.homeGb !== g.awayGb) {
      if (!homeGb) {
        homeGb = g.homeGb;
        awayGb = g.awayGb;
      }
      else if (!sameTeamPair(homeGb, awayGb, g.homeGb, g.awayGb)) {
        gbConflict = true;
      }
    }
    if (!bo && e.BO)
      bo = Number(e.BO) || 0;
  }

  // Title 兜底 namePair
  const title = String(row.Title || "");
  const vs = title.split(/\s+vs\s+/i);
  if (vs.length >= 2) {
    const np = namePairOf(normalizeTeam(vs[0]), normalizeTeam(vs.slice(1).join(" vs ")));
    if (np)
      namePairs.add(np);
  }

  const startMs = normalizeEpochMs(row.StartTime) || 0;
  return {
    members,
    namePairs,
    // 簇内 gb 互相矛盾时禁用 gb 桥，避免误并
    gbPair: (!gbConflict && homeGb && awayGb) ? { homeGb, awayGb } : null,
    bo,
    gameKey: gKey,
    startMs,
    isSeed: row._clusterBasis === "seed" || row._clusterBasis === "binding",
  };
}

function timeDiffOk(aMs, bMs, tolMs) {
  const a = normalizeEpochMs(aMs);
  const b = normalizeEpochMs(bMs);
  if (!a || !b)
    return false;
  return Math.abs(a - b) <= tolMs;
}

function boConflict(aBo, bBo) {
  const a = Number(aBo) || 0;
  const b = Number(bBo) || 0;
  return a > 0 && b > 0 && a !== b;
}

function namePairsIntersect(setA, setB) {
  for (const p of setA) {
    if (setB.has(p))
      return true;
  }
  return false;
}

function gbCompatible(pairA, pairB) {
  if (!pairA || !pairB)
    return false;
  return sameTeamPair(pairA.homeGb, pairA.awayGb, pairB.homeGb, pairB.awayGb);
}

function hitCondition(metaA, metaB) {
  if (gbCompatible(metaA.gbPair, metaB.gbPair))
    return true;
  if (namePairsIntersect(metaA.namePairs, metaB.namePairs))
    return true;
  return false;
}

function matchsConflict(matchsA, matchsB) {
  for (const [p, sid] of Object.entries(matchsB || {})) {
    const prev = matchsA?.[p];
    if (prev != null && prev !== "" && String(prev) !== String(sid))
      return true;
  }
  return false;
}

function mergeMatchsUnion(rows) {
  const out = {};
  for (const row of rows) {
    for (const [p, sid] of Object.entries(row.Matchs || {})) {
      if (out[p] != null && String(out[p]) !== String(sid))
        return null; // conflict
      out[p] = String(sid);
    }
  }
  return out;
}

/** 合并簇时保留 PB rot 拼盘元数据（B1 periods / sibling 列表） */
function unionPbRotMeta(rows) {
  const sibs = new Set();
  let rot = "";
  for (const row of rows || []) {
    const r = String(row?._pbRotNum || "").trim();
    if (r && !rot)
      rot = r;
    for (const sid of row?._pbSiblingSourceMatchIds || []) {
      const s = String(sid || "").trim();
      if (s)
        sibs.add(s);
    }
  }
  // 并集 Matchs.PB 以外的不应进 sibling；主 id 若在 sibs 里去掉
  const primary = rows?.map(r => String(r?.Matchs?.PB || "").trim()).find(Boolean) || "";
  if (primary)
    sibs.delete(primary);
  const out = {};
  if (sibs.size)
    out._pbSiblingSourceMatchIds = [...sibs];
  if (rot)
    out._pbRotNum = rot;
  return out;
}

function pickPreferredRow(rows) {
  const idRow = rows.find(r => String(r.MergeKey || "").startsWith("match:id:"));
  if (idRow)
    return idRow;
  return [...rows].sort((a, b) => (a.StartTime || 0) - (b.StartTime || 0))[0];
}

/** BO 取自 META 优先级最高的成员（可能非 OB），仅供本阶段 boConflict 用；
 *  落库值由 structure/resolve_structure 覆写成 OB-only */
function pickMetaFromMembers(members, fallbackRow) {
  const ORDER = ["Polymarket", "OB", "RAY", "IA", "PB", "TF"];
  let best = members[0];
  for (const p of ORDER) {
    const hit = members.find(e => e.platform === p);
    if (hit) {
      best = hit;
      break;
    }
  }
  if (!best) {
    return {
      Title: fallbackRow.Title || "",
      StartTime: fallbackRow.StartTime || 0,
      Game: fallbackRow.Game || "",
      GameID: fallbackRow.GameID || "",
      BO: fallbackRow.BO || 0,
    };
  }
  return {
    Title: `${best.homeName} vs ${best.awayName}`,
    StartTime: best.startMs || fallbackRow.StartTime || 0,
    Game: best.Game || fallbackRow.Game || "",
    GameID: best.GameID || fallbackRow.GameID || "",
    BO: best.BO || fallbackRow.BO || 0,
  };
}

/**
 * 4a：把漏网单馆贴到已有场
 */
export function attachOrphans(list, orphans, byKey, stats) {
  const remaining = [];
  for (const orphan of orphans || []) {
    if (!canUseNameOrGb(orphan)) {
      remaining.push(orphan);
      continue;
    }
    const oMeta = {
      namePairs: new Set([namePairFromEntry(orphan)].filter(Boolean)),
      gbPair: (() => {
        const g = enrichGb(orphan);
        return g.homeGb && g.awayGb && g.homeGb !== g.awayGb
          ? { homeGb: g.homeGb, awayGb: g.awayGb }
          : null;
      })(),
      bo: Number(orphan.BO) || 0,
      gameKey: gameKeyOf(orphan),
      startMs: orphan.startMs || 0,
    };

    const candidates = [];
    for (let i = 0; i < list.length; i++) {
      const row = list[i];
      const cMeta = clusterMeta(row, byKey);
      if (!cMeta.gameKey || cMeta.gameKey !== oMeta.gameKey)
        continue;
      if (row.Matchs?.[orphan.platform])
        continue;
      const tol = (row._clusterBasis === "id" || String(row.MergeKey || "").startsWith("match:id:"))
        ? ID_START_TOLERANCE_MS
        : NAME_START_TOLERANCE_MS;
      if (!timeDiffOk(cMeta.startMs, oMeta.startMs, tol))
        continue;
      if (boConflict(cMeta.bo, oMeta.bo))
        continue;
      if (!hitCondition(cMeta, oMeta))
        continue;
      candidates.push({
        i,
        dt: Math.abs((cMeta.startMs || 0) - (oMeta.startMs || 0)),
        preferId: row._clusterBasis === "id" || String(row.MergeKey || "").startsWith("match:id:"),
      });
    }

    if (!candidates.length) {
      remaining.push(orphan);
      continue;
    }
    candidates.sort((a, b) => a.dt - b.dt || (b.preferId - a.preferId));
    const best = candidates[0];
    const second = candidates[1];
    // 两个都已是合法候选时，时间差过近 → 歧义不贴（不限 30min 窗）
    if (second && Math.abs(best.dt - second.dt) < AMBIGUOUS_ATTACH_GAP_MS) {
      stats.skippedAmbiguous += 1;
      remaining.push(orphan);
      continue;
    }

    const target = list[best.i];
    target.Matchs = { ...target.Matchs, [orphan.platform]: orphan.sourceMatchId };
    if (target._clusterBasis === "id" || target._clusterBasis === "name")
      target._clusterBasis = "reconciled";
    target._reconciled = true;
    stats.attached += 1;
  }
  return remaining;
}

function canUseNameOrGb(entry) {
  const np = namePairFromEntry(entry);
  const g = enrichGb(entry);
  if (np)
    return true;
  if (g.homeGb && g.awayGb && g.homeGb !== g.awayGb)
    return true;
  return false;
}

/**
 * 4b：并相似场
 */
export function mergeClustersByName(list, byKey, stats) {
  const n = list.length;
  if (n < 2)
    return list;

  const metas = list.map(row => clusterMeta(row, byKey));
  const parent = Array.from({ length: n }, (_, i) => i);

  function find(i) {
    while (parent[i] !== i) {
      parent[i] = parent[parent[i]];
      i = parent[i];
    }
    return i;
  }
  function union(a, b) {
    const ra = find(a);
    const rb = find(b);
    if (ra !== rb)
      parent[rb] = ra;
  }

  function componentRows(root) {
    const rows = [];
    for (let k = 0; k < n; k++) {
      if (find(k) === root)
        rows.push(list[k]);
    }
    return rows;
  }

  /** @type {{ i: number, j: number, dt: number, preferId: number }[]} */
  const edges = [];
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const a = metas[i];
      const b = metas[j];
      if (a.isSeed || b.isSeed)
        continue;
      if (!a.gameKey || a.gameKey !== b.gameKey)
        continue;
      if (!timeDiffOk(a.startMs, b.startMs, NAME_START_TOLERANCE_MS))
        continue;
      if (boConflict(a.bo, b.bo)) {
        stats.skippedBo += 1;
        continue;
      }
      if (!hitCondition(a, b))
        continue;
      if (matchsConflict(list[i].Matchs, list[j].Matchs)) {
        stats.skippedConflict += 1;
        continue;
      }
      const preferId = (String(list[i].MergeKey || "").startsWith("match:id:") ? 1 : 0)
        + (String(list[j].MergeKey || "").startsWith("match:id:") ? 1 : 0);
      edges.push({
        i,
        j,
        dt: Math.abs((a.startMs || 0) - (b.startMs || 0)),
        preferId,
      });
    }
  }

  // 先合「含 id 键 / 时间更近」的边，降低传递冲突误伤 A+B 的概率
  edges.sort((x, y) => y.preferId - x.preferId || x.dt - y.dt);

  for (const e of edges) {
    const ra = find(e.i);
    const rb = find(e.j);
    if (ra === rb)
      continue;
    const mergedProbe = mergeMatchsUnion([
      ...componentRows(ra),
      ...componentRows(rb),
    ]);
    if (!mergedProbe) {
      stats.skippedConflict += 1;
      continue;
    }
    union(e.i, e.j);
  }

  const groups = new Map();
  for (let i = 0; i < n; i++) {
    const r = find(i);
    if (!groups.has(r))
      groups.set(r, []);
    groups.get(r).push(i);
  }

  const out = [];
  for (const idxs of groups.values()) {
    if (idxs.length === 1) {
      out.push(list[idxs[0]]);
      continue;
    }
    const rows = idxs.map(i => list[i]);
    const unionMatchs = mergeMatchsUnion(rows);
    if (!unionMatchs) {
      stats.skippedConflict += 1;
      for (const row of rows)
        out.push(row);
      continue;
    }
    const preferred = pickPreferredRow(rows);
    const allMembers = [];
    for (const row of rows)
      allMembers.push(...membersOfRow(row, byKey));
    // 也纳入并集里可能尚未在 membersOfRow 的（理论上都在）
    const meta = pickMetaFromMembers(allMembers, preferred);
    const pbMeta = unionPbRotMeta(rows);
    const merged = {
      ...preferred,
      Matchs: unionMatchs,
      Title: meta.Title,
      StartTime: meta.StartTime,
      Game: meta.Game,
      GameID: meta.GameID,
      BO: meta.BO || preferred.BO || 0,
      MergeKey: String(preferred.MergeKey || "").startsWith("match:id:")
        ? preferred.MergeKey
        : (rows.find(r => String(r.MergeKey || "").startsWith("match:id:"))?.MergeKey
          || preferred.MergeKey),
      _clusterBasis: "reconciled",
      _reconciled: true,
      _entryCount: Object.keys(unionMatchs).length,
      ...pbMeta,
    };
    if (!pbMeta._pbSiblingSourceMatchIds)
      delete merged._pbSiblingSourceMatchIds;
    if (!pbMeta._pbRotNum)
      delete merged._pbRotNum;
    stats.merged += 1;
    out.push(merged);
  }

  out.sort((a, b) => (a.StartTime || 0) - (b.StartTime || 0));
  return out;
}

/**
 * @param {object[]} list 已有簇
 * @param {object[]} allEntries 全部平台条目
 * @returns {{ list: object[], stats: object }}
 */
export function reconcileClustersByName(list, allEntries) {
  const stats = {
    attached: 0,
    merged: 0,
    skippedConflict: 0,
    skippedAmbiguous: 0,
    skippedBo: 0,
  };
  const byKey = entryIndex(allEntries);
  const inCluster = new Set();
  for (const row of list || []) {
    for (const [p, sid] of Object.entries(row.Matchs || {}))
      inCluster.add(`${p}:${sid}`);
  }
  const orphans = (allEntries || []).filter(e => !inCluster.has(e.rowKey));

  let next = (list || []).map(r => ({ ...r, Matchs: { ...r.Matchs } }));
  attachOrphans(next, orphans, byKey, stats);
  // 刷新索引中的 members（Matchs 已变）
  next = mergeClustersByName(next, byKey, stats);

  return { list: next, stats };
}

/**
 * client_matches ID 分配：复用 @changmen/match-identity/ids（非 merge）。
 * dry-run 时不 insert stub，仅复用已有 id，否则分配临时负 ID。
 */
import {
  assignMatchIds,
  findLinkedClientIdFromMatchs,
  findReuseIdByMatchsSuperset,
  findReuseIdByPlatformOverlap,
  matchsSignature,
  resolveClientMatchIds,
} from "@changmen/match-identity/ids/client_match_ids.js";

/** M3：已结束行不参与身份复用 */
export function isEndedClientMatchRow(row) {
  const ended = row?.ended_at ?? row?.endedAt;
  return ended != null && ended !== "";
}

function activeClientMatchRows(rows) {
  return (rows || []).filter(r => !isEndedClientMatchRow(r));
}

function reuseIdSync(row, existingActive, matches, byMergeKey, byMatchsSig, batchAssigned, existingIdKeyIndex, activeIds) {
  const mergeKey = row.MergeKey ? String(row.MergeKey) : null;
  let id = Number(row.ID) || 0;
  // M4：seed 可能带上 ended id；非活跃正 ID 一律丢弃
  if (id > 0 && activeIds && !activeIds.has(id))
    id = 0;

  if (!id && mergeKey?.startsWith("match:id:") && existingIdKeyIndex?.has(mergeKey))
    id = existingIdKeyIndex.get(mergeKey) || 0;
  if (!id && mergeKey)
    id = batchAssigned.get(mergeKey) || byMergeKey.get(mergeKey) || 0;
  if (!id && matches) {
    const linked = findLinkedClientIdFromMatchs(row.Matchs, matches, {
      mergeKey,
      existingIdKeyIndex,
    });
    // M3：链接到 ended CM 的 match_id 忽略
    if (linked && activeIds?.has(linked))
      id = linked;
  }
  if (!id) {
    const sig = matchsSignature(row.Matchs);
    if (sig)
      id = byMatchsSig.get(sig) || 0;
  }
  if (!id)
    id = findReuseIdByMatchsSuperset(existingActive, row.Matchs) || 0;
  if (!id)
    id = findReuseIdByPlatformOverlap(existingActive, row.Matchs) || 0;
  return { id, mergeKey };
}

/**
 * dry-run：不写 stub；新场用临时负 ID（仅内存对照）。
 */
export function resolveIdsDryRun(builtRows, {
  matches,
  existingClientRows = [],
  existingIdKeyIndex,
} = {}) {
  const activeExisting = activeClientMatchRows(existingClientRows);
  const byMergeKey = new Map();
  const byMatchsSig = new Map();
  const activeIds = new Set();
  for (const row of activeExisting) {
    const id = Number(row.id);
    activeIds.add(id);
    if (row.merge_key)
      byMergeKey.set(String(row.merge_key), id);
    const sig = matchsSignature(row.matchs || row.Matchs);
    if (sig && !byMatchsSig.has(sig))
      byMatchsSig.set(sig, id);
  }
  if (existingIdKeyIndex) {
    for (const [key, id] of existingIdKeyIndex) {
      const n = Number(id);
      if (Number.isFinite(n) && n > 0)
        activeIds.add(n);
      if (!byMergeKey.has(key))
        byMergeKey.set(key, id);
    }
  }
  const batchAssigned = new Map();
  let tempSeq = -1;
  const out = [];
  for (const row of builtRows || []) {
    const { id: reuse, mergeKey } = reuseIdSync(
      row,
      activeExisting,
      matches,
      byMergeKey,
      byMatchsSig,
      batchAssigned,
      existingIdKeyIndex,
      activeIds,
    );
    let id = reuse;
    if (!id) {
      id = tempSeq;
      tempSeq -= 1;
    }
    if (mergeKey)
      batchAssigned.set(mergeKey, id);
    const sig = matchsSignature(row.Matchs);
    if (sig)
      byMatchsSig.set(sig, id);
    out.push(assignMatchIds(row, id));
  }
  return out;
}

/**
 * 写库路径：完整 resolveClientMatchIds（可 insert stub）。
 */
export async function resolveIdsForWrite(adapter, builtRows, { matches, existingIdKeyIndex } = {}) {
  return resolveClientMatchIds(adapter, builtRows, { matches, existingIdKeyIndex });
}

/**
 * 投影后不变式检查（测试与 dry-run 自检共用）。
 */
import { lookupGbTeamIdByPlatform } from "@changmen/match-identity/teams/team_key.js";
import { findPlatformMatch } from "./sides/orientation_lock.js";

export function checkHomeSlotConsistency(row, nativeByPlatformMap = {}) {
  const violations = [];
  const reverse = new Set(row.Reverse || []);
  for (const bet of row.Bets || []) {
    const mapNum = Number(bet.Map) || 0;
    for (const [platform, src] of Object.entries(bet.Sources || {})) {
      const key = `${platform}:${mapNum}`;
      const raw = nativeByPlatformMap[key];
      if (!raw) {
        const map0 = (row.Bets || []).find(b => (Number(b.Map) || 0) === 0)?.Sources?.[platform];
        if (mapNum !== 0 && map0
          && String(src.HomeID) === String(map0.HomeID)
          && String(src.AwayID) === String(map0.AwayID)) {
          continue;
        }
        // 决胜局拷贝后 Map0 可能已剥除该馆（PM）：对照 Map0 原生盘 + Reverse
        const map0Native = nativeByPlatformMap[`${platform}:0`];
        if (mapNum !== 0 && map0Native) {
          const shouldSwap = reverse.has(platform);
          const expectHome = shouldSwap ? String(map0Native.AwayID ?? "") : String(map0Native.HomeID ?? "");
          const expectAway = shouldSwap ? String(map0Native.HomeID ?? "") : String(map0Native.AwayID ?? "");
          if (String(src.HomeID ?? "") === expectHome && String(src.AwayID ?? "") === expectAway)
            continue;
        }
        violations.push(`#${row.ID} ${key}: missing native for I1 check`);
        continue;
      }
      const shouldSwap = reverse.has(platform);
      const expectHome = shouldSwap ? String(raw.AwayID ?? "") : String(raw.HomeID ?? "");
      const expectAway = shouldSwap ? String(raw.HomeID ?? "") : String(raw.AwayID ?? "");
      if (String(src.HomeID ?? "") !== expectHome || String(src.AwayID ?? "") !== expectAway) {
        violations.push(
          `#${row.ID} ${key}: Home/Away mismatch reverse=${shouldSwap}`
          + ` got=${src.HomeID}/${src.AwayID} expect=${expectHome}/${expectAway}`,
        );
      }
    }
  }
  return { ok: violations.length === 0, violations };
}

export function checkReverseSubsetOfSources(row) {
  const platforms = new Set();
  for (const bet of row.Bets || []) {
    for (const p of Object.keys(bet.Sources || {}))
      platforms.add(p);
  }
  const violations = [];
  for (const p of row.Reverse || []) {
    if (!platforms.has(p))
      violations.push(`#${row.ID}: Reverse has ${p} but no Sources`);
  }
  return { ok: violations.length === 0, violations };
}

/**
 * Bets 的局段必须来自赛制层。shape 只会删行不会加行，故用子集而非相等。
 * 触发即说明有人绕开 resolveMatchStructure 造了 Bet 行。
 */
export function checkBetsWithinPeriods(row) {
  const periods = row?._periods;
  if (!Array.isArray(periods))
    return { ok: true, violations: [], skipped: true };
  const allowed = new Set(periods.map(p => Number(p) || 0));
  const violations = [];
  for (const bet of row.Bets || []) {
    const mapNum = Number(bet.Map) || 0;
    if (!allowed.has(mapNum))
      violations.push(`#${row.ID}: Map=${mapNum} not in periods [${periods.join(",")}]`);
  }
  return { ok: violations.length === 0, violations };
}

export function resolveOidToGb(platform, oid, raw, pm) {
  if (!oid || !raw || !pm)
    return null;
  const o = String(oid);
  const homeVenueId = String(pm.HomeID ?? pm.home_id ?? pm.SourceHomeID ?? "").trim();
  const awayVenueId = String(pm.AwayID ?? pm.away_id ?? pm.SourceAwayID ?? "").trim();
  if (o === String(raw.HomeID ?? "")) {
    return homeVenueId ? String(lookupGbTeamIdByPlatform(platform, homeVenueId) || "") || null : null;
  }
  if (o === String(raw.AwayID ?? "")) {
    return awayVenueId ? String(lookupGbTeamIdByPlatform(platform, awayVenueId) || "") || null : null;
  }
  return null;
}

export function checkNotSamePhysicalSide(row, {
  platformA,
  slotA,
  platformB,
  slotB,
  nativeByPlatformMap,
  matches,
  map = 0,
} = {}) {
  const bet = (row.Bets || []).find(b => (Number(b.Map) || 0) === map);
  const srcA = bet?.Sources?.[platformA];
  const srcB = bet?.Sources?.[platformB];
  if (!srcA || !srcB)
    return { ok: true, violations: [], skipped: true };

  const rawA = nativeByPlatformMap[`${platformA}:${map}`];
  const rawB = nativeByPlatformMap[`${platformB}:${map}`];
  const pmA = findPlatformMatch(matches, platformA, row.Matchs?.[platformA]);
  const pmB = findPlatformMatch(matches, platformB, row.Matchs?.[platformB]);
  if (!rawA || !rawB || !pmA || !pmB)
    return { ok: true, violations: [], skipped: true };

  const oidA = String(srcA[`${slotA}ID`] ?? "");
  const oidB = String(srcB[`${slotB}ID`] ?? "");
  const gbA = resolveOidToGb(platformA, oidA, rawA, pmA);
  const gbB = resolveOidToGb(platformB, oidB, rawB, pmB);

  const violations = [];
  if (gbA && gbB && gbA === gbB) {
    violations.push(
      `#${row.ID}: same gb ${gbA} via ${platformA}.${slotA}=${oidA} + ${platformB}.${slotB}=${oidB}`,
    );
  }
  return { ok: violations.length === 0, violations, gbA, gbB };
}

export function checkSourcesMatchLockTeams(row, {
  matches,
  nativeByPlatformMap,
  map = 0,
} = {}) {
  const homeGb = String(row.HomeGbTeamId || "");
  const awayGb = String(row.AwayGbTeamId || "");
  if (!homeGb || !awayGb)
    return { ok: true, violations: [], skipped: true };

  const bet = (row.Bets || []).find(b => (Number(b.Map) || 0) === map);
  const violations = [];
  for (const [platform, src] of Object.entries(bet?.Sources || {})) {
    const raw = nativeByPlatformMap[`${platform}:${map}`];
    const pm = findPlatformMatch(matches, platform, row.Matchs?.[platform]);
    if (!raw || !pm)
      continue;
    const h = resolveOidToGb(platform, src.HomeID, raw, pm);
    const a = resolveOidToGb(platform, src.AwayID, raw, pm);
    if (h && h !== homeGb)
      violations.push(`#${row.ID} ${platform}: Home slot gb=${h} ≠ lock home=${homeGb}`);
    if (a && a !== awayGb)
      violations.push(`#${row.ID} ${platform}: Away slot gb=${a} ≠ lock away=${awayGb}`);
  }
  return { ok: violations.length === 0, violations };
}

export function checkUnlockedEmpty(row) {
  const violations = [];
  if (!row.HomeGbTeamId && !row.AwayGbTeamId) {
    if (Array.isArray(row.Reverse) && row.Reverse.length)
      violations.push(`#${row.ID}: unlocked but Reverse nonempty`);
    for (const bet of row.Bets || []) {
      if (Object.keys(bet.Sources || {}).length)
        violations.push(`#${row.ID}: unlocked but Sources nonempty map=${bet.Map}`);
    }
  }
  return { ok: violations.length === 0, violations };
}

/**
 * 读取合场输入快照；挂 team plugin；可选 autoRegister。
 *
 * clientRows = 全量（含 home_gb / pm_sport），供 sticky + ended
 * alignClientRows 与 clientRows 来自同一次含 ended 的版本化读取。
 */
import * as db from "@changmen/db";
import { setTeamPlugin } from "@changmen/match-identity/teams/team_key.js";

let _pluginReady = null;
/** @type {string|null} */
let _pluginMapsRevision = null;

export function normalizeMatchesShape(raw) {
  const out = {};
  for (const [provider, block] of Object.entries(raw || {})) {
    if (!block)
      continue;
    if (Array.isArray(block)) {
      out[provider] = {};
      for (const m of block) {
        if (m?.SourceMatchID != null)
          out[provider][String(m.SourceMatchID)] = m;
      }
    }
    else if (typeof block === "object") {
      out[provider] = block;
    }
  }
  return out;
}

export async function ensureTeamPlugin() {
  let revision = null;
  try {
    if (typeof db.fetchTeamMapsRevision === "function")
      revision = await db.fetchTeamMapsRevision();
  }
  catch (err) {
    console.warn("[match-composer] fetchTeamMapsRevision:", err.message);
  }

  if (_pluginReady && revision != null && revision === _pluginMapsRevision)
    return _pluginReady;
  if (_pluginReady && revision == null)
    return _pluginReady;

  if (_pluginReady && revision != null && revision !== _pluginMapsRevision) {
    console.log(
      `[match-composer] team-resolver 映射变更 ${_pluginMapsRevision} → ${revision}，重载`,
    );
  }

  _pluginMapsRevision = revision;
  _pluginReady = (async () => {
    try {
      const { loadAndCreatePlugin } = await import("@changmen/team-resolver/team_db.js");
      const plugin = await loadAndCreatePlugin();
      setTeamPlugin(plugin);
    }
    catch (err) {
      console.warn("[match-composer] team-resolver 加载失败:", err.message);
      _pluginMapsRevision = null;
    }
  })();
  return _pluginReady;
}

export function resetTeamPluginCache() {
  _pluginReady = null;
  _pluginMapsRevision = null;
}

function enrichMatchesRawWithDbBindings(matchesRaw, bindingsByClientId) {
  if (!matchesRaw || !bindingsByClientId?.size)
    return matchesRaw;
  for (const [cmId, bindings] of bindingsByClientId.entries()) {
    const list = Array.isArray(bindings) ? bindings : [];
    for (const b of list) {
      const plat = b.platform || b.Platform;
      const sid = String(b.source_match_id ?? b.SourceMatchID ?? "");
      if (!plat || !sid)
        continue;
      const rows = matchesRaw[plat];
      if (!Array.isArray(rows))
        continue;
      const hit = rows.find(m => String(m.SourceMatchID) === sid);
      if (hit) {
        hit.ClientMatchId = Number(cmId);
        hit.client_match_id = Number(cmId);
        hit.match_id = Number(cmId);
      }
    }
  }
  return matchesRaw;
}

/**
 * @returns {Promise<object>}
 */
export async function loadSnapshot({ registerTeams = true } = {}) {
  await db.initLastWrittenIds?.();

  let matchesRaw = {};
  let bets = {};
  let timers = {};
  /** @type {object[]} 全量：sticky / ended / project existing */
  let clientRows = [];
  /** @type {object[]} align 挂靠专用（可等于 clientRows） */
  let alignClientRows = [];
  let clientMatchSnapshotVersion = null;
  let teamReg = null;
  let nameSync = null;

  if (db.isMatcherStoreReady()) {
    matchesRaw = (await db.fetchPlatformMatches()) || {};
    bets = (await db.fetchPlatformBets()) || {};
    timers = (await db.fetchLiveTimers()) || {};
    const lifecycleSnapshot = await db.fetchClientMatchesAll({ snapshot: true });
    if (!lifecycleSnapshot)
      throw new Error("client_matches lifecycle snapshot unavailable; abort compose");
    clientRows = lifecycleSnapshot.rows;
    alignClientRows = clientRows;
    clientMatchSnapshotVersion = lifecycleSnapshot.version;
  }

  const platformBindingsByClientId = db.isMatcherStoreReady()
    ? await db.fetchAllPlatformMatchBindings()
    : null;
  if (platformBindingsByClientId?.size)
    enrichMatchesRawWithDbBindings(matchesRaw, platformBindingsByClientId);

  if (registerTeams && db.isMatcherStoreReady()) {
    try {
      const { autoRegisterTeams } = await import(
        "../../ops/auto_register_teams.js"
      );
      teamReg = await autoRegisterTeams(matchesRaw);
    }
    catch (err) {
      console.warn("[match-composer] autoRegisterTeams:", err.message);
    }
    try {
      if (typeof db.syncCanonicalTeamNamesFromOb === "function")
        nameSync = await db.syncCanonicalTeamNamesFromOb();
    }
    catch (err) {
      console.warn("[match-composer] syncCanonicalTeamNamesFromOb:", err.message);
    }
    if ((teamReg?.registered > 0) || (nameSync?.updated > 0))
      resetTeamPluginCache();
  }
  await ensureTeamPlugin();

  const matches = normalizeMatchesShape(matchesRaw);
  const platformOverrides = db.isMatcherStoreReady()
    ? await db.fetchClientMatchPlatformOverrides()
    : {};

  return {
    matches,
    matchesRaw,
    bets,
    timers,
    clientRows,
    alignClientRows,
    clientMatchSnapshotVersion,
    clientMatchSnapshotScope: "all",
    platformOverrides,
    platformBindingsByClientId,
    teamReg,
    nameSync,
  };
}

