/**
 * PB 同系列多 event → 合场只占一个 Matchs.PB 槽（交易主键仍是 event.id）。
 * 有 RotNum：同 rot 归组（changmen 扩展上报）。
 * 无 RotNum（A8）：live 图 + 未开图残留仍并成一场，主盘选滚球账本。
 */
import { normalizeTeam } from "@changmen/match-identity/teams/team_key.js";
import { collectPlatformEntries } from "./platform_entry.js";
import { betBucketKey } from "./native_bets.js";

export function readRotNum(pmOrEntry) {
  const raw = pmOrEntry?.rotNum
    ?? pmOrEntry?.RotNum
    ?? pmOrEntry?.rot_num
    ?? pmOrEntry?.nativeRow?.RotNum
    ?? pmOrEntry?.nativeRow?.rotNum
    ?? pmOrEntry?.nativeRow?.rot_num;
  const s = raw != null ? String(raw).trim() : "";
  return s;
}

export function isPbKillsName(home, away) {
  return /\(\s*Kills\s*\)/i.test(`${home || ""} ${away || ""}`);
}

function betRowsFor(bets, platform, sourceMatchId) {
  const block = bets?.[betBucketKey(platform, sourceMatchId)]
    || bets?.[`${platform}:${String(sourceMatchId)}`];
  if (!block)
    return [];
  if (Array.isArray(block))
    return block;
  return Array.isArray(block.bets) ? block.bets : [];
}

export function mapsFromBets(bets, platform, sourceMatchId) {
  const maps = new Set();
  for (const b of betRowsFor(bets, platform, sourceMatchId)) {
    const m = Number(b.Map ?? b.map);
    if (Number.isFinite(m))
      maps.add(m);
  }
  return maps;
}

function liveFlag(pm) {
  const raw = pm?.IsLive ?? pm?.isLive ?? pm?.live ?? pm?.is_live;
  if (raw === true || raw === 1 || raw === "1")
    return true;
  if (typeof raw === "string" && raw.trim().toLowerCase() === "true")
    return true;
  return false;
}

export function isPbLiveLike(entry, bets = {}) {
  const pm = entry?.nativeRow && typeof entry.nativeRow === "object" ? entry.nativeRow : entry;
  if (liveFlag(pm))
    return true;
  return mapsFromBets(bets, entry.platform || "PB", entry.sourceMatchId).has(0);
}

function teamPairKey(entry) {
  const a = String(entry.homeN || normalizeTeam(entry.homeName || "") || "").trim();
  const b = String(entry.awayN || normalizeTeam(entry.awayName || "") || "").trim();
  if (!a || !b)
    return "";
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

function gbPairKey(entry) {
  const a = String(entry.homeGb || "").trim();
  const b = String(entry.awayGb || "").trim();
  if (!a || !b || a === b)
    return "";
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

function teamPairFromPm(pm) {
  const a = normalizeTeam(String(pm?.Home ?? pm?.home ?? "").trim());
  const b = normalizeTeam(String(pm?.Away ?? pm?.away ?? "").trim());
  if (!a || !b)
    return "";
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

/** 同 rot 组是否撞号（异队）。半边有 gb、半边仅队名不同 → 仍撞号。 */
export function isPbRotGroupCollision(group) {
  const namePairs = new Set((group || []).map(teamPairKey).filter(Boolean));
  const gbPairs = new Set((group || []).map(gbPairKey).filter(Boolean));
  if (gbPairs.size > 1)
    return true;
  if (namePairs.size <= 1)
    return false;
  // 多名对：仅当全员有 gb 且同属一个 gb 对（队名异写）才合并
  const allHaveGb = (group || []).every(e => Boolean(gbPairKey(e)));
  return !(allHaveGb && gbPairs.size === 1);
}

function isUnstartedMapsOnly(entry, bets = {}) {
  if (isPbLiveLike(entry, bets))
    return false;
  const maps = mapsFromBets(bets, entry.platform || "PB", entry.sourceMatchId);
  if (!maps.size)
    return true;
  return ![...maps].some(m => m === 0);
}

function stickySetFromClientRows(existingClientRows) {
  const ids = new Set();
  for (const cm of existingClientRows || []) {
    const ended = cm?.ended_at ?? cm?.endedAt;
    if (ended != null && ended !== "")
      continue;
    const matchs = cm.matchs || cm.Matchs || {};
    const sid = matchs.PB;
    if (sid != null && sid !== "")
      ids.add(String(sid));
  }
  return ids;
}

/**
 * 主 event：粘性 → 升主盘（未开图 sticky + 同组 live）→ live/map0 → 稳定 id。
 */
export function pickPrimaryPbEntry(entries, {
  bets = {},
  stickySourceMatchIds = new Set(),
} = {}) {
  if (!entries?.length)
    return null;
  if (entries.length === 1)
    return entries[0];

  const sticky = entries.filter(e => stickySourceMatchIds.has(String(e.sourceMatchId)));
  const liveLike = entries.filter(e => isPbLiveLike(e, bets));

  if (sticky.length === 1) {
    const s = sticky[0];
    if (isUnstartedMapsOnly(s, bets)) {
      const live = liveLike.find(e => e.sourceMatchId !== s.sourceMatchId);
      if (live)
        return live;
    }
    return s;
  }
  if (sticky.length > 1) {
    const stickyLive = sticky.filter(e => isPbLiveLike(e, bets));
    if (stickyLive.length) {
      return [...stickyLive].sort((a, b) =>
        String(a.sourceMatchId).localeCompare(String(b.sourceMatchId)))[0];
    }
    return [...sticky].sort((a, b) =>
      String(a.sourceMatchId).localeCompare(String(b.sourceMatchId)))[0];
  }

  if (liveLike.length === 1)
    return liveLike[0];
  if (liveLike.length > 1) {
    return [...liveLike].sort((a, b) =>
      String(a.sourceMatchId).localeCompare(String(b.sourceMatchId)))[0];
  }

  return [...entries].sort((a, b) =>
    String(a.sourceMatchId).localeCompare(String(b.sourceMatchId)))[0];
}

export function pickPrimaryPbSourceId(sourceIds, matches, opts = {}) {
  const want = [...new Set((sourceIds || []).map(String).filter(Boolean))];
  if (!want.length)
    return "";
  if (want.length === 1)
    return want[0];
  const bucket = matches?.PB || {};
  const subset = {};
  for (const sid of want) {
    const pm = bucket[sid]
      || Object.values(bucket).find(m => String(m?.SourceMatchID) === sid);
    if (pm)
      subset[sid] = pm;
  }
  const entries = collectPlatformEntries({ PB: subset });
  const primary = pickPrimaryPbEntry(entries, opts);
  return primary?.sourceMatchId || want[want.length - 1];
}

function findPbMatch(matches, sourceMatchId) {
  const sid = String(sourceMatchId);
  const bucket = matches?.PB;
  if (!bucket || typeof bucket !== "object")
    return null;
  if (bucket[sid])
    return bucket[sid];
  return Object.values(bucket).find(m => String(m?.SourceMatchID) === sid) || null;
}

function sourceGameKey(pm) {
  return String(pm?.SourceGameID ?? pm?.GameID ?? "").trim();
}

/** 与 primary 同 rot 的其它 PB event.id（撞号 / Kills 排除） */
export function listPbRotNumSiblings(matches, primarySourceMatchId) {
  const primary = findPbMatch(matches, primarySourceMatchId);
  if (!primary)
    return [];
  const rot = readRotNum(primary);
  if (!rot)
    return [];
  if (isPbKillsName(primary.Home ?? primary.home, primary.Away ?? primary.away))
    return [];
  const game = sourceGameKey(primary);
  const pair = teamPairFromPm(primary);
  // 主场次队名不全则无法校验同队，不扩 sibling（防空名放行）
  if (!pair)
    return [];
  const out = [];
  for (const pm of Object.values(matches?.PB || {})) {
    const sid = String(pm?.SourceMatchID ?? "");
    if (!sid || sid === String(primarySourceMatchId))
      continue;
    if (readRotNum(pm) !== rot)
      continue;
    if (isPbKillsName(pm.Home ?? pm.home, pm.Away ?? pm.away))
      continue;
    const g = sourceGameKey(pm);
    if (game && g && game !== g)
      continue;
    const otherPair = teamPairFromPm(pm);
    if (!otherPair || otherPair !== pair)
      continue;
    out.push(sid);
  }
  return out;
}

/**
 * B1 投影用：Matchs.PB（主）+ 簇内 sibling + 同 rotNum 的其它 event.id。
 * 不含 Kills；不改 Matchs.PB。
 */
export function listPbEventIdsForProjection(row, matches) {
  const primary = String(row?.Matchs?.PB ?? row?.matchs?.PB ?? "").trim();
  if (!primary)
    return [];
  const out = new Set([primary]);
  for (const sid of row?._pbSiblingSourceMatchIds || []) {
    const s = String(sid || "").trim();
    if (s)
      out.add(s);
  }
  for (const sid of listPbRotNumSiblings(matches || {}, primary))
    out.add(sid);
  return [...out];
}

export function indexEntriesWithPbAliases(entries) {
  const byKey = new Map();
  for (const e of entries || []) {
    byKey.set(e.rowKey, e);
    for (const sid of e._pbSiblingSourceMatchIds || [])
      byKey.set(`PB:${sid}`, e);
  }
  return byKey;
}

function groupKey(entry) {
  return `${entry.GameID || entry.gameCode || ""}:${readRotNum(entry)}`;
}

function mergePbGroup(group, { bets, stickySourceMatchIds }) {
  const primary = pickPrimaryPbEntry(group, { bets, stickySourceMatchIds });
  const siblings = group
    .filter(e => e.sourceMatchId !== primary.sourceMatchId)
    .map(e => String(e.sourceMatchId));
  primary._pbSiblingSourceMatchIds = siblings;
  primary._pbRotNum = readRotNum(primary);
  // 用组内最早开赛时间聚类，避免 live event.time 偏离系列赛开打时间导致拆场
  const times = group.map(e => Number(e.startMs) || 0).filter(n => n > 0);
  if (times.length)
    primary.startMs = Math.min(...times);
  if (primary.clientMatchId == null) {
    const linked = group.find(e => e.clientMatchId != null && Number.isFinite(Number(e.clientMatchId)));
    if (linked)
      primary.clientMatchId = linked.clientMatchId;
  }
  return primary;
}

/**
 * A8 不上报 RotNum。开赛后 live event 新插入、赛前 event 仍留在库里，
 * 合场每馆只有一个 PB 槽：必须把滚球账本接到这场上，否则 UI 用赛前 HomeID 对 fo 全是锁盘。
 * 指纹：同一 game+队对，恰好一场 live-like + 其余未开图（无 map0）。
 * 只改 Matchs.PB 主盘选举；不把 sibling 交给投影层（那是 RotNum 拼未开图，属 changmen 扩展）。
 */
function collapsePbUnkeyedLivePrematch(entries, { bets, stickySourceMatchIds }) {
  const rest = [];
  const pb = [];
  for (const e of entries || []) {
    if (
      e.platform === "PB"
      && !readRotNum(e)
      && !isPbKillsName(e.homeName, e.awayName)
    ) {
      pb.push(e);
    }
    else {
      rest.push(e);
    }
  }

  const groups = new Map();
  for (const e of pb) {
    const pair = teamPairKey(e);
    if (!pair) {
      rest.push(e);
      continue;
    }
    const key = `${e.GameID || e.gameCode || ""}:${pair}`;
    if (!groups.has(key))
      groups.set(key, []);
    groups.get(key).push(e);
  }

  let skippedCollisions = 0;
  let collapsedGroups = 0;
  const collapsed = [];

  for (const group of groups.values()) {
    if (group.length === 1) {
      collapsed.push(group[0]);
      continue;
    }
    if (isPbRotGroupCollision(group)) {
      skippedCollisions += 1;
      collapsed.push(...group);
      continue;
    }
    const liveLike = group.filter(e => isPbLiveLike(e, bets));
    const unstarted = group.filter(e => isUnstartedMapsOnly(e, bets));
    if (liveLike.length !== 1 || unstarted.length < 1) {
      collapsed.push(...group);
      continue;
    }
    collapsed.push(mergePbGroup(group, { bets, stickySourceMatchIds }));
    collapsedGroups += 1;
  }

  return {
    entries: [...rest, ...collapsed],
    skippedCollisions,
    collapsedGroups,
  };
}

/**
 * @returns {{ entries: object[], skippedCollisions: number, collapsedGroups: number }}
 */
export function collapsePbEntriesByRotNum(entries, {
  bets = {},
  existingClientRows = [],
  enabled = true,
} = {}) {
  if (!enabled)
    return { entries: entries || [], skippedCollisions: 0, collapsedGroups: 0 };

  const stickySourceMatchIds = stickySetFromClientRows(existingClientRows);
  const rest = [];
  const pb = [];
  for (const e of entries || []) {
    if (
      e.platform === "PB"
      && readRotNum(e)
      && !isPbKillsName(e.homeName, e.awayName)
    ) {
      pb.push(e);
    }
    else {
      rest.push(e);
    }
  }

  const groups = new Map();
  for (const e of pb) {
    const key = groupKey(e);
    if (!groups.has(key))
      groups.set(key, []);
    groups.get(key).push(e);
  }

  let skippedCollisions = 0;
  let collapsedGroups = 0;
  const collapsed = [];

  for (const group of groups.values()) {
    if (group.length === 1) {
      collapsed.push(group[0]);
      continue;
    }
    if (isPbRotGroupCollision(group)) {
      skippedCollisions += 1;
      console.warn(
        `[match-composer] PB rotNum collision rot=${readRotNum(group[0])} `
        + `ids=${group.map(e => e.sourceMatchId).join(",")}`,
      );
      collapsed.push(...group);
      continue;
    }

    collapsed.push(mergePbGroup(group, { bets, stickySourceMatchIds }));
    collapsedGroups += 1;
  }

  const unkeyed = collapsePbUnkeyedLivePrematch([...rest, ...collapsed], {
    bets,
    stickySourceMatchIds,
  });
  skippedCollisions += unkeyed.skippedCollisions;
  collapsedGroups += unkeyed.collapsedGroups;

  if (collapsedGroups || skippedCollisions) {
    console.log(
      `[match-composer] PB rotNum collapse groups=${collapsedGroups} collisions=${skippedCollisions}`,
    );
  }

  return {
    entries: unkeyed.entries,
    skippedCollisions,
    collapsedGroups,
  };
}

/**
 * 将 platform_matches 归一成可聚类条目。
 */
import {
  canonicalMatchKeyByIdOnly,
  canonicalMatchKeyByName,
  lookupGbTeamIdByPlatform,
  normalizeTeam,
} from "@changmen/match-identity/teams/team_key.js";
import { isPlaceholderTeamName } from "@changmen/match-identity/teams/match_utils.js";
import {
  getGameCodeForPlatformId,
  resolveClientGame,
} from "@changmen/shared/catalog/game_catalog";
import { resolvePlatformTeamId } from "@changmen/shared/catalog/pb_team_platform_id";
import { normalizeEpochMs } from "../util/time.js";

export function collectPlatformEntries(matches) {
  const entries = [];
  for (const [platform, bucket] of Object.entries(matches || {})) {
    if (!bucket || typeof bucket !== "object")
      continue;
    for (const pm of Object.values(bucket)) {
      if (!pm?.SourceMatchID)
        continue;
      const sourceMatchId = String(pm.SourceMatchID);
      const sourceGameId = pm.SourceGameID ?? pm.GameID;
      const gameCode = getGameCodeForPlatformId(platform, sourceGameId);
      // 与 match_merge 一致：用 A8 规范 GameID，勿用馆原生 SourceGameID（否则跨馆键永不碰撞）
      const { Game, GameID: a8GameId } = resolveClientGame(platform, sourceGameId);
      const mergeGameId = a8GameId != null && a8GameId !== 0
        ? String(a8GameId)
        : String(gameCode || sourceGameId || "");
      const homeIdRaw = String(pm.HomeID ?? pm.home_id ?? pm.SourceHomeID ?? "").trim();
      const awayIdRaw = String(pm.AwayID ?? pm.away_id ?? pm.SourceAwayID ?? "").trim();
      const homeId = resolvePlatformTeamId(platform, homeIdRaw, sourceGameId, gameCode);
      const awayId = resolvePlatformTeamId(platform, awayIdRaw, sourceGameId, gameCode);
      const homeName = String(pm.Home ?? pm.home ?? "").trim();
      const awayName = String(pm.Away ?? pm.away ?? "").trim();
      const homeGb = homeId ? String(lookupGbTeamIdByPlatform(platform, homeId) || "").trim() || null : null;
      const awayGb = awayId ? String(lookupGbTeamIdByPlatform(platform, awayId) || "").trim() || null : null;
      const homeN = normalizeTeam(homeName);
      const awayN = normalizeTeam(awayName);
      const startMs = normalizeEpochMs(pm.StartTime);
      const linkedId = pm.ClientMatchId ?? pm.client_match_id ?? pm.match_id;
      const rotRaw = pm.RotNum ?? pm.rotNum ?? pm.rot_num;
      const rotNum = rotRaw != null ? String(rotRaw).trim() : "";
      entries.push({
        platform,
        sourceMatchId,
        homeId,
        awayId,
        homeName,
        awayName,
        homeGb,
        awayGb,
        homeN,
        awayN,
        startMs,
        gameCode,
        Game,
        GameID: mergeGameId,
        BO: Number(pm.BO) || 0,
        rotNum,
        nativeRow: pm,
        rowKey: `${platform}:${sourceMatchId}`,
        clientMatchId: linkedId != null && linkedId !== "" ? Number(linkedId) : null,
      });
    }
  }
  return entries;
}

export function canUseIdKey(entry) {
  if (!entry.homeGb || !entry.awayGb || entry.homeGb === entry.awayGb)
    return false;
  if (!entry.homeN || !entry.awayN)
    return false;
  if (isPlaceholderTeamName(entry.homeN) || isPlaceholderTeamName(entry.awayN))
    return false;
  return true;
}

export function canUseNameKey(entry) {
  if (!entry.homeN || !entry.awayN)
    return false;
  if (isPlaceholderTeamName(entry.homeN) || isPlaceholderTeamName(entry.awayN))
    return false;
  return true;
}

/** MergeKey 格式：match:id:GameID:gb:gb */
export function pairKeyId(entry) {
  const ck = canonicalMatchKeyByIdOnly(
    entry.GameID,
    entry.homeName,
    entry.awayName,
    entry.gameCode,
    { provider: entry.platform, homeId: entry.homeId, awayId: entry.awayId },
  );
  if (ck?.mergeKey)
    return ck.mergeKey;
  if (!entry.homeGb || !entry.awayGb)
    return null;
  const a = entry.homeGb;
  const b = entry.awayGb;
  const [x, y] = a < b ? [a, b] : [b, a];
  return `match:id:${entry.GameID || ""}:${x}:${y}`;
}

/** 与 legacy 一致：match:name:GameID:name:name */
export function pairKeyName(entry) {
  const ck = canonicalMatchKeyByName(entry.GameID, entry.homeName, entry.awayName);
  if (ck?.mergeKey)
    return ck.mergeKey;
  if (!entry.homeN || !entry.awayN)
    return null;
  const a = entry.homeN;
  const b = entry.awayN;
  const [x, y] = a < b ? [a, b] : [b, a];
  return `match:name:${entry.GameID || entry.gameCode || ""}:${x}:${y}`;
}

/**
 * 展示成形：trim / strip / 命名 / 排序。
 *
 * Round / BO / periods 由 structure/resolve_structure.js 在投影前定型，此处只读。
 */
import { parseTitleTeams } from "@changmen/match-identity/teams/match_utils.js";
import { findPlatformMatch } from "../sides/orientation_lock.js";

const MIN_PLATFORMS = 2;

export function preserveInitialOddsFromSources(bet) {
  if (!bet)
    return;
  let home = Number(bet.InitialHomeOdds) || 0;
  let away = Number(bet.InitialAwayOdds) || 0;
  for (const src of Object.values(bet.Sources || {})) {
    if (!src)
      continue;
    home = Math.max(home, Number(src.HomeOdds) || 0);
    away = Math.max(away, Number(src.AwayOdds) || 0);
  }
  if (home > 0)
    bet.InitialHomeOdds = home;
  if (away > 0)
    bet.InitialAwayOdds = away;
}

/**
 * live Round>0：Map0 仅保留当时还在 Sources 里的全场盘馆。
 * [A8 可证实] OB；[changmen 扩展] Polymarket / PredictFun / Limitless。
 * PM 在 Round===BO 时已由 project_sources 从 Map0 剥到决胜局，此处只保留、不加回。
 * trim 前保全 Initial*。
 */
export function trimMapZeroLive(rows) {
  for (const row of rows || []) {
    const liveMap = Number(row.Round) || 0;
    if (liveMap <= 0)
      continue;
    const fullBet = (row.Bets || []).find(b => (Number(b.Map) || 0) === 0);
    if (!fullBet)
      continue;
    preserveInitialOddsFromSources(fullBet);
    const kept = {};
    if (fullBet.Sources?.OB)
      kept.OB = fullBet.Sources.OB;
    if (fullBet.Sources?.Polymarket)
      kept.Polymarket = fullBet.Sources.Polymarket;
    if (fullBet.Sources?.PredictFun)
      kept.PredictFun = fullBet.Sources.PredictFun;
    if (fullBet.Sources?.Limitless)
      kept.Limitless = fullBet.Sources.Limitless;
    fullBet.Sources = kept;
  }
}

export function stripOrphanPlatforms(rows, platformMatches) {
  for (const row of rows || []) {
    if (row?.Matchs && typeof row.Matchs === "object") {
      for (const [plat, srcId] of Object.entries({ ...row.Matchs })) {
        if (!findPlatformMatch(platformMatches, plat, srcId))
          delete row.Matchs[plat];
      }
    }
    if (!Array.isArray(row?.Bets))
      continue;
    for (const bet of row.Bets) {
      if (!bet?.Sources)
        continue;
      for (const plat of Object.keys(bet.Sources)) {
        const srcId = row.Matchs?.[plat];
        if (!srcId || !findPlatformMatch(platformMatches, plat, srcId))
          delete bet.Sources[plat];
      }
    }
    row.Bets = row.Bets.filter((b) => {
      if (Object.keys(b.Sources || {}).length > 0)
        return true;
      const map = Number(b.Map) || 0;
      if (map !== 0)
        return false;
      const liveMap = Number(row.Round) || 0;
      if (liveMap <= 0)
        return false;
      return (Number(b.InitialHomeOdds) || 0) > 0 || (Number(b.InitialAwayOdds) || 0) > 0;
    });
    const platformsWithSources = new Set();
    for (const bet of row.Bets || []) {
      for (const p of Object.keys(bet.Sources || {}))
        platformsWithSources.add(p);
    }
    if (Array.isArray(row.Reverse))
      row.Reverse = row.Reverse.filter(p => platformsWithSources.has(p));
  }
}

export function refreshBetNames(rows) {
  for (const row of rows || []) {
    const teams = parseTitleTeams(row.Title);
    for (const bet of row.Bets || []) {
      if (teams) {
        bet.HomeName = teams.home;
        bet.AwayName = teams.away;
      }
      const map = Number(bet.Map) || 0;
      if (!bet.Name) {
        bet.Name = map === 0 ? "全场-获胜" : `[地图${map}]-单局-获胜`;
      }
      if (row.ID != null)
        bet.MatchID = Number(row.ID);
    }
  }
}

export function sortBets(rows) {
  for (const row of rows || []) {
    if (!Array.isArray(row.Bets) || row.Bets.length < 2)
      continue;
    row.Bets.sort((a, b) => (Number(a.Map) || 0) - (Number(b.Map) || 0));
  }
}

/** strip 后仍不足多馆的场剔除；进行中（Round>0）允许暂留单馆，避免源抖动误归档 */
export function filterMultiPlatform(rows, minPlatforms = MIN_PLATFORMS) {
  const min = Math.max(1, Number(minPlatforms) || MIN_PLATFORMS);
  return (rows || []).filter((r) => {
    const n = Object.keys(r?.Matchs || {}).length;
    if (n >= min)
      return true;
    // live：至少还剩 1 馆则保留，等缺席馆恢复
    if (n >= 1 && (Number(r?.Round) || 0) > 0)
      return true;
    return false;
  });
}

/** 投影后：trim → strip → 命名 → 排序 */
export function applyLiveShape(rows, { matches } = {}) {
  trimMapZeroLive(rows);
  stripOrphanPlatforms(rows, matches);
  refreshBetNames(rows);
  sortBets(rows);
  return rows;
}

/**
 * 场次主客锁：PM → OB → RAY → PredictFun（后者仅兜底，纯 PF/Limitless+PF 合场可建锁）。
 * 禁止 min/max；不采信 row 上脏 gb；后到高优先级 upgrade。
 */
import {
  lookupCanonicalTeamName,
  lookupGbTeamIdByPlatform,
  normalizeTeam,
} from "@changmen/match-identity/teams/team_key.js";
import { parseTitleTeams } from "@changmen/match-identity/teams/match_utils.js";
import { getGameCodeForPlatformId } from "@changmen/shared/catalog/game_catalog";
import { resolvePlatformTeamId } from "@changmen/shared/catalog/pb_team_platform_id";

export const LOCK_ANCHOR_PLATFORMS = ["Polymarket", "OB", "RAY", "PredictFun"];

function parseLockedGb(value) {
  if (value == null || value === "")
    return null;
  const s = String(value).trim();
  return s || null;
}

export function findPlatformMatch(matches, platform, sourceMatchId) {
  const bucket = matches?.[platform];
  if (!bucket || sourceMatchId == null)
    return null;
  const sid = String(sourceMatchId);
  return bucket[sid] || Object.values(bucket).find(m => String(m.SourceMatchID) === sid) || null;
}

export function teamIdsFromPm(platform, pm) {
  const sourceGameId = pm.SourceGameID ?? pm.GameID;
  const gameCode = getGameCodeForPlatformId(platform, sourceGameId);
  const homeIdRaw = String(pm.HomeID ?? pm.home_id ?? pm.SourceHomeID ?? "").trim();
  const awayIdRaw = String(pm.AwayID ?? pm.away_id ?? pm.SourceAwayID ?? "").trim();
  const homeId = resolvePlatformTeamId(platform, homeIdRaw, sourceGameId, gameCode);
  const awayId = resolvePlatformTeamId(platform, awayIdRaw, sourceGameId, gameCode);
  const homeGb = homeId ? parseLockedGb(lookupGbTeamIdByPlatform(platform, homeId)) : null;
  const awayGb = awayId ? parseLockedGb(lookupGbTeamIdByPlatform(platform, awayId)) : null;
  return { homeGb, awayGb, homeId, awayId, gameCode };
}

export function pickLockFromAnchors(matchs, matches) {
  for (const platform of LOCK_ANCHOR_PLATFORMS) {
    const sourceMatchId = matchs?.[platform];
    if (sourceMatchId == null || sourceMatchId === "")
      continue;
    const pm = findPlatformMatch(matches, platform, sourceMatchId);
    if (!pm)
      continue;
    const { homeGb, awayGb } = teamIdsFromPm(platform, pm);
    if (!homeGb || !awayGb || homeGb === awayGb)
      continue;
    return { homeGb, awayGb, anchorPlatform: platform };
  }
  return null;
}

function titleFromLock(homeGb, awayGb, fallbackTitle) {
  const homeName = lookupCanonicalTeamName(homeGb) || parseTitleTeams(fallbackTitle)?.home;
  const awayName = lookupCanonicalTeamName(awayGb) || parseTitleTeams(fallbackTitle)?.away;
  if (!homeName || !awayName)
    return fallbackTitle || "";
  return `${String(homeName).trim()} vs ${String(awayName).trim()}`;
}

export function sameTeamPair(homeA, awayA, homeB, awayB) {
  if (!homeA || !awayA || !homeB || !awayB)
    return false;
  return (homeA === homeB && awayA === awayB)
    || (homeA === awayB && awayA === homeB);
}

function sameOrientation(homeA, awayA, homeB, awayB) {
  return homeA === homeB && awayA === awayB;
}

function applyLock(row, homeGb, awayGb, lockSource, fallbackTitle) {
  row.HomeGbTeamId = homeGb;
  row.AwayGbTeamId = awayGb;
  row.Title = titleFromLock(homeGb, awayGb, fallbackTitle);
  row._lockAnchor = lockSource;
  delete row._clearGbLock;
  return { homeGb, awayGb, locked: true, lockSource };
}

function clearLock(row, matches) {
  row.HomeGbTeamId = undefined;
  row.AwayGbTeamId = undefined;
  row._lockAnchor = null;
  row._clearGbLock = true;
  for (const platform of [...LOCK_ANCHOR_PLATFORMS, "IA", "PB", "TF"]) {
    const sid = row.Matchs?.[platform];
    if (!sid)
      continue;
    const pm = findPlatformMatch(matches, platform, sid);
    if (!pm)
      continue;
    const home = String(pm.Home ?? pm.home ?? "").trim();
    const away = String(pm.Away ?? pm.away ?? "").trim();
    if (home && away) {
      row.Title = `${home} vs ${away}`;
      break;
    }
  }
  return { homeGb: null, awayGb: null, locked: false, lockSource: null };
}

export function isStickyOrientationEnabled(opts = {}) {
  if (opts.stickyOrientation === true)
    return true;
  if (opts.stickyOrientation === false)
    return false;
  if (opts.forceReanchorOrientation === true)
    return false;
  const v = process.env.MATCH_COMPOSER_STICKY_ORIENTATION
    || process.env.MATCH_PROJECTOR_STICKY_ORIENTATION
    || "";
  return String(v).trim() === "1";
}

export function resolveOrientationLock(row, matches, existingRow, opts = {}) {
  const forceReanchorOrientation = opts.forceReanchorOrientation === true
    || String(process.env.MATCH_COMPOSER_REANCHOR || "").trim() === "1"
    || String(process.env.MATCH_PROJECTOR_REANCHOR || "").trim() === "1";
  const stickyOrientation = isStickyOrientationEnabled({
    ...opts,
    forceReanchorOrientation,
  });

  const existingHome = parseLockedGb(existingRow?.home_gb_team_id ?? existingRow?.HomeGbTeamId);
  const existingAway = parseLockedGb(existingRow?.away_gb_team_id ?? existingRow?.AwayGbTeamId);
  const anchor = pickLockFromAnchors(row.Matchs, matches);
  const fallbackTitle = row.Title || existingRow?.title;

  if (existingHome && existingAway && existingHome !== existingAway) {
    if (anchor) {
      if (!sameTeamPair(existingHome, existingAway, anchor.homeGb, anchor.awayGb)) {
        return applyLock(
          row,
          anchor.homeGb,
          anchor.awayGb,
          `reanchor:${anchor.anchorPlatform}`,
          fallbackTitle,
        );
      }
      const orientDiffers = !sameOrientation(
        existingHome,
        existingAway,
        anchor.homeGb,
        anchor.awayGb,
      );
      if (orientDiffers && (forceReanchorOrientation || !stickyOrientation)) {
        return applyLock(
          row,
          anchor.homeGb,
          anchor.awayGb,
          `upgrade:${anchor.anchorPlatform}`,
          fallbackTitle,
        );
      }
      return applyLock(row, existingHome, existingAway, "existing", fallbackTitle);
    }
    const hasAnchorSlot = LOCK_ANCHOR_PLATFORMS.some(
      p => row.Matchs?.[p] != null && row.Matchs[p] !== "",
    );
    if (hasAnchorSlot)
      return applyLock(row, existingHome, existingAway, "existing-gap", fallbackTitle);
  }

  if (anchor)
    return applyLock(row, anchor.homeGb, anchor.awayGb, anchor.anchorPlatform, fallbackTitle);

  return clearLock(row, matches);
}

/**
 * @param {{ home?: string, away?: string }} [lockNames] 锁两侧队名的免插件来源（持久化标题）。
 *   队名兜底不得只依赖 lookupCanonicalTeamName，否则与 gb 主路径共用 team-resolver，
 *   插件缺失时两条通道一起断，整场源清空。
 */
export function sideModeAgainstLock(platform, pm, homeGb, awayGb, lockNames) {
  if (!homeGb || !awayGb || !pm)
    return "ambiguous";
  const { homeGb: ph, awayGb: pa } = teamIdsFromPm(platform, pm);
  if (ph && pa) {
    if (ph === homeGb && pa === awayGb)
      return "aligned";
    if (ph === awayGb && pa === homeGb)
      return "reversed";
    return "ambiguous";
  }
  const phN = normalizeTeam(pm.Home ?? pm.home);
  const paN = normalizeTeam(pm.Away ?? pm.away);
  const ch = normalizeTeam(lookupCanonicalTeamName(homeGb) || lockNames?.home || "");
  const ca = normalizeTeam(lookupCanonicalTeamName(awayGb) || lockNames?.away || "");
  if (!phN || !paN || !ch || !ca)
    return "ambiguous";
  if (phN === ch && paN === ca)
    return "aligned";
  if (phN === ca && paN === ch)
    return "reversed";
  return "ambiguous";
}

export { parseLockedGb, titleFromLock };

/**
 * Sources / Reverse 投影。不经 accumulate；直接从 platform_bets 取 native。
 *
 * 禁止 Map0→任意局盘回填：缺原生地图盘就 omit，勿用全场冒充。
 * 仅当 Round===BO 时用 Map0 作为决胜局的投影输入（只 swap 一次）。
 * Polymarket Map0 拷到决胜局后从 Map0 删除，避免同一 token 挂两行。
 * 若 platform_bets 已有该馆原生 Map N，走原生投影、不剥 Map0。
 *
 * PB B1 / S2：主 event（Matchs.PB）缺某 Map 时，从同 rotNum sibling 取该 Map；
 * Source.HomeID / BetID / LineID 仍是那条腿自己的 event；Matchs.PB 不变。
 */
import { parseTitleTeams } from "@changmen/match-identity/teams/match_utils.js";
import { getGameCodeForPlatformId } from "@changmen/shared/catalog/game_catalog";
import { isComposerPbRotnumCollapse } from "../../lib/config.js";
import { listPbEventIdsForProjection } from "../normalize/pb_rotnum_collapse.js";
import { rawSourceForMap } from "../normalize/native_bets.js";
import { resolveRowStructure } from "../structure/resolve_structure.js";
import { swapBetSource } from "../util/swap.js";
import {
  findPlatformMatch,
  resolveOrientationLock,
  sideModeAgainstLock,
} from "./orientation_lock.js";

export function normalizeOverrideMode(overrideMode) {
  if (overrideMode == null || overrideMode === "")
    return undefined;
  if (typeof overrideMode === "string") {
    const s = overrideMode.trim();
    if (s === "force_aligned" || s === "force_reversed")
      return s;
    return undefined;
  }
  if (typeof overrideMode === "object" && overrideMode.mode != null)
    return normalizeOverrideMode(overrideMode.mode);
  return undefined;
}

export function applyOverride(autoMode, overrideMode) {
  const ov = normalizeOverrideMode(overrideMode);
  if (ov === "force_reversed")
    return "reversed";
  if (ov === "force_aligned") {
    if (autoMode === "reversed")
      return "reversed";
    if (autoMode === "ambiguous")
      return "ambiguous";
    return "aligned";
  }
  return autoMode;
}

export function betHasOdds(src) {
  if (!src || typeof src !== "object")
    return false;
  return Boolean(String(src.HomeID ?? "").trim() || String(src.AwayID ?? "").trim());
}

/**
 * 取某 Map 的原生 Source；PB 主 event 缺盘时回落到 sibling（HomeID/BetID 仍属该腿 event）。
 * @returns {{ raw: object|null, pm: object|null, sourceMatchId: string }}
 */
export function resolveRawSourceForMap({
  platform,
  primarySourceMatchId,
  mapNum,
  bets,
  matches,
  row,
}) {
  const primarySid = String(primarySourceMatchId ?? "");
  const primaryPm = findPlatformMatch(matches, platform, primarySid);
  const gameCode = getGameCodeForPlatformId(
    platform,
    primaryPm?.SourceGameID ?? primaryPm?.GameID,
  );
  const primaryRaw = rawSourceForMap(platform, primarySid, mapNum, bets, gameCode);
  if (betHasOdds(primaryRaw) || platform !== "PB" || !isComposerPbRotnumCollapse()) {
    return { raw: primaryRaw, pm: primaryPm, sourceMatchId: primarySid };
  }

  const ids = listPbEventIdsForProjection(row, matches)
    .filter(sid => sid && sid !== primarySid);
  for (const sid of ids) {
    const pm = findPlatformMatch(matches, platform, sid);
    if (!pm)
      continue;
    const code = getGameCodeForPlatformId(platform, pm.SourceGameID ?? pm.GameID);
    const raw = rawSourceForMap(platform, sid, mapNum, bets, code);
    if (betHasOdds(raw))
      return { raw, pm, sourceMatchId: sid };
  }
  return { raw: primaryRaw, pm: primaryPm, sourceMatchId: primarySid };
}

export function projectPlatformSource({
  platform,
  pm,
  raw,
  homeGb,
  awayGb,
  overrideMode,
  lockNames,
}) {
  if (!betHasOdds(raw) || !homeGb || !awayGb) {
    return { mode: "omit", source: null, inReverse: false, omitReason: "no_raw_or_lock" };
  }
  const autoMode = sideModeAgainstLock(platform, pm, homeGb, awayGb, lockNames);
  const ov = normalizeOverrideMode(overrideMode);
  const mode = applyOverride(autoMode, ov);
  if (mode === "ambiguous") {
    return {
      mode: "ambiguous",
      source: null,
      inReverse: false,
      omitReason: autoMode === "ambiguous" && ov === "force_aligned"
        ? "ambiguous_ignore_force_aligned"
        : "ambiguous",
    };
  }
  const needSwap = mode === "reversed";
  const projected = needSwap ? swapBetSource(raw) : { ...raw };
  const expectHome = needSwap ? String(raw.AwayID ?? "") : String(raw.HomeID ?? "");
  const expectAway = needSwap ? String(raw.HomeID ?? "") : String(raw.AwayID ?? "");
  if (String(projected.HomeID ?? "") !== expectHome || String(projected.AwayID ?? "") !== expectAway) {
    return { mode: "omit", source: null, inReverse: false, omitReason: "i1_structure" };
  }
  if (!String(expectHome).trim() || !String(expectAway).trim()) {
    return { mode: "omit", source: null, inReverse: false, omitReason: "missing_ids" };
  }
  return { mode, source: projected, inReverse: needSwap };
}

/** 按赛制层给出的 periods 铺 Bets 行，保留同 Map 的既有行 */
function ensureBetShells(row, periods) {
  const existing = new Map((row.Bets || []).map(b => [Number(b.Map) || 0, b]));
  row.Bets = periods.map(mapNum => existing.get(mapNum) || { Map: mapNum, Sources: {} });
}

export function projectClientMatchSides(row, {
  matches,
  bets,
  existingRow,
  platformOverrides = {},
  forceReanchorOrientation = false,
  stickyOrientation,
} = {}) {
  const structure = row._periods
    ? { deciderMap: Number(row._deciderMap) || 0, periods: row._periods }
    : resolveRowStructure(row, { matches, bets });
  const deciderMap = structure.deciderMap;
  ensureBetShells(row, structure.periods);

  const lock = resolveOrientationLock(row, matches, existingRow, {
    forceReanchorOrientation,
    stickyOrientation,
  });
  const overrides = platformOverrides[Number(row.ID)]
    || platformOverrides[row.ID]
    || platformOverrides[String(row.ID)]
    || {};

  if (!lock.locked) {
    row.Reverse = [];
    for (const bet of row.Bets || [])
      bet.Sources = {};
    delete row.SideAlignAmbiguous;
    return { reverse: [], omitted: [], locked: false, lockSource: lock.lockSource };
  }

  const { homeGb, awayGb } = lock;
  /** 锁朝向的队名快照：team-resolver 不可用时，队名兜底的唯一免插件来源 */
  const lockNames = parseTitleTeams(row.Title) || undefined;
  const reverse = [];
  const omitted = [];
  const ambiguous = [];
  /** 已投影的 Map0 Source：决胜局复用它，中间局仅用于区分 omit 原因 */
  const map0Projected = {};
  /** PM 全场已拷到决胜局：投影结束后从 Map0 剥除 */
  let pmMap0CopiedToDecider = false;

  const orderedBets = [...(row.Bets || [])].sort(
    (a, b) => (Number(a.Map) || 0) - (Number(b.Map) || 0),
  );

  for (const bet of orderedBets) {
    const mapNum = Number(bet.Map) || 0;
    const nextSources = {};
    for (const [platform, sourceMatchId] of Object.entries(row.Matchs || {})) {
      /** 决胜局：全场盘语义上即该局盘。Map0 已投影过，直接复用，不再二次 swap */
      const useMap0AsDecider = () => {
        if (mapNum === 0 || mapNum !== deciderMap)
          return false;
        const src = map0Projected[platform];
        if (!betHasOdds(src))
          return false;
        nextSources[platform] = { ...src };
        if (platform === "Polymarket")
          pmMap0CopiedToDecider = true;
        return true;
      };

      const pmPrimary = findPlatformMatch(matches, platform, sourceMatchId);
      if (!pmPrimary) {
        omitted.push({ platform, map: mapNum, reason: "no_pm" });
        continue;
      }
      const { raw, pm: pmForSide } = resolveRawSourceForMap({
        platform,
        primarySourceMatchId: sourceMatchId,
        mapNum,
        bets,
        matches,
        row,
      });

      // 局盘无原生赔率：禁止用 Map0 全场冒充（决胜局除外）
      if (!betHasOdds(raw) && mapNum !== 0) {
        if (useMap0AsDecider())
          continue;
        if (betHasOdds(map0Projected[platform])) {
          omitted.push({ platform, map: mapNum, reason: "no_map0_fallback_on_map_line" });
        }
        else {
          omitted.push({ platform, map: mapNum, reason: "no_native_map_odds" });
        }
        continue;
      }

      const r = projectPlatformSource({
        platform,
        pm: pmForSide || pmPrimary,
        raw,
        homeGb,
        awayGb,
        overrideMode: overrides[platform],
        lockNames,
      });
      if (!r.source) {
        if (r.mode === "ambiguous")
          ambiguous.push(platform);
        if (useMap0AsDecider())
          continue;
        omitted.push({ platform, map: mapNum, reason: r.omitReason || r.mode });
        continue;
      }
      nextSources[platform] = r.source;
      if (mapNum === 0)
        map0Projected[platform] = r.source;
      if (r.inReverse && !reverse.includes(platform))
        reverse.push(platform);
    }
    bet.Sources = nextSources;
    const parts = String(row.Title || "").split(/\s+vs\s+/i);
    if (parts.length >= 2) {
      bet.HomeName = parts[0].trim();
      bet.AwayName = parts.slice(1).join(" vs ").trim();
    }
  }

  if (pmMap0CopiedToDecider && deciderMap > 0) {
    const map0 = (row.Bets || []).find(b => (Number(b.Map) || 0) === 0);
    if (map0?.Sources?.Polymarket)
      delete map0.Sources.Polymarket;
  }

  const platformsWithSources = new Set();
  for (const bet of row.Bets || []) {
    for (const p of Object.keys(bet.Sources || {}))
      platformsWithSources.add(p);
  }
  row.Reverse = reverse.filter(p => platformsWithSources.has(p));
  if (ambiguous.length)
    row.SideAlignAmbiguous = [...new Set(ambiguous)];
  else
    delete row.SideAlignAmbiguous;

  return {
    reverse: row.Reverse,
    omitted,
    locked: true,
    homeGb,
    awayGb,
    lockSource: lock.lockSource,
  };
}

export function projectList(list, ctx) {
  const existingById = new Map(
    (ctx.existingClientRows || []).map(r => [Number(r.id ?? r.ID), r]),
  );
  const stats = { locked: 0, unlocked: 0, omitEvents: 0, reanchored: 0 };
  for (const row of list || []) {
    const result = projectClientMatchSides(row, {
      ...ctx,
      existingRow: existingById.get(Number(row.ID)),
    });
    row._lockSource = result.lockSource || row._lockAnchor || null;
    row._omitEvents = result.omitted || [];
    if (result.locked)
      stats.locked += 1;
    else
      stats.unlocked += 1;
    stats.omitEvents += result.omitted?.length || 0;
    const src = String(result.lockSource || "");
    if (src.startsWith("reanchor") || src.startsWith("upgrade"))
      stats.reanchored += 1;
  }
  return stats;
}

import * as db from "@changmen/db";
import {
  ensureClientMatchId,
  isPlaceholderTeamName,
  lookupCanonicalTeamName,
  lookupGbTeamIdByPlatform,
  manualMergeKey,
  normalizeTeam,
  teamsFromPlatformRows,
} from "@changmen/match-identity";
import { getGameCodeForPlatformId, getPlatformGameId, resolveClientGame } from "@changmen/shared/catalog/game_catalog";
import { formatPbTeamPlatformId, resolvePlatformTeamId } from "@changmen/shared/catalog/pb_team_platform_id";
import { collectorRuntime as store } from "../runtime_ports.js";
import { ensureTeamPlugin, invalidateTeamPlugin, matchMergeOnce } from "../ops/match_merge_once.js";
import { invalidateMatcherRdsSnapshot } from "../ops/rds_snapshot_cache.js";
import { resetMatcherUiTeamPlugin } from "../ui/merge_mode.js";
import "../lib/env.js";

function invalidateTeamMappings() {
  invalidateTeamPlugin();
  resetMatcherUiTeamPlugin();
}

/**
 * 人工关联：平台赛事 → client_match，并写入队伍 ID 映射。
 */

function gameCodeForPlatform(platform, sourceGameId) {
  return getGameCodeForPlatformId(platform, sourceGameId);
}

function parseGbTeamId(value) {
  if (value == null || value === "")
    return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function parseTitleTeams(title) {
  const t = String(title || "").trim();
  if (!t.includes(" vs "))
    return null;
  const parts = t.split(" vs ").map(s => s.trim());
  if (parts.length < 2)
    return null;
  const [home, away] = parts;
  if (isPlaceholderTeamName(home) || isPlaceholderTeamName(away))
    return null;
  return { home, away };
}

function platformMatchRowForClient(plat, srcId, platformsById, pm) {
  const row = platformsById?.[`${plat}:${srcId}`];
  if (row)
    return row;
  if (pm && String(pm.platform) === String(plat) && String(pm.source_match_id) === String(srcId))
    return pm;
  return null;
}

/** 与 match_merge titleFromMatchs 同源：关联平台行 → teamsFromPlatformRows */
function buildPlatformRowsForClientTeams(cm, pm, platformsById) {
  const matchs = { ...(cm.matchs || {}) };
  if (pm?.platform != null && pm?.source_match_id != null) {
    const plat = String(pm.platform);
    const srcId = String(pm.source_match_id);
    if (!matchs[plat])
      matchs[plat] = srcId;
  }

  const rows = [];
  for (const [platform, sourceMatchId] of Object.entries(matchs)) {
    const row = platformMatchRowForClient(platform, sourceMatchId, platformsById, pm);
    if (!row)
      continue;
    const sourceGameId = row.source_game_id ?? row.SourceGameID ?? row.GameID;
    const gameCode = getGameCodeForPlatformId(platform, sourceGameId);
    const home = String(row.home ?? row.Home ?? "").trim();
    const away = String(row.away ?? row.Away ?? "").trim();
    if (isPlaceholderTeamName(home) && isPlaceholderTeamName(away))
      continue;
    rows.push({
      platform,
      home,
      away,
      homeId: resolvePlatformTeamId(
        platform,
        row.home_id ?? row.HomeID ?? row.SourceHomeID,
        sourceGameId,
        gameCode,
      ),
      awayId: resolvePlatformTeamId(
        platform,
        row.away_id ?? row.AwayID ?? row.SourceAwayID,
        sourceGameId,
        gameCode,
      ),
    });
  }
  return rows;
}

/** 与 reconcile 用同一 Title 基准；DB title 仅作兜底 */
async function resolveClientTeams(cm, pm, platformsById) {
  await ensureTeamPlugin();

  const rows = buildPlatformRowsForClientTeams(cm, pm, platformsById);
  if (rows.length) {
    const picked = teamsFromPlatformRows(rows, {
      lookupGbTeamId: lookupGbTeamIdByPlatform,
      lookupCanonicalName: lookupCanonicalTeamName,
    });
    if (picked?.home && picked?.away) {
      return { home: String(picked.home).trim(), away: String(picked.away).trim() };
    }
  }

  const fromTitle = parseTitleTeams(cm.title);
  if (fromTitle)
    return fromTitle;

  const bets = Array.isArray(cm.bets) ? cm.bets : [];
  if (bets.length) {
    const b = bets[0];
    const home = String(b.HomeName || b.homeName || "").trim();
    const away = String(b.AwayName || b.awayName || "").trim();
    if (!isPlaceholderTeamName(home) && !isPlaceholderTeamName(away)) {
      return { home, away };
    }
  }

  if (pm && !isPlaceholderTeamName(pm.home) && !isPlaceholderTeamName(pm.away)) {
    return { home: String(pm.home).trim(), away: String(pm.away).trim() };
  }

  return null;
}

/** @returns {{ mode: 'aligned'|'reversed'|'ambiguous', reversed: boolean|null, detail?: string }} */
function analyzeSideAlignment(pmHome, pmAway, cmHome, cmAway) {
  const ph = normalizeTeam(pmHome);
  const pa = normalizeTeam(pmAway);
  const ch = normalizeTeam(cmHome);
  const ca = normalizeTeam(cmAway);
  if (!ph || !pa || !ch || !ca) {
    return { mode: "ambiguous", reversed: null, detail: "队名不完整，无法自动判断" };
  }

  const directHome = ph === ch;
  const directAway = pa === ca;
  const swapHome = ph === ca;
  const swapAway = pa === ch;

  if (directHome && directAway) {
    return { mode: "aligned", reversed: false, detail: "主客与系统一致" };
  }
  if (swapHome && swapAway) {
    return { mode: "reversed", reversed: true, detail: "平台主客与系统相反" };
  }

  const parts = [];
  if (directHome)
    parts.push("主队名一致");
  else if (swapHome)
    parts.push("平台主与系统客名一致");
  if (directAway)
    parts.push("客队名一致");
  else if (swapAway)
    parts.push("平台客与系统主名一致");
  const detail = parts.length ? `${parts.join("，")}，但整体无法判定` : "队名无法对应";
  return { mode: "ambiguous", reversed: null, detail };
}

async function allocateManualGbTeamId() {
  const id = await db.nextManualGbTeamId();
  return parseGbTeamId(id);
}

async function ensureManualGbTeamIdOnRow(row) {
  if (!row)
    return null;
  if (row.gb_team_id != null)
    return parseGbTeamId(row.gb_team_id);
  const manualGbTeamId = await allocateManualGbTeamId();
  const updated = await db.updateCanonicalTeamById(row.id, {
    gb_team_id: manualGbTeamId,
    updated_by: "手动",
  });
  if (!updated) {
    throw new Error(
      `标准队伍「${row.name}」（${row.game}）分配 gb_team_id 失败`,
    );
  }
  return parseGbTeamId(updated.gb_team_id);
}

function isPgUniqueViolation(error) {
  return error?.code === "23505";
}

function uniqueConstraintKind(error) {
  const msg = String(error?.message || error?.details || "");
  if (msg.includes("canonical_teams_game_name_key"))
    return "game_name";
  if (msg.includes("canonical_teams_gb_team_id_key"))
    return "gb_team_id";
  return "unknown";
}

async function describeCanonicalTeamRow(row) {
  if (!row)
    return null;
  const game = row.game || "?";
  const label = row.name || "?";
  if (row.gb_team_id != null) {
    return `游戏 ${game} · 标准队伍「${label}」· 已有 gb_team_id ${row.gb_team_id}`;
  }
  return `游戏 ${game} · 标准队伍「${label}」· 尚无 gb_team_id（种子/历史数据）`;
}

async function recoverCanonicalTeamAfterUniqueViolation(gameCode, name, norm) {
  const exact = await fetchCanonicalTeamExact(gameCode, name);
  if (exact)
    return exact;
  const byNorm = await findCanonicalTeamByNormalizedName(gameCode, norm);
  if (byNorm)
    return byNorm;
  return null;
}

async function buildCanonicalInsertConflictMessage(gameCode, name, error) {
  const kind = uniqueConstraintKind(error);
  const row = await recoverCanonicalTeamAfterUniqueViolation(
    gameCode,
    name,
    normalizeTeam(name),
  );
  const existing = row ? await describeCanonicalTeamRow(row) : null;

  if (kind === "gb_team_id") {
    return [
      "分配 gb_team_id 时发生冲突（编号已被占用）",
      "请刷新页面后重新拖线关联",
    ].join("\n");
  }

  if (existing) {
    return [
      "无法新建标准队伍：与库中已有记录重名",
      existing,
      "请刷新页面后重试；若仍失败，可能是数据同步延迟",
    ].join("\n");
  }

  return [
    `无法新建标准队伍：游戏 ${gameCode} · 队名「${name}」与库中记录冲突`,
    "请刷新页面后重新拖线；若反复出现，请检查 canonical_teams 是否已有同名队伍",
  ].join("\n");
}

async function fetchCanonicalTeamExact(gameCode, name) {
  return db.fetchCanonicalTeamExact(gameCode, name);
}

async function findCanonicalTeamByNormalizedName(gameCode, norm) {
  return db.findCanonicalTeamByNormalizedName(gameCode, norm);
}

/** 仅 Matcher 手动拖线连线：gb_team_id 从 100000 自增，updated_by = 手动 */
async function resolveOrCreateManualTeam(gameCode, teamName) {
  const name = String(teamName || "").trim();
  if (!name || isPlaceholderTeamName(name)) {
    throw new Error("队名无效");
  }

  const norm = normalizeTeam(name);

  const exact = await fetchCanonicalTeamExact(gameCode, name);
  if (exact)
    return ensureManualGbTeamIdOnRow(exact);

  const byNorm = await findCanonicalTeamByNormalizedName(gameCode, norm);
  if (byNorm)
    return ensureManualGbTeamIdOnRow(byNorm);

  const manualGbTeamId = await allocateManualGbTeamId();
  try {
    const inserted = await db.insertCanonicalTeam({
      gb_team_id: manualGbTeamId,
      game: gameCode,
      name,
      updated_by: "手动",
    });
    return parseGbTeamId(inserted.gb_team_id);
  }
  catch (error) {
    if (isPgUniqueViolation(error)) {
      const existing = await recoverCanonicalTeamAfterUniqueViolation(gameCode, name, norm);
      if (existing) {
        try {
          return await ensureManualGbTeamIdOnRow(existing);
        }
        catch (reuseErr) {
          const detail = await describeCanonicalTeamRow(existing);
          throw new Error(
            [`复用已有标准队伍失败`, detail, reuseErr.message].filter(Boolean).join("\n"),
          );
        }
      }
      throw new Error(await buildCanonicalInsertConflictMessage(gameCode, name, error));
    }
    throw new Error(
      `新建标准队伍失败（${gameCode} · 「${name}」）：${error.message}`,
    );
  }
}

function resolveGameCodeForPlatformPair(pmA, pmB, cmHint) {
  for (const pm of [pmA, pmB]) {
    const code = gameCodeForPlatform(pm.platform, pm.source_game_id);
    if (code)
      return code;
  }
  if (cmHint) {
    const gid = String(cmHint.game_id || "").trim();
    const a8Map = { 1: "lol", 2: "dota2", 3: "cs2", 4: "kog", 8: "valorant" };
    const fromGid = a8Map[gid] || a8Map[Number(gid)];
    if (fromGid)
      return fromGid;
    const parsed = String(cmHint.game || "").match(/\(([^)]+)\)\s*$/);
    if (parsed)
      return parsed[1].toLowerCase();
  }
  return "unknown";
}

function resolvePairClientMatchKey(pmSource, pmTarget) {
  const idS = pmSource.match_id != null && pmSource.match_id !== "" ? Number(pmSource.match_id) : null;
  const idT = pmTarget.match_id != null && pmTarget.match_id !== "" ? Number(pmTarget.match_id) : null;
  if (idS && idT && idS !== idT) {
    throw new Error(`两场赛事已关联到不同 client_match（#${idS} 与 #${idT}），请使用合并功能`);
  }
  return {
    existingId: idT || idS || null,
    mergeKey: manualMergeKey(
      pmSource.platform,
      pmSource.source_match_id,
      pmTarget.platform,
      pmTarget.source_match_id,
    ),
  };
}

async function resolvePairClientMatchId(pmSource, pmTarget, stub = {}) {
  const { existingId, mergeKey } = resolvePairClientMatchKey(pmSource, pmTarget);
  if (existingId)
    return existingId;
  const adapter = db.getClientMatchIdAdapter();
  return ensureClientMatchId(adapter, mergeKey, stub);
}

async function fetchPlatformMatchRow(platform, sourceMatchId) {
  const pm = await db.fetchPlatformMatchRow(platform, sourceMatchId);
  if (!pm) {
    const plat = String(platform || "").trim();
    const srcId = String(sourceMatchId || "").trim();
    throw new Error(`平台赛事不存在: ${plat} #${srcId}`);
  }
  return pm;
}

async function previewLinkPlatformAlignment({ platform, sourceMatchId, targetPlatform, targetMatchId }) {
  const srcPlat = String(platform || "").trim();
  const tgtPlat = String(targetPlatform || "").trim();
  const srcId = String(sourceMatchId || "").trim();
  const tgtId = String(targetMatchId || "").trim();
  if (!srcPlat || !tgtPlat || !srcId || !tgtId)
    throw new Error("参数不完整");
  if (srcPlat === tgtPlat)
    throw new Error("请拖到另一个平台的赛事");

  const [pmSource, pmTarget] = await Promise.all([
    fetchPlatformMatchRow(srcPlat, srcId),
    fetchPlatformMatchRow(tgtPlat, tgtId),
  ]);

  const refTeamsPick = teamsFromPlatformRows([
    { platform: pmSource.platform, home: pmSource.home, away: pmSource.away },
    { platform: pmTarget.platform, home: pmTarget.home, away: pmTarget.away },
  ]);
  if (!refTeamsPick)
    throw new Error("平台赛事队名不完整");
  const refTeams = { home: refTeamsPick.home, away: refTeamsPick.away };

  const alignment = analyzeSideAlignment(pmSource.home, pmSource.away, refTeams.home, refTeams.away);
  const { existingId, mergeKey } = resolvePairClientMatchKey(pmSource, pmTarget);

  return {
    linkType: "platform",
    platform: srcPlat,
    sourceMatchId: srcId,
    targetPlatform: tgtPlat,
    targetMatchId: tgtId,
    clientMatchId: existingId,
    mergeKey,
    clientMatchIdPending: !existingId,
    platformTeams: {
      home: pmSource.home,
      away: pmSource.away,
      home_id: pmSource.home_id,
      away_id: pmSource.away_id,
    },
    systemTeams: refTeams,
    targetTeams: {
      home: pmTarget.home,
      away: pmTarget.away,
      home_id: pmTarget.home_id,
      away_id: pmTarget.away_id,
    },
    alignment,
    suggestedReversed: alignment.reversed,
    sourceMatchIdExisting: pmSource.match_id,
    targetMatchIdExisting: pmTarget.match_id,
  };
}

async function writeTeamMapsIdentityForPlatform(pm, gameCode) {
  const plat = String(pm.platform || "").trim();
  const results = [];
  results.push(await upsertTeamMapForMatchLink(
    plat,
    pm.home_id,
    pm.home,
    gameCode,
    pm.source_game_id,
  ));
  results.push(await upsertTeamMapForMatchLink(
    plat,
    pm.away_id,
    pm.away,
    gameCode,
    pm.source_game_id,
  ));
  return results;
}

async function persistPlatformSideOverride(cmId, platform, reversed) {
  const mode = reversed ? "force_reversed" : "force_aligned";
  return db.setClientMatchPlatformSideOverride(cmId, platform, mode);
}

async function linkPlatformToPlatform({
  platform,
  sourceMatchId,
  targetPlatform,
  targetMatchId,
  reversed: reversedInput,
}) {
  const preview = await previewLinkPlatformAlignment({
    platform,
    sourceMatchId,
    targetPlatform,
    targetMatchId,
  });

  const pmSource = await fetchPlatformMatchRow(preview.platform, preview.sourceMatchId);
  const pmTarget = await fetchPlatformMatchRow(preview.targetPlatform, preview.targetMatchId);
  const refTeamsPick = teamsFromPlatformRows([
    { platform: pmSource.platform, home: pmSource.home, away: pmSource.away },
    { platform: pmTarget.platform, home: pmTarget.home, away: pmTarget.away },
  ]);
  if (!refTeamsPick)
    throw new Error("平台赛事队名不完整");
  const refHome = refTeamsPick.home;
  const refAway = refTeamsPick.away;
  const cmId = await resolvePairClientMatchId(pmSource, pmTarget, {
    title: refTeamsPick.title,
    matchs: {
      [pmSource.platform]: String(pmSource.source_match_id),
      [pmTarget.platform]: String(pmTarget.source_match_id),
    },
  });

  let cmHint = null;
  if (pmTarget.match_id || pmSource.match_id) {
    const hintId = Number(pmTarget.match_id || pmSource.match_id);
    cmHint = await db.fetchClientMatchRow(hintId, "id,title,game,game_id");
  }

  const gameCode = resolveGameCodeForPlatformPair(pmSource, pmTarget, cmHint);

  const alignment = analyzeSideAlignment(pmSource.home, pmSource.away, refHome, refAway);
  let reversed;
  if (typeof reversedInput === "boolean") {
    reversed = reversedInput;
  }
  else if (alignment.mode === "aligned") {
    reversed = false;
  }
  else if (alignment.mode === "reversed") {
    reversed = true;
  }
  else {
    throw new Error("无法自动判断主客是否一致，请在确认框中选择「主客一致」或「主客颠倒」");
  }

  const mapResults = [];
  for (const pm of [pmSource, pmTarget]) {
    mapResults.push(...await writeTeamMapsIdentityForPlatform(pm, gameCode));
  }

  const targetAlign = analyzeSideAlignment(pmTarget.home, pmTarget.away, refHome, refAway);
  let targetReversed = false;
  if (targetAlign.mode === "reversed")
    targetReversed = true;

  for (const pm of [pmSource, pmTarget]) {
    await db.setPlatformMatchId(pm.platform, pm.source_match_id, cmId, { force: true });
  }

  await db.patchClientMatchMatchs(cmId, {
    [pmSource.platform]: String(pmSource.source_match_id),
    [pmTarget.platform]: String(pmTarget.source_match_id),
  });

  await persistPlatformSideOverride(cmId, pmSource.platform, reversed);
  if (targetAlign.mode === "aligned" || targetAlign.mode === "reversed") {
    await persistPlatformSideOverride(cmId, pmTarget.platform, targetReversed);
  }

  const cmRow = await db.fetchClientMatchRow(cmId, "id,matchs");
  store.patchCollectorMatchClientIds([{
    ID: cmId,
    Matchs: cmRow?.matchs || {},
  }]);

  invalidateTeamMappings();
  invalidateMatcherRdsSnapshot(["platformMatches", "clientMatches"]);
  const matchMerge = await matchMergeOnce({ afterInFlight: true });

  return {
    ok: true,
    linkType: "platform",
    platform: preview.platform,
    source_match_id: preview.sourceMatchId,
    target_platform: preview.targetPlatform,
    target_match_id: preview.targetMatchId,
    client_match_id: cmId,
    reversed,
    targetReversed,
    sideAlignment: alignment.mode,
    targetSideAlignment: targetAlign.mode,
    gameCode,
    teams: { home: refHome, away: refAway },
    title: refTeamsPick.title,
    teamMapsWritten: mapResults.filter(r => !r.skipped).length,
    matchMerge,
    summary: `${preview.platform} #${preview.sourceMatchId} ↔ ${preview.targetPlatform} #${preview.targetMatchId} → 赛事 ${cmId}（${refHome} vs ${refAway}）`,
    logLines: [
      `平台赛事关联成功 · client_match #${cmId}`,
      `${preview.platform} #${preview.sourceMatchId} ↔ ${preview.targetPlatform} #${preview.targetMatchId}`,
      `赛事 ${refHome} vs ${refAway} · 主客${reversed ? "颠倒" : "一致"}（${alignment.mode}）`,
      `游戏 ${gameCode} · ${formatTeamMapLogLine(mapResults)}`,
    ],
  };
}

function normalizeStoredTeamPlatformId(platform, platformId, { sourceGameId, gameCode } = {}) {
  const pid = String(platformId || "").trim();
  if (!pid || platform !== "PB")
    return pid;
  const gameSlug
    = String(sourceGameId || "").trim()
      || (gameCode ? getPlatformGameId("PB", gameCode) : null)
      || "";
  return formatPbTeamPlatformId(gameSlug, pid, gameCode);
}

async function upsertTeamPlatformRecord(platform, platformId, platformName, gameCode, sourceGameId) {
  const pid = normalizeStoredTeamPlatformId(platform, platformId, { sourceGameId, gameCode });
  if (!pid)
    return { skipped: true, reason: "no_platform_id" };

  await db.upsertTeamPlatformMaps([
    {
      venue: String(platform),
      venue_team_id: pid,
      venue_name: String(platformName || "").trim() || pid,
      game: gameCode,
      source: "manual",
      confidence: 1.0,
    },
  ]);
  return { skipped: false, hasGbTeamId: false };
}

/** 手动匹配：写入 gb_team_id 映射 */
async function upsertManualTeamPlatformMap(gbTeamId, platform, platformId, platformName, gameCode, sourceGameId) {
  const pid = normalizeStoredTeamPlatformId(platform, platformId, { sourceGameId, gameCode });
  if (!pid)
    return { skipped: true, reason: "no_platform_id" };
  const id = parseGbTeamId(gbTeamId);
  if (id == null)
    throw new Error("gb_team_id 无效");

  await db.upsertTeamPlatformMaps([
    {
      gb_team_id: id,
      venue: String(platform),
      venue_team_id: pid,
      venue_name: String(platformName || "").trim() || pid,
      game: gameCode,
      source: "manual",
      confidence: 1.0,
    },
  ]);
  return { skipped: false, hasGbTeamId: true };
}

/** 比赛连线：已有 gb 则沿用；队名有效则自动 resolve/create canonical，否则待识别 */
async function upsertTeamMapForMatchLink(platform, platformId, platformName, gameCode, sourceGameId) {
  const pid = normalizeStoredTeamPlatformId(platform, platformId, { sourceGameId, gameCode });
  if (!pid)
    return { skipped: true, reason: "no_platform_id" };

  const name = String(platformName || "").trim() || pid;
  const existing = await fetchTeamPlatformMap(platform, pid);
  let gbTeamId = parseGbTeamId(existing?.gb_team_id);

  if (gbTeamId == null && !isPlaceholderTeamName(name)) {
    try {
      gbTeamId = await resolveOrCreateManualTeam(gameCode, name);
    }
    catch {
      gbTeamId = null;
    }
  }

  if (gbTeamId != null) {
    return upsertManualTeamPlatformMap(gbTeamId, platform, pid, name, gameCode, sourceGameId);
  }
  return upsertTeamPlatformRecord(platform, platformId, platformName, gameCode, sourceGameId);
}

function formatTeamMapLogLine(mapResults) {
  const written = (mapResults || []).filter(r => !r.skipped);
  const gbCount = written.filter(r => r.hasGbTeamId).length;
  const pendingCount = written.length - gbCount;
  if (gbCount && pendingCount) {
    return `写入 team_venue_maps ${written.length} 条（${gbCount} 含 gb_team_id，${pendingCount} 待识别）`;
  }
  if (gbCount)
    return `写入 team_venue_maps ${gbCount} 条（含 gb_team_id）`;
  return `写入 team_venue_maps ${written.length} 条（待识别，无 gb_team_id）`;
}

async function previewLinkAlignment({ platform, sourceMatchId, clientMatchId }) {
  const plat = String(platform || "").trim();
  const srcId = String(sourceMatchId || "").trim();
  const cmId = Number(clientMatchId);
  if (!plat || !srcId || !Number.isFinite(cmId)) {
    throw new Error("参数不完整");
  }

  const pm = await fetchPlatformMatchRow(plat, srcId);

  const cm = await db.fetchClientMatchRow(cmId, "id,title,game,game_id,matchs,bets");
  if (!cm)
    throw new Error("目标已匹配赛事不存在");

  const allPm = await db.fetchPlatformMatchesHomeAway();
  const platformsById = {};
  for (const row of allPm || []) {
    platformsById[`${row.platform}:${row.source_match_id}`] = row;
  }

  const teams = await resolveClientTeams(cm, pm, platformsById);
  if (!teams)
    throw new Error("无法解析目标赛事的主客队");

  const alignment = analyzeSideAlignment(pm.home, pm.away, teams.home, teams.away);
  return {
    platform: plat,
    sourceMatchId: srcId,
    clientMatchId: cmId,
    platformTeams: {
      home: pm.home,
      away: pm.away,
      home_id: pm.home_id,
      away_id: pm.away_id,
    },
    systemTeams: teams,
    alignment,
    suggestedReversed: alignment.reversed,
  };
}

async function linkPlatformToClientMatch({ platform, sourceMatchId, clientMatchId, reversed: reversedInput }) {
  const plat = String(platform || "").trim();
  const srcId = String(sourceMatchId || "").trim();
  const cmId = Number(clientMatchId);
  if (!plat || !srcId || !Number.isFinite(cmId)) {
    throw new Error("参数不完整");
  }

  const pm = await fetchPlatformMatchRow(plat, srcId);

  const cm = await db.fetchClientMatchRow(cmId, "id,title,game,game_id,matchs,bets");
  if (!cm)
    throw new Error("目标已匹配赛事不存在");

  const allPm = await db.fetchPlatformMatchesHomeAway();
  const platformsById = {};
  for (const row of allPm || []) {
    platformsById[`${row.platform}:${row.source_match_id}`] = row;
  }

  const teams = await resolveClientTeams(cm, pm, platformsById);
  if (!teams)
    throw new Error("无法解析目标赛事的主客队");

  let gameCode = gameCodeForPlatform(plat, pm.source_game_id);
  if (!gameCode) {
    const gid = String(cm.game_id || "").trim();
    const a8Map = { 1: "lol", 2: "dota2", 3: "cs2", 4: "kog", 8: "valorant" };
    gameCode = a8Map[gid] || a8Map[Number(gid)] || null;
  }
  if (!gameCode) {
    const parsed = String(cm.game || "").match(/\(([^)]+)\)\s*$/);
    gameCode = parsed ? parsed[1].toLowerCase() : "unknown";
  }

  const alignment = analyzeSideAlignment(pm.home, pm.away, teams.home, teams.away);
  let reversed;
  if (typeof reversedInput === "boolean") {
    reversed = reversedInput;
  }
  else if (alignment.mode === "aligned") {
    reversed = false;
  }
  else if (alignment.mode === "reversed") {
    reversed = true;
  }
  else {
    throw new Error("无法自动判断主客是否一致，请在确认框中选择「主客一致」或「主客颠倒」");
  }

  const mapResults = await writeTeamMapsIdentityForPlatform(pm, gameCode);

  await db.setPlatformMatchId(plat, srcId, cmId, { force: true });
  const patched = await db.patchClientMatchMatchs(cmId, { [plat]: srcId });
  await persistPlatformSideOverride(cmId, plat, reversed);

  store.patchCollectorMatchClientIds([{
    ID: cmId,
    Matchs: patched.matchs,
  }]);

  invalidateTeamMappings();
  invalidateMatcherRdsSnapshot(["platformMatches", "clientMatches"]);
  const matchMerge = await matchMergeOnce({ afterInFlight: true });

  resolveClientGame(plat, pm.source_game_id);

  return {
    ok: true,
    platform: plat,
    source_match_id: srcId,
    client_match_id: cmId,
    reversed,
    sideAlignment: alignment.mode,
    gameCode,
    teams: { home: teams.home, away: teams.away },
    platformTeams: { home: pm.home, away: pm.away },
    platformTeamIds: { home: String(pm.home_id || ""), away: String(pm.away_id || "") },
    teamMapsWritten: mapResults.filter(r => !r.skipped).length,
    matchMerge,
    summary: `${plat} #${srcId} → 赛事 ${cmId}（${teams.home} vs ${teams.away}）`,
    logLines: [
      `赛事关联成功 · client_match #${cmId}`,
      `${plat} #${srcId} · ${pm.home} vs ${pm.away}`,
      `对齐 ${teams.home} vs ${teams.away} · 主客${reversed ? "颠倒" : "一致"}（${alignment.mode}）`,
      `游戏 ${gameCode} · ${formatTeamMapLogLine(mapResults)}`,
    ],
  };
}

async function fetchTeamPlatformMap(platform, platformId) {
  return db.fetchTeamPlatformMap(platform, platformId);
}

function validateTeamLinkPair(a, b) {
  const platA = String(a?.platform || "").trim();
  const platB = String(b?.platform || "").trim();
  const idA = String(a?.platformId || "").trim();
  const idB = String(b?.platformId || "").trim();
  if (!platA || !platB || !idA || !idB)
    throw new Error("平台队伍 ID 不完整");
  if (platA === platB && idA === idB)
    throw new Error("不能关联同一支队伍");
  if (platA === platB) {
    throw new Error(
      `不能关联同一平台的两支队伍\n${platA} · ${String(a?.platformName || idA).trim()} (id ${idA})\n↔\n${platA} · ${String(b?.platformName || idB).trim()} (id ${idB})\n\n请拖到另一个平台的圆点`,
    );
  }
  const gameCode = String(a?.gameCode || b?.gameCode || "").trim();
  if (!gameCode || gameCode === "unknown")
    throw new Error("无法解析游戏类型");
  return { platA, platB, idA, idB, gameCode };
}

async function countTeamMapsForGbId(gbTeamId) {
  return db.countTeamMapsForGbId(gbTeamId);
}

/** 将较大 gb_team_id 下的全部 platform 映射改写到较小编号 */
async function reassignGbTeamId(fromId, toId) {
  return db.reassignGbTeamId(fromId, toId);
}

function resolveTeamLinkGbPlan(gbA, gbB) {
  if (gbA && gbB && gbA !== gbB) {
    const targetGb = Math.min(gbA, gbB);
    const loserGb = Math.max(gbA, gbB);
    return { mode: "merge", targetGb, loserGb, gbTeamIdAllocated: false };
  }
  if (gbA && gbB) {
    return { mode: "same", targetGb: gbA, loserGb: null, gbTeamIdAllocated: false };
  }
  if (gbA || gbB) {
    return { mode: "reuse_one", targetGb: gbA || gbB, loserGb: null, gbTeamIdAllocated: false };
  }
  return { mode: "new", targetGb: null, loserGb: null, gbTeamIdAllocated: true };
}

/** 拖线前预览：说明将采用的 gb_team_id 及合并影响 */
async function previewLinkPlatformTeams({ a, b }) {
  const { platA, platB, idA, idB, gameCode } = validateTeamLinkPair(a, b);
  const normA = normalizeStoredTeamPlatformId(platA, idA, { gameCode });
  const normB = normalizeStoredTeamPlatformId(platB, idB, { gameCode });
  const mapA = await fetchTeamPlatformMap(platA, normA);
  const mapB = await fetchTeamPlatformMap(platB, normB);
  const gbA = parseGbTeamId(mapA?.gb_team_id);
  const gbB = parseGbTeamId(mapB?.gb_team_id);
  const plan = resolveTeamLinkGbPlan(gbA, gbB);
  const nameA = String(a?.platformName || mapA?.venue_name || idA).trim();
  const nameB = String(b?.platformName || mapB?.venue_name || idB).trim();

  let mapsReassigned = 0;
  if (plan.mode === "merge" && plan.loserGb != null) {
    mapsReassigned = await countTeamMapsForGbId(plan.loserGb);
  }

  return {
    ok: true,
    game: gameCode,
    mode: plan.mode,
    target_gb_team_id: plan.targetGb,
    loser_gb_team_id: plan.loserGb,
    maps_reassigned: mapsReassigned,
    will_allocate_gb_team_id: plan.gbTeamIdAllocated,
    team_a: {
      venue: platA,
      venue_team_id: normA,
      venue_name: nameA,
      gb_team_id: gbA,
      pending: Boolean(mapA && mapA.gb_team_id == null),
    },
    team_b: {
      venue: platB,
      venue_team_id: normB,
      venue_name: nameB,
      gb_team_id: gbB,
      pending: Boolean(mapB && mapB.gb_team_id == null),
    },
  };
}

/** 关联两平台的队伍 ID 到同一 canonical，并 matchMerge 使 ID 合并立即生效 */
async function linkPlatformTeams({ a, b }) {
  const { platA, platB, idA, idB, gameCode } = validateTeamLinkPair(a, b);
  const normA = normalizeStoredTeamPlatformId(platA, idA, { gameCode });
  const normB = normalizeStoredTeamPlatformId(platB, idB, { gameCode });
  const mapA = await fetchTeamPlatformMap(platA, normA);
  const mapB = await fetchTeamPlatformMap(platB, normB);
  const gbA = parseGbTeamId(mapA?.gb_team_id);
  const gbB = parseGbTeamId(mapB?.gb_team_id);
  const plan = resolveTeamLinkGbPlan(gbA, gbB);

  let gbTeamId = plan.targetGb;
  let mapsReassigned = 0;
  if (plan.mode === "merge" && plan.loserGb != null && gbTeamId != null) {
    mapsReassigned = await reassignGbTeamId(plan.loserGb, gbTeamId);
  }

  if (!gbTeamId) {
    const pickName = String(a?.platformName || mapA?.venue_name || b?.platformName || mapB?.venue_name || "").trim();
    if (!pickName || isPlaceholderTeamName(pickName))
      throw new Error("队名为空，无法创建 canonical");
    try {
      gbTeamId = await resolveOrCreateManualTeam(gameCode, pickName);
    }
    catch (err) {
      const head = [
        "队伍关联失败：需要为标准队伍分配 gb_team_id",
        `A ${platA} · ${String(a?.platformName || mapA?.venue_name || idA).trim()}`,
        `B ${platB} · ${String(b?.platformName || mapB?.venue_name || idB).trim()}`,
        `游戏 ${gameCode} · 选用队名「${pickName}」`,
      ].join("\n");
      throw new Error(`${head}\n${err.message}`);
    }
  }

  const nameA = String(a?.platformName || mapA?.venue_name || idA).trim();
  const nameB = String(b?.platformName || mapB?.venue_name || idB).trim();

  const written = [];
  written.push(await upsertManualTeamPlatformMap(gbTeamId, platA, normA, nameA, gameCode));
  written.push(await upsertManualTeamPlatformMap(gbTeamId, platB, normB, nameB, gameCode));

  invalidateTeamMappings();
  const matchMerge = await matchMergeOnce({ afterInFlight: true });

  const label = String(gbTeamId);
  const mapsWritten = written.filter(r => !r.skipped).length;
  let gbNote = "沿用已有 gb_team_id";
  if (plan.gbTeamIdAllocated) {
    gbNote = "新分配 gb_team_id";
  }
  else if (plan.mode === "merge") {
    gbNote = `合并 gb_team_id ${plan.loserGb} → ${label}（较小编号为准，已改写 ${mapsReassigned} 条映射）`;
  }
  else if (plan.mode === "same") {
    gbNote = "两队已同属该 gb_team_id，刷新映射";
  }
  else if (gbA || gbB) {
    gbNote = "沿用一侧已有 gb_team_id";
  }

  return {
    ok: true,
    action: "link_team",
    gb_team_id: label,
    gb_team_id: label,
    gb_team_id_allocated: plan.gbTeamIdAllocated,
    gb_team_id_merged: plan.mode === "merge",
    gb_team_id_loser: plan.loserGb,
    maps_reassigned: mapsReassigned,
    game: gameCode,
    team_a: { venue: platA, venue_team_id: normA, venue_name: nameA },
    team_b: { venue: platB, venue_team_id: normB, venue_name: nameB },
    teamMapsWritten: mapsWritten,
    matchMerge,
    summary: `${platA} · ${nameA} ↔ ${platB} · ${nameB} → gb_team_id ${label}`,
    logLines: [
      `队伍关联成功 · gb_team_id ${label}（${gbNote}）`,
      `A ${platA} · ${nameA} · 平台 id ${idA}`,
      `B ${platB} · ${nameB} · 平台 id ${idB}`,
      `游戏 ${gameCode} · 写入 team_venue_maps ${mapsWritten} 条 · updated_by 手动`,
      `赛事合并完成 · client_matches ${matchMerge.matchCount} 场`,
    ],
  };
}

async function registerTeamPlatformMap({ platform, platformId, platformName, gameCode }) {
  const plat = String(platform || "").trim();
  const pid = String(platformId || "").trim();
  const name = String(platformName || "").trim() || pid;
  const game = String(gameCode || "").trim();
  if (!plat || !pid)
    throw new Error("平台队伍 ID 不完整");
  if (!game || game === "unknown")
    throw new Error(`无法解析游戏类型（${plat} · ${name}）`);

  const storedPid = normalizeStoredTeamPlatformId(plat, pid, { gameCode });
  const existing = await db.fetchTeamPlatformMap(plat, storedPid);

  if (existing) {
    const displayName = String(existing.venue_name || name).trim() || storedPid;
    const gameLabel = String(existing.game || game).trim() || game;
    if (existing.gb_team_id != null) {
      const err = new Error(
        `无需重复收录\n${plat} · ${displayName}\n平台 id ${storedPid} · 游戏 ${gameLabel}\n已有 gb_team_id ${existing.gb_team_id}`,
      );
      err.code = "already_registered";
      throw err;
    }
    const err = new Error(
      `无需重复收录\n${plat} · ${displayName}\n平台 id ${storedPid} · 游戏 ${gameLabel}\n已在 team_venue_maps，状态：待识别`,
    );
    err.code = "already_registered";
    throw err;
  }

  const result = await upsertTeamPlatformRecord(plat, pid, name, game);
  if (result.skipped)
    throw new Error("平台队伍 ID 不完整");

  invalidateTeamMappings();

  return {
    ok: true,
    action: "register_team_map",
    platform: plat,
    venue_team_id: pid,
    venue_name: name,
    game,
    status: "pending",
    summary: `${plat} · ${name} (id ${pid}) · ${game} → team_venue_maps（待识别）`,
    detail: `队伍「${name}」已收录，尚无 gb_team_id`,
    logLines: [
      `队伍收录成功 · 待识别（无 gb_team_id）`,
      `${plat} · ${name}`,
      `平台 id ${pid} · 游戏 ${game}`,
      `已写入 team_venue_maps`,
    ],
  };
}

/**
 * 手动主客反转：写入 client_match_platform_overrides，下轮 reconcile 派生 Reverse/Sources。
 */
async function setClientMatchPlatformSideOverride({ clientMatchId, platform, reversed }) {
  const cmId = Number(clientMatchId);
  const plat = String(platform || "").trim();
  const wantReversed = !!reversed;
  if (!Number.isFinite(cmId) || cmId <= 0)
    throw new Error("无效的赛事 ID");
  if (!plat)
    throw new Error("平台不能为空");

  const cm = await db.fetchClientMatchRow(cmId, "id,title,matchs");
  if (!cm)
    throw new Error("赛事不存在");

  const matchs = cm.matchs && typeof cm.matchs === "object" ? cm.matchs : {};
  const srcId = String(matchs[plat] || "").trim();
  if (!srcId)
    throw new Error(`赛事 ${cmId} 未关联平台 ${plat}`);

  const pm = await fetchPlatformMatchRow(plat, srcId);
  const { mode } = await persistPlatformSideOverride(cmId, plat, wantReversed);

  return {
    ok: true,
    id: cmId,
    platform: plat,
    reversed: wantReversed,
    mode,
    summary: `${plat} 主客方向已${wantReversed ? "标记反转" : "恢复正向"}（platform override）`,
    logLines: [
      `手动主客反转 · client_match #${cmId} · ${plat} #${srcId}`,
      `Title ${cm.title || ""} · 平台 ${pm.home} vs ${pm.away}`,
      `override ${mode}`,
    ],
  };
}

/**
 * 对调场次 gb 锁（Title 主客翻转）；与单平台 force_reversed 不同。
 */
async function swapClientMatchGbOrientation({ clientMatchId }) {
  const cmId = Number(clientMatchId);
  if (!Number.isFinite(cmId) || cmId <= 0)
    throw new Error("无效的赛事 ID");

  const before = await db.fetchClientMatchRow(cmId, "id,title,home_gb_team_id,away_gb_team_id");
  if (!before)
    throw new Error("赛事不存在");

  const update = await db.swapClientMatchGbOrientation(cmId);
  return {
    ok: true,
    ...update,
    summary: `场次 #${cmId} 主客锁已对调：${update.title}`,
    logLines: [
      `对调 gb 锁 · client_match #${cmId}`,
      `原 Title ${before.title || ""} · home_gb=${before.home_gb_team_id} away_gb=${before.away_gb_team_id}`,
      `新 Title ${update.title} · home_gb=${update.home_gb_team_id} away_gb=${update.away_gb_team_id}`,
    ],
  };
}

