#!/usr/bin/env node
/** [changmen 扩展] Build a self-contained Node artifact from the server-owned resource root. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";
import { BACKEND_ROOT, VENUE_ADAPTER_ROOT } from "@changmen/storage/paths.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);
// A copied artifact owns registry/paths.js beside scripts/. A workspace tool uses
// the registry package's declared resource tree, even if its generated catalog is stale.
const ADAPTER_PKG_ROOT = fs.existsSync(path.join(__dirname, "../registry/paths.js"))
  ? path.resolve(__dirname, "..") : VENUE_ADAPTER_ROOT;
const LEGACY_TOOL_FACADE = "#!/usr/bin/env node\nimport path from \"node:path\";\nimport { pathToFileURL } from \"node:url\";\nimport { syncPlatformAdapterBackendBundle } from \"../../../server/packages/venue-adapter-tools/sync-backend-bundle.mjs\";\nexport * from \"../../../server/packages/venue-adapter-tools/sync-backend-bundle.mjs\";\n\nif (process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {\n  console.log(`[sync-platform-adapter] ${syncPlatformAdapterBackendBundle()}`);\n}\n";
const ADAPTER_INFRA = new Set(["registry", "loader", "shared", "contract", "scripts", "_template", "node_modules"]);
const ENTRIES = [
  ["loader/adapter_paths.mjs", "@changmen/venue-node-loader", [
    'export * from "../../../server/packages/venue-node-loader/adapter_paths.mjs";\n',
  ]],
  ["registry/paths.js", "@changmen/venue-node-registry/paths.js", [
    'export * from "../../paths.js";\n',
    'export * from "../../../server/packages/venue-node-registry/paths.js";\n',
  ]],
  ["registry/feeds.js", "@changmen/venue-node-registry/feeds.js", [
    'export * from "../../feeds.js";\n',
    'export * from "../../../server/packages/venue-node-registry/feeds.js";\n',
  ]],
  ["scripts/sync-backend-bundle.mjs", null, [LEGACY_TOOL_FACADE]],
];
function cpDir(src, dst) {
  fs.mkdirSync(dst, { recursive: true });
  for (const name of fs.readdirSync(src)) {
    if (name === "_template") continue;
    const from = path.join(src, name), to = path.join(dst, name);
    if (fs.statSync(from).isDirectory()) cpDir(from, to);
    else fs.copyFileSync(from, to);
  }
}
/** @param {{dst?: string, src?: string, includeBrowserSources?: boolean}} [options] */
export function syncPlatformAdapterBackendBundle(options = {}) {
  const src = options.src ?? ADAPTER_PKG_ROOT;
  const dst = options.dst ?? path.join(BACKEND_ROOT, "platform_adapter");
  const isDefault = path.resolve(src) === path.resolve(ADAPTER_PKG_ROOT);
  const manifestSource = isDefault ? require.resolve("@changmen/shared/catalog/venue_manifest.json")
    : path.join(src, "registry", "manifest.json");
  if (!fs.existsSync(manifestSource)) throw new Error(`platform-adapter source missing manifest: ${src}`);
  const manifestBytes = fs.readFileSync(manifestSource);
  const realSource = fs.realpathSync(src), target = fs.existsSync(dst) ? fs.realpathSync(dst) : path.resolve(dst);
  const contains = (a, b) => { const rel = path.relative(a, b); return !rel || rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel); };
  if (contains(realSource, target) || contains(target, realSource)) throw Error("Bundle source and destination must not overlap");
  // Resolve all required implementation bytes before replacing an existing artifact.
  const materialized = [];
  for (const [relative, spec, facades] of ENTRIES) {
    const input = path.join(src, relative), present = fs.existsSync(input);
    if (!present && !isDefault) continue;
    if (present && !facades.includes(fs.readFileSync(input, "utf8").replaceAll("\r\n", "\n"))) continue;
    const implementation = spec ? require.resolve(spec) : fileURLToPath(import.meta.url);
    materialized.push([relative, fs.readFileSync(implementation)]);
  }
  if (fs.existsSync(dst)) fs.rmSync(dst, { recursive: true, force: true });
  fs.mkdirSync(dst, { recursive: true });
  for (const name of fs.readdirSync(src)) {
    if (name === "_template") continue;
    const from = path.join(src, name), to = path.join(dst, name);
    if (!fs.statSync(from).isDirectory()) fs.copyFileSync(from, to);
    else if (ADAPTER_INFRA.has(name) || options.includeBrowserSources) cpDir(from, to);
  }
  for (const [relative, bytes] of materialized) {
    const target = path.join(dst, relative); fs.mkdirSync(path.dirname(target), { recursive: true }); fs.writeFileSync(target, bytes);
  }
  fs.mkdirSync(path.join(dst, "registry"), { recursive: true });
  fs.writeFileSync(path.join(dst, "registry", "manifest.json"), manifestBytes);
  return dst;
}
if (process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {
  console.log(`[sync-platform-adapter] ${syncPlatformAdapterBackendBundle()}`);
}

import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { BACKEND_ROOT, CHANGMEN_ROOT, VENUE_ADAPTER_ROOT } from "@changmen/storage/paths.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const require = createRequire(import.meta.url);

const LOADER_DIR = __dirname;
const PLATFORM_ADAPTER_ROOT = path.join(LOADER_DIR, "..");

export { BACKEND_ROOT, CHANGMEN_ROOT };

const RESOLVE_PATHS = [
  path.join(BACKEND_ROOT, "node_modules"),
  path.join(CHANGMEN_ROOT, "node_modules"),
];

/** require `@changmen/shared/{...}` from backend / monorepo node_modules */
export function reqS(...segments) {
  const entry = `@changmen/shared/${segments.join("/")}`;
  return require(require.resolve(entry, { paths: RESOLVE_PATHS }));
}

export function backendRequire(specifier) {
  return require(require.resolve(specifier, { paths: RESOLVE_PATHS }));
}

let _adapterRoot;
let _registryPaths;
let _registryFeeds;
let _registryReady;
/** @type {Map<string, Record<string, unknown>>} */
const _esmPlatformModuleCache = new Map();

/** 仅测试 / 瘦包调试：清空根目录与 registry 缓存 */
export function resetAdapterRootForTests() {
  if (_registryPaths?.resetPlatformNodeRootForTests) {
    _registryPaths.resetPlatformNodeRootForTests();
  }
  _adapterRoot = undefined;
  _registryPaths = undefined;
  _registryFeeds = undefined;
  _registryReady = undefined;
  _esmPlatformModuleCache.clear();
}

/**
 * platform-adapter 根目录。
 * - 显式：`CHANGMEN_ADAPTER_ROOT`（瘦包 / 测试；兼容 `GAMEBET_ADAPTER_ROOT`）
 * - 开发：`changmen/packages/venue-adapter`（workspace 包）
 * - 可选拷贝：`server/backend/platform_adapter`（`npm run sync:platform-adapter`）
 */
export function getAdapterRoot() {
  if (_adapterRoot) return _adapterRoot;

  const forced = (
    process.env.CHANGMEN_ADAPTER_ROOT
    || process.env.GAMEBET_ADAPTER_ROOT
  )?.trim();
  if (forced) {
    const abs = path.resolve(forced);
    if (fs.existsSync(path.join(abs, "registry", "manifest.json"))) {
      _adapterRoot = abs;
      return _adapterRoot;
    }
    throw new Error(`CHANGMEN_ADAPTER_ROOT invalid (no registry/manifest.json): ${abs}`);
  }

  if (fs.existsSync(path.join(VENUE_ADAPTER_ROOT, "registry", "manifest.json"))) {
    _adapterRoot = VENUE_ADAPTER_ROOT;
    return _adapterRoot;
  }

  if (fs.existsSync(path.join(PLATFORM_ADAPTER_ROOT, "registry", "manifest.json"))) {
    _adapterRoot = PLATFORM_ADAPTER_ROOT;
    return _adapterRoot;
  }

  const bundled = path.join(BACKEND_ROOT, "platform_adapter");
  if (fs.existsSync(path.join(bundled, "registry", "manifest.json"))) {
    _adapterRoot = bundled;
    return _adapterRoot;
  }

  const legacy = path.join(CHANGMEN_ROOT, "platform_adapter");
  if (fs.existsSync(path.join(legacy, "registry", "manifest.json"))) {
    _adapterRoot = legacy;
    return _adapterRoot;
  }

  throw new Error(
    "venue-adapter not found: expected CHANGMEN_LAYOUT.venueAdapter (dev) or server/backend/platform_adapter (packaged)",
  );
}

/** 预加载 registry ESM（paths.js / feeds.js）；server 入口须在加载 http_routes 前 await */
export async function initAdapterRegistry() {
  if (_registryReady) return _registryReady;

  _registryReady = (async () => {
    const root = getAdapterRoot();
    const registryDir = path.join(root, "registry");
    const pathsUrl = pathToFileURL(path.join(registryDir, "paths.js")).href;
    const feedsUrl = pathToFileURL(path.join(registryDir, "feeds.js")).href;
    _registryPaths = await import(pathsUrl);
    _registryFeeds = await import(feedsUrl);
  })();

  return _registryReady;
}

function ensureRegistryLoaded() {
  if (!_registryPaths || !_registryFeeds) {
    throw new Error(
      "platform_adapter registry not loaded; await initAdapterRegistry() before adapterRequire(registry/*)",
    );
  }
}

/** require(platform_adapter 下的相对路径片段) — 平台 backend 仍为 CJS */
export function adapterRequire(...segments) {
  const key = segments.join("/");
  if (key === "registry/paths.js") {
    ensureRegistryLoaded();
    return _registryPaths;
  }
  if (key === "registry/feeds.js") {
    ensureRegistryLoaded();
    return _registryFeeds;
  }
  return require(path.join(getAdapterRoot(), ...segments));
}

export function getRegistryPaths() {
  ensureRegistryLoaded();
  return _registryPaths;
}

export function resolvePlatformFile(id, ...segments) {
  return getRegistryPaths().resolvePlatformFile(id, ...segments);
}

/** 预加载已迁 ESM 的平台顶层 *.js（`@changmen/platform-probes/{platform}/`） */
export async function initEsmPlatformBackends() {
  ensureRegistryLoaded();
  const nodeRoot = _registryPaths.getPlatformNodeRoot();
  for (const entry of _registryPaths.MANIFEST) {
    const backendDir = path.join(nodeRoot, entry.dir);
    const pkgPath = path.join(backendDir, "package.json");
    if (!fs.existsSync(pkgPath)) continue;
    let pkg;
    try {
      pkg = JSON.parse(fs.readFileSync(pkgPath, "utf8"));
    } catch {
      continue;
    }
    if (pkg.type !== "module") continue;
    for (const file of fs.readdirSync(backendDir)) {
      if (!file.endsWith(".js") || file.startsWith("_")) continue;
      const abs = path.join(backendDir, file);
      if (!fs.statSync(abs).isFile()) continue;
      if (!_esmPlatformModuleCache.has(abs)) {
        _esmPlatformModuleCache.set(abs, await import(pathToFileURL(abs).href));
      }
    }
  }
}

function loadPlatformModule(abs) {
  if (_esmPlatformModuleCache.has(abs)) {
    return _esmPlatformModuleCache.get(abs);
  }
  try {
    return require(abs);
  } catch (err) {
    if (err?.code === "ERR_REQUIRE_ESM") {
      throw new Error(
        `ESM platform module not preloaded: ${abs} (await initEsmPlatformBackends())`,
      );
    }
    throw err;
  }
}

/** require(platform_adapter/{dir}/...) — ESM 平台走预加载缓存 */
export function requirePlatform(id, ...segments) {
  return loadPlatformModule(resolvePlatformFile(id, ...segments));
}

await initAdapterRegistry();
await initEsmPlatformBackends();

